export const STAGES = [{"id":"sale","label":"Selling goods"},{"id":"shipping","label":"Ships and cargo"},{"id":"finance","label":"Paying, securing, insuring"},{"id":"contract","label":"Contracts"},{"id":"disputes","label":"Courts and arbitration"},{"id":"property","label":"Property and equity"},{"id":"wrongs","label":"Wrongs and crimes"},{"id":"reading","label":"Reading the law"},{"id":"states","label":"States and trade rules"},{"id":"companies","label":"Companies and agents"}];
export const MATHS = [
{"id":"LW-H01","lv":"sale","d":4,"area":"Selling goods","q":"Under Incoterms 2020 FOB, risk passes from seller to buyer when the goods are","o":["handed to the first carrier at the seller's premises","placed on board the vessel at the port of loading","unloaded onto the quay at the port of discharge","cleared for export and ready at the terminal gate"],"a":[1],"s":1,"x":"Since 2010 it is on board, not 'over the ship's rail'. The buyer books the ship and insures the voyage, and ownership may pass later.","about":["fob"]},
{"id":"LW-H02","lv":"sale","d":5,"area":"Selling goods","q":"A CIF seller must insure the cargo for at least","o":["100% of the contract price","105% of the contract price","110% of the contract price","120% of the contract price"],"a":[2],"s":1,"x":"Incoterms 2020: 110% of the price in the contract, in the contract's currency, with the buyer able to claim under the policy. A buyer who wants more must ask for it.","about":["cif"]},
{"id":"LW-H03","lv":"sale","d":6,"area":"Selling goods","q":"Incoterms 2020 raised the insurance a CIP seller must buy to Institute Cargo Clauses (A). For CIF the minimum stays","o":["Institute Cargo Clauses (A)","Institute Cargo Clauses (B)","Institute Cargo Clauses (C)","Institute War Clauses (Cargo)"],"a":[2],"s":1,"x":"Clauses (C), the shortest list of named perils. The ICC kept it for CIF because the term is much used for bulk commodities, where cheap cover is the custom; CIP, used more for manufactured goods, went to all risks.","about":["cif","incoterms"]},
{"id":"LW-H04","lv":"sale","d":4,"area":"Selling goods","q":"Which of these Incoterms 2020 can be used for any mode of transport, not only sea?","o":["FOB","CFR","CIF","FCA"],"a":[3],"s":1,"x":"FOB, CFR, CIF and FAS are for sea and inland waterways only. A container handed over at an inland terminal is delivered long before it's on board, so FCA suits it better than FOB.","about":["incoterms"]},
{"id":"LW-H05","lv":"sale","d":5,"area":"Selling goods","q":"Incoterms 2020 renamed DAT (delivered at terminal) as","o":["DAP, delivered at place","DDU, delivered duty unpaid","DPU, delivered at place unloaded","DAF, delivered at frontier"],"a":[2],"s":1,"x":"DAT could only be a terminal; DPU can be any place, with the goods always unloaded by the seller, which is what sets it apart from DAP.","about":["incoterms"]},
{"id":"LW-H06","lv":"sale","d":4,"area":"Selling goods","q":"Under which Incoterm 2020 does the seller have no duty to clear the goods for export?","o":["FCA","FOB","DAP","EXW"],"a":[3],"s":1,"x":"Under EXW the buyer clears the goods for export as well, which is awkward for a buyer abroad who can't. FCA, with the seller clearing them, is the usual fix.","about":["exw"]},
{"id":"LW-H07","lv":"sale","d":4,"area":"Selling goods","q":"A buyer under a CIF contract must pay","o":["once the cargo has arrived and passed inspection","on tender of the documents, even if the cargo has been lost","on tender of the documents, unless the cargo has been lost","once the ship has berthed at the port of discharge"],"a":[1],"s":1,"x":"A CIF sale is a sale of documents: the seller performs by tendering the bill of lading, the policy and the invoice, and the buyer's remedy for a loss is the insurance (Manbre Saccharine v Corn Products, 1919).","about":["cif"]},
{"id":"LW-H08","lv":"sale","d":5,"area":"Selling goods","q":"Under the CISG, a reply to an offer that changes its terms materially is","o":["an acceptance, with the changes struck out","an acceptance, with the changes binding both sides","a counter-offer, which rejects the original offer","an invitation to treat, leaving the offer open"],"a":[2],"s":1,"x":"Article 19: changes to price, payment, quality, quantity, delivery, liability or the settling of disputes are material. The common law reaches the same result (Hyde v Wrench, 1840).","about":["battle-of-the-forms","cisg"]},
{"id":"LW-H09","lv":"sale","d":5,"area":"Selling goods","q":"Which of these sales falls outside the CISG?","o":["a vegetable oil cargo sold between two traders","a coffee consignment sold FOB to a roaster abroad","a second-hand ship sold by one owner to another","machine parts bought by a factory in another state"],"a":[2],"s":1,"x":"Article 2 leaves out goods bought for personal, family or household use, sales by auction or by authority of law, stocks, shares, money and negotiable instruments, ships, vessels, hovercraft and aircraft, and electricity.","about":["cisg"]},
{"id":"LW-H10","lv":"finance","d":4,"area":"Paying, securing, insuring","q":"Under UCP 600, a bank has at most how long to examine the documents presented under a credit?","o":["three banking days after the day of presentation","seven banking days after the day of presentation","five banking days after the day of presentation","ten banking days after the day of presentation"],"a":[2],"s":1,"x":"Article 14(b). UCP 500 allowed a reasonable time up to seven banking days; UCP 600 (2007) cut it to five, and a notice of refusal must go out within the same time.","about":["letter-of-credit"]},
{"id":"LW-H11","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"Under UCP 600 a documentary credit is","o":["revocable until the goods ship, then irrevocable","irrevocable: no one can amend or cancel it alone","revocable until a confirming bank adds its promise","irrevocable only once the applicant approves the documents"],"a":[1],"s":1,"x":"Article 2 defines a credit as irrevocable by its nature; the revocable credit of UCP 500 went in 2007, and an amendment needs the issuing bank, any confirming bank and the beneficiary (art. 10).","about":["letter-of-credit"]},
{"id":"LW-H12","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"Unless the credit says otherwise, UCP 600 requires the documents to be presented no later than","o":["14 calendar days after shipment","30 calendar days after shipment","10 banking days after shipment","21 calendar days after shipment"],"a":[3],"s":1,"x":"Article 14(c), and never later than the credit's expiry. Late presentation is among the commonest reasons a bank refuses documents.","about":["letter-of-credit"]},
{"id":"LW-H13","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"If a credit states a condition but names no document to show it, UCP 600 says banks will","o":["refuse to pay until the applicant confirms it in writing","treat the condition as not stated and disregard it","pay, but only against the beneficiary's own certificate","ask the issuing bank which document would satisfy it"],"a":[1],"s":1,"x":"Article 14(h). A condition with no document is a trap for the applicant, who thinks it is protected: if you want it enforced, say what must prove it.","about":["autonomy-principle","letter-of-credit"]},
{"id":"LW-H14","lv":"shipping","d":4,"area":"Ships and cargo","q":"A bill of lading is a receipt for the cargo, evidence of the contract of carriage and","o":["a guarantee of payment, issued by the buyer's bank","a certificate of origin, accepted by customs at import","a document of title, which can pass the cargo by endorsement","a policy of insurance, paying if the cargo is lost"],"a":[2],"s":1,"x":"Being a document of title is what lets a cargo be sold afloat, and what lets a bank hold it as security: whoever holds an original can claim the goods.","about":["bill-of-lading"]},
{"id":"LW-H15","lv":"shipping","d":6,"area":"Ships and cargo","q":"The Hague-Visby limit of liability is the higher of 666.67 SDR a package and how much per kilo of gross weight lost or damaged?","o":["1 SDR","2.5 SDR","3 SDR","2 SDR"],"a":[3],"s":1,"x":"SDR is the IMF's special drawing right, a basket of currencies. Hamburg Rules: 835 SDR a package or 2.5 a kilo. Rotterdam Rules: 875 or 3. A value declared in the bill of lading before shipment lifts the limit.","about":["hague-visby-rules"]},
{"id":"LW-H16","lv":"shipping","d":4,"area":"Ships and cargo","q":"Under the Hague-Visby Rules, a cargo claim against the carrier is barred unless suit is brought within","o":["three months of delivery","two years of delivery","six years of delivery","one year of delivery"],"a":[3],"s":1,"x":"Article III rule 6: one year from delivery, or from when the goods should have been delivered. The parties may agree to extend it once the cause of action has arisen.","about":["hague-visby-rules"]},
{"id":"LW-H17","lv":"shipping","d":4,"area":"Ships and cargo","q":"Despatch is","o":["money the charterer pays the shipowner for time lost at the ports","money the shipowner pays the charterer for time saved at the ports","a bonus the shipowner pays the master for a fast passage","a fee the agent charges for clearing the ship out of port"],"a":[1],"s":1,"x":"Usually half the demurrage rate; it rewards a charterer who loads or discharges faster than laytime allows.","about":["demurrage"]},
{"id":"LW-H18","lv":"shipping","d":5,"area":"Ships and cargo","q":"After a general average is declared, cargo owners are usually asked to sign an average bond and","o":["pay the salvors' full reward in cash at once","release all claims against the carrier for the voyage","provide a guarantee from their cargo insurers","arrange their own tug to tow the cargo ashore"],"a":[2],"s":1,"x":"The shipowner has a lien on the cargo for its share. The bond and guarantee free the cargo; the average adjuster then works out each share, which can take years.","about":["general-average"]},
{"id":"LW-H19","lv":"shipping","d":3,"area":"Ships and cargo","q":"Under a time charter, who normally pays for the fuel the ship burns?","o":["the owner, out of the daily hire","the shipper, with the freight","the owner and the charterer, in equal shares","the charterer, on top of the daily hire"],"a":[3],"s":1,"x":"The charterer buys the bunkers; the fuel on board is reckoned at delivery and redelivery. Under a voyage charter the owner pays and recovers it in the freight.","about":["charter-party"]},
{"id":"LW-H20","lv":"shipping","d":5,"area":"Ships and cargo","q":"'Once on demurrage, always on demurrage' means","o":["a ship on demurrage can't earn despatch on later voyages","demurrage runs until the cargo is paid for in full","events that would stop laytime don't stop demurrage","the owner may claim demurrage again on any later voyage"],"a":[2],"s":1,"x":"Once laytime has run out, an event that would have stopped laytime doesn't stop demurrage unless the charter says so. A charterer who is late is held to its lateness.","about":["demurrage","laytime"]},
{"id":"LW-H21","lv":"contract","d":5,"area":"Contracts","q":"In Hadley v Baxendale (1854) the mill-owner could not recover its lost profits because","o":["the carrier hadn't been told that the delay would stop the mill","lost profits can never be recovered in an action for breach","the mill-owner could have bought a new crankshaft elsewhere","the carrier's delay was not a breach of its contract"],"a":[0],"s":1,"x":"A broken crankshaft was sent to the makers as a pattern for a new one, and the carrier's delay of days kept the mill idle. Only loss that arises naturally, or that both parties had in mind when they contracted, is recoverable.","about":["remoteness"]},
{"id":"LW-H22","lv":"contract","d":4,"area":"Contracts","q":"A contract made under economic duress is","o":["void from the start, as if never made","valid, but the victim may claim damages","valid, but unenforceable for the excess","voidable by the victim, if it acts promptly"],"a":[3],"s":1,"x":"The victim may affirm it or set it aside, and delay loses the right: in The Atlantic Baron (1979) a shipbuilder's threat was enough but the owners had waited too long.","about":["economic-duress"]},
{"id":"LW-H23","lv":"disputes","d":3,"area":"Courts and arbitration","q":"A claim for breach of a simple contract must be brought in England within","o":["one year of the breach","three years of the breach","twelve years of the breach","six years of the breach"],"a":[3],"s":1,"x":"Limitation Act 1980, s 5. A deed gets twelve years (s 8). A written acknowledgement of a debt starts the clock again.","about":["limitation-period"]},
{"id":"LW-H24","lv":"disputes","d":4,"area":"Courts and arbitration","q":"An arbitral award can be enforced under the New York Convention in how many states?","o":["about 120","more than 170","about 90","fewer than 50"],"a":[1],"s":1,"x":"That reach is why commodity disputes go to arbitration: a court judgment has the 2019 Hague Judgments Convention and a patchwork of treaties. The grounds for refusing an award are listed in article V.","about":["new-york-convention"]},
{"id":"LW-H25","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Since the UK's Arbitration Act 2025, unless the parties agree otherwise, the law of an arbitration agreement is that of","o":["the contract it belongs to","the country of the claimant","the seat of the arbitration","the place where the award will be enforced"],"a":[2],"s":1,"x":"New section 6A, in force from 1 August 2025. It reverses Enka v Chubb (2020), where a choice of law for the main contract usually governed the arbitration clause too. Only an express choice for the arbitration agreement itself displaces the seat's law.","about":["seat-of-arbitration"]},
{"id":"LW-H26","lv":"disputes","d":5,"area":"Courts and arbitration","q":"The Mareva injunction takes its name from","o":["a judge who first granted one in a salvage dispute","a Greek shipowner who first asked for one in court","a ship whose owners were chasing unpaid charter hire","a London bank whose accounts were first frozen by one"],"a":[2],"s":1,"x":"Mareva Compania Naviera v International Bulkcarriers (1975): Lord Denning froze the charterers' London bank account. It wasn't the first (Nippon Yusen Kaisha v Karageorgis came weeks earlier) but the name stuck; the power now rests on the Senior Courts Act 1981, s 37.","about":["freezing-injunction"]},
{"id":"LW-H27","lv":"wrongs","d":2,"area":"Wrongs and crimes","q":"In Donoghue v Stevenson (1932), the claimant fell ill after finding what in her bottle of ginger beer?","o":["a dead mouse","a shard of glass","a decomposed snail","a drowned wasp"],"a":[2],"s":1,"x":"Lord Atkin's neighbour principle: take reasonable care to avoid acts you can reasonably foresee would injure your neighbour. The case was decided on the assumption that the snail was there; it was never proved.","about":["duty-of-care"]},
{"id":"LW-H28","lv":"companies","d":4,"area":"Companies and agents","q":"In Salomon v A Salomon & Co, Mr Salomon had lent his company money against a debenture. The House of Lords held that","o":["he was liable for its debts, being its real owner","the company was a separate person, so he was paid first","the debenture was void as he held nearly all the shares","the company was a sham, so all creditors shared equally"],"a":[1],"s":1,"x":"The company was a person apart from its owner, and as a secured creditor Mr Salomon came ahead of the unsecured ones. The principle has been trimmed (Prest v Petrodel, 2013) but is the root of limited liability.","about":["separate-legal-personality"]},
{"id":"LW-H29","lv":"states","d":3,"area":"States and trade rules","q":"Under the UN Convention on the Law of the Sea, a coastal state's territorial sea reaches","o":["3 nautical miles from the coast","24 nautical miles from the coast","12 nautical miles from the coast","200 nautical miles from the coast"],"a":[2],"s":1,"x":"Article 3. In the territorial sea foreign ships have a right of innocent passage. The contiguous zone reaches 24 miles and the exclusive economic zone 200.","about":["mare-liberum"]},
{"id":"LW-H30","lv":"states","d":3,"area":"States and trade rules","q":"A coastal state's exclusive economic zone, where it owns the fish and the seabed's resources, reaches up to","o":["12 nautical miles","200 nautical miles","24 nautical miles","350 nautical miles"],"a":[1],"s":1,"x":"Article 57. The coastal state's rights over the seabed itself, the continental shelf, can reach 350 miles in some places.","about":["mare-liberum","transit-passage"]},
{"id":"LW-H31","lv":"states","d":6,"area":"States and trade rules","q":"In February 2025 the EU set definitive anti-dumping duties on Chinese biodiesel of between 10% and","o":["22.4%","35.6%","48.1%","63.9%"],"a":[1],"s":1,"x":"They replaced provisional duties of August 2024 and cover HVO (hydrotreated vegetable oil) as well as FAME biodiesel, but not sustainable aviation fuel.","about":["anti-dumping"]},
{"id":"LW-anti-dumping","lv":"states","d":5,"area":"States and trade rules","q":"What is meant by “Anti-dumping”?","o":["duties on imports from a country that broke a trade agreement","duties on imports surging so fast they threaten local producers","duties on imports sold below normal value that injure local industry","duties on imports that a foreign government has subsidised to sell cheap"],"a":[2],"s":1,"x":"Anti-dumping: duties on imports sold below normal value that injure local industry. GATT, art. VI, and the WTO's Anti-Dumping Agreement: normal value is usually the home-market price or the cost of making. The EU put duties on biodiesel from Argentina and Indonesia in 2013, and from China, HVO included, in 2025 (10% to 35.6%), sustainable aviation fuel aside.","about":["anti-dumping"]},
{"id":"LW-anti-dumping-name","lv":"states","d":6,"area":"States and trade rules","q":"Which legal term means this? “Duties on imports sold below normal value that injure local industry”","o":["Blocking statute","But-for test","Hull formula","Anti-dumping"],"a":[3],"s":1,"x":"Anti-dumping: duties on imports sold below normal value that injure local industry. GATT, art. VI, and the WTO's Anti-Dumping Agreement: normal value is usually the home-market price or the cost of making. The EU put duties on biodiesel from Argentina and Indonesia in 2013, and from China, HVO included, in 2025 (10% to 35.6%), sustainable aviation fuel aside.","about":["anti-dumping"]},
{"id":"LW-demurrage","lv":"shipping","d":3,"area":"Ships and cargo","q":"What is meant by “Demurrage”?","o":["the daily sum a charterer owes for keeping a ship too long","the daily rate a charterer pays for a ship it hires by the day","the daily rate a port charges for a ship waiting at anchor","the daily rate a charterer earns for loading faster than allowed"],"a":[0],"s":1,"x":"Demurrage: the daily sum a charterer owes for keeping a ship too long. Liquidated damages for delay at the charter's own rate. 'Once on demurrage, always on demurrage': exceptions that stop laytime don't stop it unless the clause says so. In a sale, the buyer's demurrage usually mirrors the charter's.","about":["demurrage"]},
{"id":"LW-demurrage-name","lv":"shipping","d":4,"area":"Ships and cargo","q":"Which legal term means this? “The daily sum a charterer owes for keeping a ship too long”","o":["Off-hire","Charter party","Bill of lading","Demurrage"],"a":[3],"s":1,"x":"Demurrage: the daily sum a charterer owes for keeping a ship too long. Liquidated damages for delay at the charter's own rate. 'Once on demurrage, always on demurrage': exceptions that stop laytime don't stop it unless the clause says so. In a sale, the buyer's demurrage usually mirrors the charter's.","about":["demurrage"]},
{"id":"LW-charter-party","lv":"shipping","d":3,"area":"Ships and cargo","q":"What is meant by “Charter party”?","o":["the contract booking space for one parcel on a liner's sailing","the contract selling a ship, with its flag and its class kept","the contract hiring a whole ship, for a voyage or for a set period","the contract insuring a ship's hull and machinery for a year"],"a":[2],"s":1,"x":"Charter party: the contract hiring a whole ship, for a voyage or for a set period. From carta partita, a deed cut in two so that each side kept half. A voyage charter pays freight by the tonne and demurrage for delay; a time charter pays hire by the day; a bareboat (demise) charter hands over the ship itself, the charterer crewing it.","about":["charter-party"]},
{"id":"LW-charter-party-name","lv":"shipping","d":4,"area":"Ships and cargo","q":"Which legal term means this? “The contract hiring a whole ship, for a voyage or for a set period”","o":["Demurrage","No cure, no pay","Himalaya clause","Charter party"],"a":[3],"s":1,"x":"Charter party: the contract hiring a whole ship, for a voyage or for a set period. From carta partita, a deed cut in two so that each side kept half. A voyage charter pays freight by the tonne and demurrage for delay; a time charter pays hire by the day; a bareboat (demise) charter hands over the ship itself, the charterer crewing it.","about":["charter-party"]},
{"id":"LW-fob","lv":"sale","d":3,"area":"Selling goods","q":"What is meant by “FOB”?","o":["the seller books and pays the ship; risk passes once goods are loaded","the seller pays the ship and insurance; risk passes on arrival at port","the buyer books the ship; risk passes once goods are on the quay beside it","the buyer books the ship; risk passes once the goods are loaded aboard"],"a":[3],"s":1,"x":"FOB: the buyer books the ship; risk passes once the goods are loaded aboard. Free on board, Incoterms 2020: sea and inland waterways only. Risk passes when the goods are on board (the ship's rail went in 2010). In oil and biofuels, FOB means the buyer nominates the ship to arrive within the laycan, the agreed window, and the seller's terminal loads it.","about":["fob"]},
{"id":"LW-fob-name","lv":"sale","d":4,"area":"Selling goods","q":"Which legal term means this? “The buyer books the ship; risk passes once the goods are loaded aboard”","o":["WIBON","EXW","CFR","FOB"],"a":[3],"s":1,"x":"FOB: the buyer books the ship; risk passes once the goods are loaded aboard. Free on board, Incoterms 2020: sea and inland waterways only. Risk passes when the goods are on board (the ship's rail went in 2010). In oil and biofuels, FOB means the buyer nominates the ship to arrive within the laycan, the agreed window, and the seller's terminal loads it.","about":["fob"]},
{"id":"LW-cif","lv":"sale","d":3,"area":"Selling goods","q":"What is meant by “CIF”?","o":["the seller pays freight, insurance and duties; risk passes at delivery","the seller pays freight and insurance; risk passes on arrival","the seller pays the freight but not insurance; risk passes on loading","the seller pays freight and insurance; risk passes on loading"],"a":[3],"s":1,"x":"CIF: the seller pays freight and insurance; risk passes on loading. Cost, insurance and freight: a sale of documents. The buyer must pay against the bill of lading, the policy and the invoice even if the ship has sunk (Manbre Saccharine v Corn Products, 1919). Minimum cover, Institute Cargo Clauses (C), for 110% of the price.","about":["cif"]},
{"id":"LW-cif-name","lv":"sale","d":4,"area":"Selling goods","q":"Which legal term means this? “The seller pays freight and insurance; risk passes on loading”","o":["DDP","CISG","WIBON","CIF"],"a":[3],"s":1,"x":"CIF: the seller pays freight and insurance; risk passes on loading. Cost, insurance and freight: a sale of documents. The buyer must pay against the bill of lading, the policy and the invoice even if the ship has sunk (Manbre Saccharine v Corn Products, 1919). Minimum cover, Institute Cargo Clauses (C), for 110% of the price.","about":["cif"]},
{"id":"LW-caveat-emptor-name","lv":"sale","d":4,"area":"Selling goods","q":"Which legal term means this? “The buyer is responsible for checking what they buy”","o":["Nemo dat quod non habet","Res perit domino","Habeas corpus","Caveat emptor"],"a":[3],"s":1,"x":"Caveat emptor: the buyer is responsible for checking what they buy. Literally: let the buyer beware. The common law's old rule for sales, now much narrowed: the Sale of Goods Act 1979 implies that goods sold in the course of a business are of satisfactory quality and fit for their purpose (s 14). It still holds for private sales and, largely, for land.","about":["caveat-emptor"]},
{"id":"LW-quid-pro-quo-name","lv":"contract","d":4,"area":"Contracts","q":"Which legal term means this? “Something given in return for something else”","o":["Culpa in contrahendo","Bona fide","Contra proferentem","Quid pro quo"],"a":[3],"s":1,"x":"Quid pro quo: something given in return for something else. Literally: something for something. The bargain at the heart of a contract: each side gives something for what it gets. In the common law that is consideration; in a bribery case, a quid pro quo is what makes a favour a corrupt exchange.","about":["quid-pro-quo"]},
{"id":"LW-ad-hoc-name","lv":"disputes","d":4,"area":"Courts and arbitration","q":"Which legal term means this? “Made for one particular purpose, not planned”","o":["Lex fori","Pro bono","Ad hoc","Res judicata"],"a":[2],"s":1,"x":"Ad hoc: made for one particular purpose, not planned. Literally: for this. An ad hoc arbitration is one with no institution to run it: the parties and their arbitrators set the rules, usually the UNCITRAL Rules, and the court of the seat helps when they cannot agree.","about":["ad-hoc"]},
{"id":"LW-pro-bono-name","lv":"disputes","d":4,"area":"Courts and arbitration","q":"Which legal term means this? “Done for free, for the public good”","o":["Res judicata","Locus standi","Lex fori","Pro bono"],"a":[3],"s":1,"x":"Pro bono: done for free, for the public good. Literally: for the good. From pro bono publico, for the public good: legal work done without a fee, which many lawyers' professional rules encourage.","about":["pro-bono"]},
{"id":"LW-bona-fide-name","lv":"contract","d":4,"area":"Contracts","q":"Which legal term means this? “Genuine, in good faith”","o":["Pro forma","Quantum meruit","Rebus sic stantibus","Bona fide"],"a":[3],"s":1,"x":"Bona fide: genuine, in good faith. Literally: in good faith. In good faith: honest, and without notice of any defect or adverse claim. Several exceptions to nemo dat turn on it, and so does a holder in due course's title.","about":["bona-fide"]},
{"id":"LW-habeas-corpus-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “The right not to be held without a court's review”","o":["Habeas corpus","Sine qua non","Respondeat superior","Ne bis in idem"],"a":[0],"s":1,"x":"Habeas corpus: the right not to be held without a court's review. Literally: you shall have the body. The writ by which a court orders a prisoner brought before it to test whether the detention is lawful; the Habeas Corpus Act 1679 made it effective, and Magna Carta's clause 39 is its root.","about":["habeas-corpus"]},
{"id":"LW-de-facto-name","lv":"states","d":4,"area":"States and trade rules","q":"Which legal term means this? “In fact, whether or not by right”","o":["Mare liberum","Bona fide","De facto","Lex situs"],"a":[2],"s":1,"x":"De facto: in fact, whether or not by right. Literally: from the fact. Opposite of de jure, by right. A de facto government holds the territory and the power without being recognised as the lawful one; a de facto director acts as one without having been appointed.","about":["de-facto"]},
{"id":"LW-sine-qua-non-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “An essential condition”","o":["In dubio pro reo","Ne bis in idem","Res ipsa loquitur","Sine qua non"],"a":[3],"s":1,"x":"Sine qua non: an essential condition. Literally: without which not. The Roman lawyers' conditio sine qua non is the but-for test of causation: take away the act and the harm would not have happened. Necessary, but not enough, because it isn't a test of fault or foresight.","about":["sine-qua-non"]},
{"id":"LW-mutatis-mutandis-name","lv":"reading","d":6,"area":"Reading the law","q":"Which legal term means this? “With the necessary changes made”","o":["Ejusdem generis","Ipso facto","Noscitur a sociis","Mutatis mutandis"],"a":[3],"s":1,"x":"Mutatis mutandis: with the necessary changes made. Literally: having changed what must be changed. A drafting shortcut: 'section 5 applies, mutatis mutandis, to a lease' extends a rule to a new case with whatever changes of names and details make it fit.","about":["mutatis-mutandis"]},
{"id":"LW-pro-forma-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “As a matter of form”","o":["Res perit domino","Pro forma","Lex situs","Lex mercatoria"],"a":[1],"s":1,"x":"Pro forma: as a matter of form. Literally: for form. A pro forma invoice is a quotation set out like an invoice, not a demand for payment; a buyer needs it to open a credit or to get an import licence. It is not a tax invoice.","about":["pro-forma"]},
{"id":"LW-ipso-facto-name","lv":"reading","d":6,"area":"Reading the law","q":"Which legal term means this? “By that very fact”","o":["Ipso facto","Per incuriam","Ejusdem generis","Noscitur a sociis"],"a":[0],"s":1,"x":"Ipso facto: by that very fact. An 'ipso facto' clause ends a contract automatically on the other side's insolvency. English and US law now restrict them: the Corporate Insolvency and Governance Act 2020 stops a supplier from terminating just because its customer enters a formal procedure.","about":["ipso-facto"]},
{"id":"LW-force-majeure-name","lv":"contract","d":4,"area":"Contracts","q":"Which legal term means this? “An unforeseeable event that excuses a party from a contract”","o":["Pacta sunt servanda","Contra proferentem","En fait de meubles, la possession vaut titre","Force majeure"],"a":[3],"s":1,"x":"Force majeure: an unforeseeable event that excuses a party from a contract. Literally: superior force. Not a doctrine of English law but a clause, read for what it says: which events, whether they must prevent or merely hinder, what notice. A party needn't accept performance the contract doesn't provide for to overcome one (RTI v MUR Shipping, 2024: euros offered for sanctioned dollars).","about":["force-majeure"]},
{"id":"LW-nemo-dat","lv":"sale","d":3,"area":"Selling goods","q":"What does this mean? “Nemo dat quod non habet”","o":["a gift isn't made until the thing is handed over","a seller can't be made to deliver goods it has lost","a debtor can't be made to pay more than it owns","a buyer gets no better title than the seller itself had"],"a":[3],"s":1,"x":"Nemo dat quod non habet: a buyer gets no better title than the seller itself had. Literally: no one gives what they do not have. The rule of the Sale of Goods Act 1979, s 21, with exceptions for estoppel, mercantile agents, sellers and buyers in possession and sales under a voidable title. Civil law protects a good-faith buyer far more (§ 932 BGB; Code civil, art. 2276).","about":["nemo-dat"]},
{"id":"LW-nemo-dat-name","lv":"sale","d":4,"area":"Selling goods","q":"Which legal term means this? “A buyer gets no better title than the seller itself had”","o":["Caveat emptor","Nemo iudex in causa sua","Pro forma","Nemo dat quod non habet"],"a":[3],"s":1,"x":"Nemo dat quod non habet: a buyer gets no better title than the seller itself had. Literally: no one gives what they do not have. The rule of the Sale of Goods Act 1979, s 21, with exceptions for estoppel, mercantile agents, sellers and buyers in possession and sales under a voidable title. Civil law protects a good-faith buyer far more (§ 932 BGB; Code civil, art. 2276).","about":["nemo-dat"]},
{"id":"LW-res-perit-domino","lv":"sale","d":5,"area":"Selling goods","q":"What does this mean? “Res perit domino” (literally: the thing perishes for its owner)","o":["an owner can't claim for damage it caused to its own goods","the seller bears any loss until the goods are delivered","a sale of goods that have perished is void from the start","risk of loss goes with ownership unless agreed otherwise"],"a":[3],"s":1,"x":"Res perit domino: risk of loss goes with ownership unless agreed otherwise. Literally: the thing perishes for its owner. The default of the Sale of Goods Act 1979, s 20. Trade terms usually part the two: under FOB and CIF, risk passes on loading, ownership often only when the documents are paid for.","about":["res-perit-domino"]},
{"id":"LW-res-perit-domino-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “Risk of loss goes with ownership unless agreed otherwise”","o":["Lex mercatoria","In dubio pro reo","Res perit domino","Beati possidentes"],"a":[2],"s":1,"x":"Res perit domino: risk of loss goes with ownership unless agreed otherwise. Literally: the thing perishes for its owner. The default of the Sale of Goods Act 1979, s 20. Trade terms usually part the two: under FOB and CIF, risk passes on loading, ownership often only when the documents are paid for.","about":["res-perit-domino"]},
{"id":"LW-retention-of-title","lv":"sale","d":5,"area":"Selling goods","q":"What is meant by “Retention of title”?","o":["the buyer may keep the goods while a dispute is settled","the seller may keep the goods until the buyer pays for them","the seller keeps the documents until the ship arrives","the seller stays the owner of the goods until it has been paid"],"a":[3],"s":1,"x":"Retention of title: the seller stays the owner of the goods until it has been paid. A Romalpa clause, after Aluminium Industrie Vaassen v Romalpa (1976). It protects the seller in the buyer's insolvency while the goods can still be identified; a claim to the proceeds, or to goods mixed into others, is usually a charge, void unless registered. In Germany, Eigentumsvorbehalt is routine.","about":["retention-of-title"]},
{"id":"LW-retention-of-title-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “The seller stays the owner of the goods until it has been paid”","o":["Market overt","Adverse possession","Apparent authority","Retention of title"],"a":[3],"s":1,"x":"Retention of title: the seller stays the owner of the goods until it has been paid. A Romalpa clause, after Aluminium Industrie Vaassen v Romalpa (1976). It protects the seller in the buyer's insolvency while the goods can still be identified; a claim to the proceeds, or to goods mixed into others, is usually a charge, void unless registered. In Germany, Eigentumsvorbehalt is routine.","about":["retention-of-title"]},
{"id":"LW-market-overt","lv":"sale","d":7,"area":"Selling goods","q":"What is meant by “Market overt”?","o":["stolen goods found at a fair went back to their owner for free","a good-faith buyer at an open fair took title even to stolen goods","goods bought at a public auction couldn't be returned for defects","a trader had to show its prices openly on the stall it had rented"],"a":[1],"s":1,"x":"Market overt: a good-faith buyer at an open fair took title even to stolen goods. An exception to nemo dat from the Middle Ages, for sales in open markets and in the shops of the City of London; abolished in England by the Sale of Goods (Amendment) Act 1994.","about":["market-overt"]},
{"id":"LW-market-overt-name","lv":"sale","d":8,"area":"Selling goods","q":"Which legal term means this? “A good-faith buyer at an open fair took title even to stolen goods”","o":["Battle of the forms","Retention of title","Market overt","Satisfactory quality"],"a":[2],"s":1,"x":"Market overt: a good-faith buyer at an open fair took title even to stolen goods. An exception to nemo dat from the Middle Ages, for sales in open markets and in the shops of the City of London; abolished in England by the Sale of Goods (Amendment) Act 1994.","about":["market-overt"]},
{"id":"LW-possession-vaut-titre","lv":"sale","d":7,"area":"Selling goods","q":"What does this mean? “En fait de meubles, la possession vaut titre” (literally: in matters of movables, possession is as good as title)","o":["a pawnbroker holding goods may treat them as its own after one year","whoever holds movables is presumed to have paid for them in full","a good-faith buyer of movables becomes the owner, even from a non-owner","a carrier holding goods may sell them if its freight goes unpaid"],"a":[2],"s":1,"x":"En fait de meubles, la possession vaut titre: a good-faith buyer of movables becomes the owner, even from a non-owner. Literally: in matters of movables, possession is as good as title. French Code civil, art. 2276 (art. 2279 until 2008): the owner of a thing lost or stolen may still reclaim it within three years. German law reaches much the same result by § 932 BGB, English law the opposite by nemo dat.","about":["possession-vaut-titre"]},
{"id":"LW-possession-vaut-titre-name","lv":"sale","d":8,"area":"Selling goods","q":"Which legal term means this? “A good-faith buyer of movables becomes the owner, even from a non-owner”","o":["He who comes to equity must come with clean hands","Ei incumbit probatio qui dicit, non qui negat","Equity regards as done that which ought to be done","En fait de meubles, la possession vaut titre"],"a":[3],"s":1,"x":"En fait de meubles, la possession vaut titre: a good-faith buyer of movables becomes the owner, even from a non-owner. Literally: in matters of movables, possession is as good as title. French Code civil, art. 2276 (art. 2279 until 2008): the owner of a thing lost or stolen may still reclaim it within three years. German law reaches much the same result by § 932 BGB, English law the opposite by nemo dat.","about":["possession-vaut-titre"]},
{"id":"LW-satisfactory-quality","lv":"sale","d":5,"area":"Selling goods","q":"What is meant by “Satisfactory quality”?","o":["goods must match the sample the buyer was shown before the sale was made","goods sold by a business must be as good as a reasonable buyer would expect","goods must suit any special purpose the buyer told the seller of","goods must be exactly as the contract describes them, word for word"],"a":[1],"s":1,"x":"Satisfactory quality: goods sold by a business must be as good as a reasonable buyer would expect. Implied by the Sale of Goods Act 1979, s 14(2), into sales in the course of a business: fitness for the usual purposes, appearance and finish, freedom from minor defects, safety, durability. It replaced 'merchantable quality' in 1994; consumers now have the Consumer Rights Act 2015.","about":["satisfactory-quality"]},
{"id":"LW-satisfactory-quality-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “Goods sold by a business must be as good as a reasonable buyer would expect”","o":["Clean bill of lading","Battle of the forms","Stoppage in transit","Satisfactory quality"],"a":[3],"s":1,"x":"Satisfactory quality: goods sold by a business must be as good as a reasonable buyer would expect. Implied by the Sale of Goods Act 1979, s 14(2), into sales in the course of a business: fitness for the usual purposes, appearance and finish, freedom from minor defects, safety, durability. It replaced 'merchantable quality' in 1994; consumers now have the Consumer Rights Act 2015.","about":["satisfactory-quality"]},
{"id":"LW-battle-of-the-forms","lv":"sale","d":5,"area":"Selling goods","q":"What is meant by “Battle of the forms”?","o":["rival bids for one cargo, where the first one accepted takes it","clashing standard terms, with the last set sent usually prevailing","a dispute over whose law governs a contract made by letters","competing claims to goods, where the first registered charge wins"],"a":[1],"s":1,"x":"Battle of the forms: clashing standard terms, with the last set sent usually prevailing. Butler Machine Tool v Ex-Cell-O (1979): the last shot before performance usually wins. The CISG treats a reply with material changes as a counter-offer (art. 19); German courts keep only the terms both sides share, the 'knock-out' rule.","about":["battle-of-the-forms"]},
{"id":"LW-battle-of-the-forms-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “Clashing standard terms, with the last set sent usually prevailing”","o":["Battle of the forms","Bona fide purchaser","Market overt","Stoppage in transit"],"a":[0],"s":1,"x":"Battle of the forms: clashing standard terms, with the last set sent usually prevailing. Butler Machine Tool v Ex-Cell-O (1979): the last shot before performance usually wins. The CISG treats a reply with material changes as a counter-offer (art. 19); German courts keep only the terms both sides share, the 'knock-out' rule.","about":["battle-of-the-forms"]},
{"id":"LW-incoterms","lv":"sale","d":3,"area":"Selling goods","q":"What is meant by “Incoterms”?","o":["the ICC's rules for guarantees payable on first written demand","the ICC's rules for how banks collect payment against shipping documents","the ICC's terms for who ships, clears customs and bears risk","the ICC's rules for how banks examine documents under a credit"],"a":[2],"s":1,"x":"Incoterms: the ICC's terms for who ships, clears customs and bears risk. First published in 1936; Incoterms 2020 has eleven: seven for any mode of transport (EXW, FCA, CPT, CIP, DAP, DPU, DDP) and four for sea and inland waterways (FAS, FOB, CFR, CIF). They say nothing about when ownership passes.","about":["incoterms"]},
{"id":"LW-incoterms-name","lv":"sale","d":4,"area":"Selling goods","q":"Which legal term means this? “The ICC's terms for who ships, clears customs and bears risk”","o":["Satisfactory quality","Incoterms","Stoppage in transit","Market overt"],"a":[1],"s":1,"x":"Incoterms: the ICC's terms for who ships, clears customs and bears risk. First published in 1936; Incoterms 2020 has eleven: seven for any mode of transport (EXW, FCA, CPT, CIP, DAP, DPU, DDP) and four for sea and inland waterways (FAS, FOB, CFR, CIF). They say nothing about when ownership passes.","about":["incoterms"]},
{"id":"LW-cfr-incoterm","lv":"sale","d":5,"area":"Selling goods","q":"What is meant by “CFR”?","o":["the buyer pays the freight; risk passes once the goods are loaded","the seller pays the freight but not insurance; risk passes on loading","the seller pays freight and insurance; risk passes on loading","the seller pays the freight; risk passes only when the ship arrives"],"a":[1],"s":1,"x":"CFR: the seller pays the freight but not insurance; risk passes on loading. Cost and freight, also written C&F or CNF; Incoterms 2020, sea and inland waterways only. As under CIF and FOB, the seller's risk ends on board at the loading port; the buyer insures the voyage.","about":["cfr-incoterm"]},
{"id":"LW-cfr-incoterm-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “The seller pays the freight but not insurance; risk passes on loading”","o":["Incoterms","EXW","DDP","CFR"],"a":[3],"s":1,"x":"CFR: the seller pays the freight but not insurance; risk passes on loading. Cost and freight, also written C&F or CNF; Incoterms 2020, sea and inland waterways only. As under CIF and FOB, the seller's risk ends on board at the loading port; the buyer insures the voyage.","about":["cfr-incoterm"]},
{"id":"LW-exw","lv":"sale","d":5,"area":"Selling goods","q":"What is meant by “EXW”?","o":["the buyer collects from the seller's premises and does everything else","the seller delivers to the buyer's premises and does everything else","the seller delivers to the port and the buyer pays for the ship","the seller loads the buyer's truck and clears the goods for export"],"a":[0],"s":1,"x":"EXW: the buyer collects from the seller's premises and does everything else. Ex works: the seller's least obligation in Incoterms 2020. It needn't even load the goods or clear them for export, which is why FCA at the seller's premises is usually the better term for an export.","about":["exw"]},
{"id":"LW-exw-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “The buyer collects from the seller's premises and does everything else”","o":["FOB","WIBON","CISG","EXW"],"a":[3],"s":1,"x":"EXW: the buyer collects from the seller's premises and does everything else. Ex works: the seller's least obligation in Incoterms 2020. It needn't even load the goods or clear them for export, which is why FCA at the seller's premises is usually the better term for an export.","about":["exw"]},
{"id":"LW-ddp","lv":"sale","d":5,"area":"Selling goods","q":"What is meant by “DDP”?","o":["the seller delivers to the buyer's door; the buyer pays import duties","the seller delivers to the port of arrival, unloaded onto the quay","the seller delivers to the buyer's door, with import duties paid","the seller delivers to the buyer's door, insured but not cleared"],"a":[2],"s":1,"x":"DDP: the seller delivers to the buyer's door, with import duties paid. Delivered duty paid: the seller's greatest obligation in Incoterms 2020, the mirror of EXW. It must clear the goods for import and pay the duties, so it must be able to act as importer in the buyer's country.","about":["ddp"]},
{"id":"LW-ddp-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “The seller delivers to the buyer's door, with import duties paid”","o":["FOB","CFR","CISG","DDP"],"a":[3],"s":1,"x":"DDP: the seller delivers to the buyer's door, with import duties paid. Delivered duty paid: the seller's greatest obligation in Incoterms 2020, the mirror of EXW. It must clear the goods for import and pay the duties, so it must be able to act as importer in the buyer's country.","about":["ddp"]},
{"id":"LW-cisg","lv":"sale","d":5,"area":"Selling goods","q":"What is meant by “CISG”?","o":["the UN's uniform law for international sales of goods","the UN's model law for international commercial arbitration","the UN's treaty on how treaties are made and read, of 1969","the UN's treaty on the carriage of goods by sea, of 1978"],"a":[0],"s":1,"x":"CISG: the UN's uniform law for international sales of goods. The UN Convention on Contracts for the International Sale of Goods, Vienna 1980, in force since 1988, with 97 states party in 2025, though not the UK or India. It applies unless the parties exclude it, as sellers and buyers of commodities often do.","about":["cisg"]},
{"id":"LW-cisg-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “The UN's uniform law for international sales of goods”","o":["DDP","FOB","Incoterms","CISG"],"a":[3],"s":1,"x":"CISG: the UN's uniform law for international sales of goods. The UN Convention on Contracts for the International Sale of Goods, Vienna 1980, in force since 1988, with 97 states party in 2025, though not the UK or India. It applies unless the parties exclude it, as sellers and buyers of commodities often do.","about":["cisg"]},
{"id":"LW-lex-mercatoria","lv":"sale","d":5,"area":"Selling goods","q":"What does this mean? “Lex mercatoria” (literally: the law of merchants)","o":["the rules a guild set for its own members' prices and wages","the law of the ship's flag, followed wherever it trades","the duties a medieval city levied on all goods sold in its market","trade's own customs, applied across borders apart from any state"],"a":[3],"s":1,"x":"Lex mercatoria: trade's own customs, applied across borders apart from any state. Literally: the law of merchants. The law of medieval fairs and ports, absorbed into the common law by Lord Mansfield in the 18th century. The name lives on for the transnational rules of trade (Incoterms, UCP 600, the UNIDROIT Principles) that arbitrators apply.","about":["lex-mercatoria"]},
{"id":"LW-lex-mercatoria-name","lv":"sale","d":6,"area":"Selling goods","q":"Which legal term means this? “Trade's own customs, applied across borders apart from any state”","o":["Quantum meruit","Lex mercatoria","Cuius est solum","Res perit domino"],"a":[1],"s":1,"x":"Lex mercatoria: trade's own customs, applied across borders apart from any state. Literally: the law of merchants. The law of medieval fairs and ports, absorbed into the common law by Lord Mansfield in the 18th century. The name lives on for the transnational rules of trade (Incoterms, UCP 600, the UNIDROIT Principles) that arbitrators apply.","about":["lex-mercatoria"]},
{"id":"LW-stoppage-in-transit","lv":"sale","d":7,"area":"Selling goods","q":"What is meant by “Stoppage in transit”?","o":["an unpaid seller can halt goods on the way if the buyer is insolvent","a carrier may halt goods on their way until all its freight is paid","a buyer may halt goods on their way if it finds them defective","a state may halt goods on their way that breach its sanctions"],"a":[0],"s":1,"x":"Stoppage in transit: an unpaid seller can halt goods on the way if the buyer is insolvent. Sale of Goods Act 1979, ss 44 to 46, beside the unpaid seller's lien on goods still in its hands and its right of resale (s 48). It ends when the goods reach the buyer, or when the bill of lading is passed on to a buyer in good faith.","about":["stoppage-in-transit"]},
{"id":"LW-stoppage-in-transit-name","lv":"sale","d":8,"area":"Selling goods","q":"Which legal term means this? “An unpaid seller can halt goods on the way if the buyer is insolvent”","o":["Satisfactory quality","Incoterms","Market overt","Stoppage in transit"],"a":[3],"s":1,"x":"Stoppage in transit: an unpaid seller can halt goods on the way if the buyer is insolvent. Sale of Goods Act 1979, ss 44 to 46, beside the unpaid seller's lien on goods still in its hands and its right of resale (s 48). It ends when the goods reach the buyer, or when the bill of lading is passed on to a buyer in good faith.","about":["stoppage-in-transit"]},
{"id":"LW-bill-of-lading","lv":"shipping","d":3,"area":"Ships and cargo","q":"What is meant by “Bill of lading”?","o":["the carrier's receipt for cargo, which also passes title to it","the charterer's order to the master to load a named cargo","the port's record of what each ship loaded and when it sailed","the carrier's invoice for freight, paid before the cargo is released"],"a":[0],"s":1,"x":"Bill of lading: the carrier's receipt for cargo, which also passes title to it. Receipt for the goods, evidence of the contract of carriage and a document of title (Lickbarrow v Mason, 1794): whoever holds an original can claim the cargo, so it can be sold afloat by endorsement. The UK's Electronic Trade Documents Act 2023 gives an electronic one the same standing.","about":["bill-of-lading"]},
{"id":"LW-bill-of-lading-name","lv":"shipping","d":4,"area":"Ships and cargo","q":"Which legal term means this? “The carrier's receipt for cargo, which also passes title to it”","o":["No cure, no pay","Bill of lading","Himalaya clause","Seaworthiness"],"a":[1],"s":1,"x":"Bill of lading: the carrier's receipt for cargo, which also passes title to it. Receipt for the goods, evidence of the contract of carriage and a document of title (Lickbarrow v Mason, 1794): whoever holds an original can claim the cargo, so it can be sold afloat by endorsement. The UK's Electronic Trade Documents Act 2023 gives an electronic one the same standing.","about":["bill-of-lading"]},
{"id":"LW-letter-of-indemnity","lv":"shipping","d":5,"area":"Ships and cargo","q":"What is meant by “Letter of indemnity”?","o":["a bank's promise to pay the seller once the shipping documents comply","a promise to cover the carrier's loss for handing over without the bill","a buyer's promise to pay demurrage if the ship waits at discharge","an insurer's promise to pay for cargo lost or damaged on the voyage"],"a":[1],"s":1,"x":"Letter of indemnity: a promise to cover the carrier's loss for handing over without the bill. Routine in oil and chemical tankers, where the cargo arrives before the originals; the P&I clubs publish standard wordings. A letter of indemnity for a clean bill on cargo known to be damaged is a fraud and can't be enforced (Brown Jenkinson v Percy Dalton, 1957).","about":["letter-of-indemnity"]},
{"id":"LW-letter-of-indemnity-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “A promise to cover the carrier's loss for handing over without the bill”","o":["Clean bill of lading","Notice of readiness","Bill of lading","Letter of indemnity"],"a":[3],"s":1,"x":"Letter of indemnity: a promise to cover the carrier's loss for handing over without the bill. Routine in oil and chemical tankers, where the cargo arrives before the originals; the P&I clubs publish standard wordings. A letter of indemnity for a clean bill on cargo known to be damaged is a fraud and can't be enforced (Brown Jenkinson v Percy Dalton, 1957).","about":["letter-of-indemnity"]},
{"id":"LW-clean-bill","lv":"shipping","d":5,"area":"Ships and cargo","q":"What is meant by “Clean bill of lading”?","o":["one made out to a named consignee alone, so it can't be endorsed","one signed with no note of damage to the goods or packing","one issued only once the freight has been paid in full","one issued once the cargo is aboard, not merely received"],"a":[1],"s":1,"x":"Clean bill of lading: one signed with no note of damage to the goods or packing. Banks under a documentary credit accept only a clean transport document (UCP 600, art. 27); a claused or 'foul' bill stops payment, which is why shippers press masters for clean bills, sometimes against letters of indemnity.","about":["clean-bill"]},
{"id":"LW-clean-bill-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “One signed with no note of damage to the goods or packing”","o":["No cure, no pay","General average","Himalaya clause","Clean bill of lading"],"a":[3],"s":1,"x":"Clean bill of lading: one signed with no note of damage to the goods or packing. Banks under a documentary credit accept only a clean transport document (UCP 600, art. 27); a claused or 'foul' bill stops payment, which is why shippers press masters for clean bills, sometimes against letters of indemnity.","about":["clean-bill"]},
{"id":"LW-hague-visby-rules","lv":"shipping","d":5,"area":"Ships and cargo","q":"What is meant by “Hague-Visby Rules”?","o":["the treaty on liability for pollution when an oil tanker spills","the treaty on a sea carrier's duties, defences and limits of liability","the treaty on a shipowner's limit for all claims arising from one accident","the code for sharing a sacrifice made to save a ship and its cargo"],"a":[1],"s":1,"x":"Hague-Visby Rules: the treaty on a sea carrier's duties, defences and limits of liability. The Hague Rules of 1924, amended at Visby in 1968: the carrier must use due diligence to make the ship seaworthy, may plead errors in navigation, and limits its liability to 666.67 SDR a package or 2 SDR a kilo, whichever is higher. Claims are barred after a year.","about":["hague-visby-rules"]},
{"id":"LW-hague-visby-rules-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “The treaty on a sea carrier's duties, defences and limits of liability”","o":["No cure, no pay","Clean bill of lading","Hague-Visby Rules","General average"],"a":[2],"s":1,"x":"Hague-Visby Rules: the treaty on a sea carrier's duties, defences and limits of liability. The Hague Rules of 1924, amended at Visby in 1968: the carrier must use due diligence to make the ship seaworthy, may plead errors in navigation, and limits its liability to 666.67 SDR a package or 2 SDR a kilo, whichever is higher. Claims are barred after a year.","about":["hague-visby-rules"]},
{"id":"LW-seaworthiness","lv":"shipping","d":5,"area":"Ships and cargo","q":"What is meant by “Seaworthiness”?","o":["a ship's duty to answer a distress call and give aid at sea","a ship's right to enter any port in a storm, whatever its flag","a ship fit to carry the cargo safely on the voyage, crew and all","a ship's clearance by its flag state's surveyor every five years"],"a":[2],"s":1,"x":"Seaworthiness: a ship fit to carry the cargo safely on the voyage, crew and all. Absolute at common law; under the Hague-Visby Rules a duty of due diligence before and at the beginning of the voyage. Fitness for the particular cargo (clean tanks for a chemical, say) is part of it.","about":["seaworthiness"]},
{"id":"LW-seaworthiness-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “A ship fit to carry the cargo safely on the voyage, crew and all”","o":["General average","Seaworthiness","Demurrage","No cure, no pay"],"a":[1],"s":1,"x":"Seaworthiness: a ship fit to carry the cargo safely on the voyage, crew and all. Absolute at common law; under the Hague-Visby Rules a duty of due diligence before and at the beginning of the voyage. Fitness for the particular cargo (clean tanks for a chemical, say) is part of it.","about":["seaworthiness"]},
{"id":"LW-laytime","lv":"shipping","d":5,"area":"Ships and cargo","q":"What is meant by “Laytime”?","o":["the time a ship may stay in port before it pays berth dues","the rest a crew must have between watches, set by convention","the time a voyage charter allows for loading and for discharge","the time a buyer has to inspect the cargo before acceptance"],"a":[2],"s":1,"x":"Laytime: the time a voyage charter allows for loading and for discharge. It starts after notice of readiness (often six hours after) and runs as the charter says: SHINC counts Sundays and holidays, SHEX doesn't; WIBON starts it whether the ship is in berth or not. Time beyond it is paid as demurrage; time saved may earn despatch.","about":["laytime"]},
{"id":"LW-laytime-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “The time a voyage charter allows for loading and for discharge”","o":["Maritime lien","Safe port","Laytime","Off-hire"],"a":[2],"s":1,"x":"Laytime: the time a voyage charter allows for loading and for discharge. It starts after notice of readiness (often six hours after) and runs as the charter says: SHINC counts Sundays and holidays, SHEX doesn't; WIBON starts it whether the ship is in berth or not. Time beyond it is paid as demurrage; time saved may earn despatch.","about":["laytime"]},
{"id":"LW-notice-of-readiness","lv":"shipping","d":5,"area":"Ships and cargo","q":"What is meant by “Notice of readiness”?","o":["the shipper's word that the cargo is at the quay, waiting to load","the buyer's word that it has the money ready to pay for the cargo","the master's word that the ship has arrived and is ready to work","the port's word that a berth is free and a pilot is ready to board"],"a":[2],"s":1,"x":"Notice of readiness: the master's word that the ship has arrived and is ready to work. Laytime can't start without a valid one: the ship must be an 'arrived ship' (for a port charter, within the port at the charterer's disposal: The Johanna Oldendorff, 1973) and in fact ready. A notice given before then is no notice.","about":["notice-of-readiness"]},
{"id":"LW-notice-of-readiness-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “The master's word that the ship has arrived and is ready to work”","o":["Bill of lading","Letter of indemnity","No cure, no pay","Notice of readiness"],"a":[3],"s":1,"x":"Notice of readiness: the master's word that the ship has arrived and is ready to work. Laytime can't start without a valid one: the ship must be an 'arrived ship' (for a port charter, within the port at the charterer's disposal: The Johanna Oldendorff, 1973) and in fact ready. A notice given before then is no notice.","about":["notice-of-readiness"]},
{"id":"LW-wibon","lv":"shipping","d":7,"area":"Ships and cargo","q":"What is meant by “WIBON”?","o":["laytime stops while the ship waits for the weather to clear","laytime counts Sundays and holidays as working days","laytime counts even while the ship waits for a free berth","laytime counts only once the ship is alongside the berth"],"a":[2],"s":1,"x":"WIBON: laytime counts even while the ship waits for a free berth. Whether in berth or not: in a berth charter it moves the risk of congestion to the charterer. Its cousins: WIPON (whether in port or not), WIFPON (in free pratique or not), WCCON (customs cleared or not).","about":["wibon"]},
{"id":"LW-wibon-name","lv":"shipping","d":8,"area":"Ships and cargo","q":"Which legal term means this? “Laytime counts even while the ship waits for a free berth”","o":["CIF","EXW","FOB","WIBON"],"a":[3],"s":1,"x":"WIBON: laytime counts even while the ship waits for a free berth. Whether in berth or not: in a berth charter it moves the risk of congestion to the charterer. Its cousins: WIPON (whether in port or not), WIFPON (in free pratique or not), WCCON (customs cleared or not).","about":["wibon"]},
{"id":"LW-off-hire","lv":"shipping","d":5,"area":"Ships and cargo","q":"What is meant by “Off-hire”?","o":["hire under a time charter stops while the charterer has no cargo","hire under a time charter stops while the ship can't work as agreed","hire under a time charter is paid in advance, monthly or half-monthly","hire under a time charter rises once the ship is redelivered late"],"a":[1],"s":1,"x":"Off-hire: hire under a time charter stops while the ship can't work as agreed. The NYPE form's off-hire clause lists the causes (breakdown, deficiency of crew or stores, drydocking and the like): hire stops for the time lost and restarts when the ship is efficient again. Having nothing to load is the charterer's risk.","about":["off-hire"]},
{"id":"LW-off-hire-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “Hire under a time charter stops while the ship can't work as agreed”","o":["Bill of lading","Safe port","Demurrage","Off-hire"],"a":[3],"s":1,"x":"Off-hire: hire under a time charter stops while the ship can't work as agreed. The NYPE form's off-hire clause lists the causes (breakdown, deficiency of crew or stores, drydocking and the like): hire stops for the time lost and restarts when the ship is efficient again. Having nothing to load is the charterer's risk.","about":["off-hire"]},
{"id":"LW-general-average","lv":"shipping","d":5,"area":"Ships and cargo","q":"What is meant by “General average”?","o":["a loss from a storm falls on whoever owned the goods it happened to strike","a carrier's liability is capped at a fixed sum per package","a sacrifice to save ship and cargo is shared by all in proportion","a salvor's reward is set as a share of the value it saved"],"a":[2],"s":1,"x":"General average: a sacrifice to save ship and cargo is shared by all in proportion. Older than the common law: the Lex Rhodia de iactu in Justinian's Digest (what is thrown overboard for all is made good by all). Now the York-Antwerp Rules, last revised in 2016; cargo is released only once its owners give security.","about":["general-average"]},
{"id":"LW-general-average-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “A sacrifice to save ship and cargo is shared by all in proportion”","o":["Maritime lien","Himalaya clause","Charter party","General average"],"a":[3],"s":1,"x":"General average: a sacrifice to save ship and cargo is shared by all in proportion. Older than the common law: the Lex Rhodia de iactu in Justinian's Digest (what is thrown overboard for all is made good by all). Now the York-Antwerp Rules, last revised in 2016; cargo is released only once its owners give security.","about":["general-average"]},
{"id":"LW-no-cure-no-pay","lv":"shipping","d":5,"area":"Ships and cargo","q":"What is meant by “No cure, no pay”?","o":["a salvor earns a reward only if something of value is saved","a repair yard is paid only if the ship passes its survey","a carrier earns no freight unless the cargo arrives in good order","an insurer pays nothing for damage the owner could have prevented"],"a":[0],"s":1,"x":"No cure, no pay: a salvor earns a reward only if something of value is saved. The basis of Lloyd's Open Form, the standard salvage contract since the 19th century, with the reward fixed afterwards by arbitration in London. The Salvage Convention of 1989 adds special compensation for preventing pollution even when nothing is saved; the SCOPIC clause sets it at agreed rates.","about":["no-cure-no-pay"]},
{"id":"LW-no-cure-no-pay-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “A salvor earns a reward only if something of value is saved”","o":["Himalaya clause","Seaworthiness","Charter party","No cure, no pay"],"a":[3],"s":1,"x":"No cure, no pay: a salvor earns a reward only if something of value is saved. The basis of Lloyd's Open Form, the standard salvage contract since the 19th century, with the reward fixed afterwards by arbitration in London. The Salvage Convention of 1989 adds special compensation for preventing pollution even when nothing is saved; the SCOPIC clause sets it at agreed rates.","about":["no-cure-no-pay"]},
{"id":"LW-himalaya-clause","lv":"shipping","d":7,"area":"Ships and cargo","q":"What is meant by “Himalaya clause”?","o":["a term letting the carrier land the cargo elsewhere if war breaks out","a term making each ship pay its own share of a collision's cost","a term letting the carrier choose any route to the discharge port","a term extending the carrier's defences to its stevedores and agents alike"],"a":[3],"s":1,"x":"Himalaya clause: a term extending the carrier's defences to its stevedores and agents alike. Named after the liner Himalaya, whose passenger sued the master and boatswain because the carrier itself was protected (Adler v Dickson, 1954); upheld for stevedores in The Eurymedon (1975). The Contracts (Rights of Third Parties) Act 1999 now makes it simpler.","about":["himalaya-clause"]},
{"id":"LW-himalaya-clause-name","lv":"shipping","d":8,"area":"Ships and cargo","q":"Which legal term means this? “A term extending the carrier's defences to its stevedores and agents alike”","o":["No cure, no pay","Seaworthiness","Bill of lading","Himalaya clause"],"a":[3],"s":1,"x":"Himalaya clause: a term extending the carrier's defences to its stevedores and agents alike. Named after the liner Himalaya, whose passenger sued the master and boatswain because the carrier itself was protected (Adler v Dickson, 1954); upheld for stevedores in The Eurymedon (1975). The Contracts (Rights of Third Parties) Act 1999 now makes it simpler.","about":["himalaya-clause"]},
{"id":"LW-maritime-lien","lv":"shipping","d":7,"area":"Ships and cargo","q":"What is meant by “Maritime lien”?","o":["a claim the crew may bring only against the owner who hired them","a claim that attaches to the ship and follows it to a new owner","a claim registered against a ship, ranking by the date it was filed","a claim the port may enforce by refusing the ship clearance to sail"],"a":[1],"s":1,"x":"Maritime lien: a claim that attaches to the ship and follows it to a new owner. It arises silently, with no registration, for salvage, collision damage, crew's wages and the master's disbursements, and ranks ahead of the ship's mortgages. It's enforced by arresting the ship in an action in rem.","about":["maritime-lien"]},
{"id":"LW-maritime-lien-name","lv":"shipping","d":8,"area":"Ships and cargo","q":"Which legal term means this? “A claim that attaches to the ship and follows it to a new owner”","o":["Demurrage","No cure, no pay","Maritime lien","Charter party"],"a":[2],"s":1,"x":"Maritime lien: a claim that attaches to the ship and follows it to a new owner. It arises silently, with no registration, for salvage, collision damage, crew's wages and the master's disbursements, and ranks ahead of the ship's mortgages. It's enforced by arresting the ship in an action in rem.","about":["maritime-lien"]},
{"id":"LW-in-rem","lv":"shipping","d":5,"area":"Ships and cargo","q":"What does this mean? “In rem” (literally: against the thing)","o":["a claim by a buyer to be handed the goods it has paid for","a claim against goods seized at a border for breach of customs","a claim against a ship itself, enforced by arresting it in port","a claim decided on the documents alone, with no oral hearing"],"a":[2],"s":1,"x":"In rem: a claim against a ship itself, enforced by arresting it in port. Literally: against the thing. The admiralty action names the ship as defendant; arrest gives the claimant security, and an owner who defends submits to the court in personam too. In civil law, a right in rem is a property right, good against everyone; one in personam binds one person.","about":["in-rem"]},
{"id":"LW-in-rem-name","lv":"shipping","d":6,"area":"Ships and cargo","q":"Which legal term means this? “A claim against a ship itself, enforced by arresting it in port”","o":["Pro bono","Lex situs","Lex fori","In rem"],"a":[3],"s":1,"x":"In rem: a claim against a ship itself, enforced by arresting it in port. Literally: against the thing. The admiralty action names the ship as defendant; arrest gives the claimant security, and an owner who defends submits to the court in personam too. In civil law, a right in rem is a property right, good against everyone; one in personam binds one person.","about":["in-rem"]},
{"id":"LW-safe-port","lv":"shipping","d":7,"area":"Ships and cargo","q":"What is meant by “Safe port”?","o":["a port the ship can reach, use and leave without danger","a port where a ship may wait out a storm without paying dues","a port with no war risk premium, whatever the charter's route","a port where the ship can't be arrested by its owner's creditors"],"a":[0],"s":1,"x":"Safe port: a port the ship can reach, use and leave without danger. The Eastern City (1958): a port the ship can reach, use and return from without exposure to danger that good navigation and seamanship can't avoid, absent some abnormal occurrence. Charterers usually warrant it (The Ocean Victory, 2017).","about":["safe-port"]},
{"id":"LW-safe-port-name","lv":"shipping","d":8,"area":"Ships and cargo","q":"Which legal term means this? “A port the ship can reach, use and leave without danger”","o":["Maritime lien","Laytime","Off-hire","Safe port"],"a":[3],"s":1,"x":"Safe port: a port the ship can reach, use and leave without danger. The Eastern City (1958): a port the ship can reach, use and return from without exposure to danger that good navigation and seamanship can't avoid, absent some abnormal occurrence. Charterers usually warrant it (The Ocean Victory, 2017).","about":["safe-port"]},
{"id":"LW-letter-of-credit","lv":"finance","d":3,"area":"Paying, securing, insuring","q":"What is meant by “Letter of credit”?","o":["a bank's promise to repay the buyer if the goods prove defective","a bank's promise to collect the price from the buyer for the seller","a bank's promise to lend the buyer the price until it resells","a bank's promise to pay the seller against documents that comply"],"a":[3],"s":1,"x":"Letter of credit: a bank's promise to pay the seller against documents that comply. Governed by the ICC's UCP 600 (2007): an irrevocable undertaking, confirmed if a second bank, usually in the seller's country, adds its own. Banks deal in documents, not goods, and have at most five banking days to examine them.","about":["letter-of-credit"]},
{"id":"LW-letter-of-credit-name","lv":"finance","d":4,"area":"Paying, securing, insuring","q":"Which legal term means this? “A bank's promise to pay the seller against documents that comply”","o":["Close-out netting","Holder in due course","Insurable interest","Letter of credit"],"a":[3],"s":1,"x":"Letter of credit: a bank's promise to pay the seller against documents that comply. Governed by the ICC's UCP 600 (2007): an irrevocable undertaking, confirmed if a second bank, usually in the seller's country, adds its own. Banks deal in documents, not goods, and have at most five banking days to examine them.","about":["letter-of-credit"]},
{"id":"LW-autonomy-principle","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What is meant by “Autonomy principle”?","o":["the bank may refuse to pay if the buyer says the goods are defective","the bank alone decides whether the goods match the contract","the bank pays only once the buyer has inspected and accepted the goods","the bank pays on compliant documents, whatever the dispute over goods"],"a":[3],"s":1,"x":"Autonomy principle: the bank pays on compliant documents, whatever the dispute over goods. UCP 600, arts 4 and 5: the credit is separate from the sale it pays for. The one exception the courts admit is fraud (United City Merchants v Royal Bank of Canada, 1983: The American Accord).","about":["autonomy-principle"]},
{"id":"LW-autonomy-principle-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “The bank pays on compliant documents, whatever the dispute over goods”","o":["Holder in due course","Insurable interest","Letter of credit","Autonomy principle"],"a":[3],"s":1,"x":"Autonomy principle: the bank pays on compliant documents, whatever the dispute over goods. UCP 600, arts 4 and 5: the credit is separate from the sale it pays for. The one exception the courts admit is fraud (United City Merchants v Royal Bank of Canada, 1983: The American Accord).","about":["autonomy-principle"]},
{"id":"LW-strict-compliance","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What is meant by “Strict compliance”?","o":["documents must reach the bank before the ship reaches its port","documents must match the credit's terms; near enough is not enough","documents may differ from the credit if the bank thinks it immaterial","documents must be originals signed in ink, never copies or prints"],"a":[1],"s":1,"x":"Strict compliance: documents must match the credit's terms; near enough is not enough. 'There is no room for documents which are almost the same, or which will do just as well' (Equitable Trust Co of New York v Dawson Partners, 1927). UCP 600 softens it a little: data in different documents needn't be identical, only not conflict (art. 14(d)).","about":["strict-compliance"]},
{"id":"LW-strict-compliance-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “Documents must match the credit's terms; near enough is not enough”","o":["Insurable interest","Letter of credit","Demand guarantee","Strict compliance"],"a":[3],"s":1,"x":"Strict compliance: documents must match the credit's terms; near enough is not enough. 'There is no room for documents which are almost the same, or which will do just as well' (Equitable Trust Co of New York v Dawson Partners, 1927). UCP 600 softens it a little: data in different documents needn't be identical, only not conflict (art. 14(d)).","about":["strict-compliance"]},
{"id":"LW-fraus-omnia-corrumpit","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What does this mean? “Fraus omnia corrumpit” (literally: fraud corrupts everything)","o":["nothing obtained by fraud can ever stand, not even a court's judgment","a fraudster loses every right it held, even ones gained honestly","a contract holding any false statement is void for everyone","a fraud by one employee taints all of the firm's dealings"],"a":[0],"s":1,"x":"Fraus omnia corrumpit: nothing obtained by fraud can ever stand, not even a court's judgment. Literally: fraud corrupts everything. Lord Denning: 'fraud unravels all' (Lazarus Estates v Beasley, 1956). It's the one exception to a credit's or a demand guarantee's autonomy: a bank needn't pay a beneficiary it clearly knows to be presenting false documents.","about":["fraus-omnia-corrumpit"]},
{"id":"LW-fraus-omnia-corrumpit-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “Nothing obtained by fraud can ever stand, not even a court's judgment”","o":["Causa proxima non remota spectatur","Culpa in contrahendo","Fraus omnia corrumpit","Ubi jus, ibi remedium"],"a":[2],"s":1,"x":"Fraus omnia corrumpit: nothing obtained by fraud can ever stand, not even a court's judgment. Literally: fraud corrupts everything. Lord Denning: 'fraud unravels all' (Lazarus Estates v Beasley, 1956). It's the one exception to a credit's or a demand guarantee's autonomy: a bank needn't pay a beneficiary it clearly knows to be presenting false documents.","about":["fraus-omnia-corrumpit"]},
{"id":"LW-demand-guarantee","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What is meant by “Demand guarantee”?","o":["a bank's promise to pay only once a court has found the buyer at fault","a bank's promise to pay on a first written call, without proof","a bank's promise to pay the seller against documents for the goods","a bank's promise to buy the seller's invoices at a discount"],"a":[1],"s":1,"x":"Demand guarantee: a bank's promise to pay on a first written call, without proof. Also a performance or bid bond, under the ICC's URDG 758 (2010). Unlike a guarantee in the strict sense, a surety's promise, it doesn't depend on the underlying debt: it's paid unless the call is clearly fraudulent.","about":["demand-guarantee"]},
{"id":"LW-demand-guarantee-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “A bank's promise to pay on a first written call, without proof”","o":["Demand guarantee","Strict compliance","Floating charge","Letter of credit"],"a":[0],"s":1,"x":"Demand guarantee: a bank's promise to pay on a first written call, without proof. Also a performance or bid bond, under the ICC's URDG 758 (2010). Unlike a guarantee in the strict sense, a surety's promise, it doesn't depend on the underlying debt: it's paid unless the call is clearly fraudulent.","about":["demand-guarantee"]},
{"id":"LW-documentary-collection","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What is meant by “Documentary collection”?","o":["banks release the bill of lading only on payment or acceptance","banks lend against the cargo, holding the bill of lading as a pledge","banks buy the seller's receivables and chase the buyer for payment","banks pay the seller once its papers comply, whatever the buyer says"],"a":[0],"s":1,"x":"Documentary collection: banks release the bill of lading only on payment or acceptance. Under the ICC's URC 522: documents against payment (D/P) or against acceptance of a bill of exchange (D/A). Cheaper than a credit, but no bank promises to pay: if the buyer won't, the seller has goods at a foreign port.","about":["documentary-collection"]},
{"id":"LW-documentary-collection-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “Banks release the bill of lading only on payment or acceptance”","o":["Letter of credit","Demand guarantee","Close-out netting","Documentary collection"],"a":[3],"s":1,"x":"Documentary collection: banks release the bill of lading only on payment or acceptance. Under the ICC's URC 522: documents against payment (D/P) or against acceptance of a bill of exchange (D/A). Cheaper than a credit, but no bank promises to pay: if the buyer won't, the seller has goods at a foreign port.","about":["documentary-collection"]},
{"id":"LW-holder-in-due-course","lv":"finance","d":7,"area":"Paying, securing, insuring","q":"What is meant by “Holder in due course”?","o":["one who took a bill in good faith and for value, free of earlier defects","one who holds a bill until it falls due, then presents it for payment","one who signed a bill on its back, and so answers for it if unpaid","one who holds a bill made out to bearer, needing no endorsement"],"a":[0],"s":1,"x":"Holder in due course: one who took a bill in good faith and for value, free of earlier defects. Bills of Exchange Act 1882, s 29: such a holder takes free of the defences the earlier parties had between themselves, which is what lets a bill of exchange circulate like money and be discounted.","about":["holder-in-due-course"]},
{"id":"LW-holder-in-due-course-name","lv":"finance","d":8,"area":"Paying, securing, insuring","q":"Which legal term means this? “One who took a bill in good faith and for value, free of earlier defects”","o":["Close-out netting","Holder in due course","Documentary collection","Demand guarantee"],"a":[1],"s":1,"x":"Holder in due course: one who took a bill in good faith and for value, free of earlier defects. Bills of Exchange Act 1882, s 29: such a holder takes free of the defences the earlier parties had between themselves, which is what lets a bill of exchange circulate like money and be discounted.","about":["holder-in-due-course"]},
{"id":"LW-set-off","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What is meant by “Set-off”?","o":["a debt is cancelled once the debtor goes into insolvency","a debt is passed to a new creditor, who collects it in full","debts each side owes the other cancel out to leave the balance","a debt is put off to a later date by agreement between both sides"],"a":[2],"s":1,"x":"Set-off: debts each side owes the other cancel out to leave the balance. Mandatory in an English insolvency (rule 14.25), where it lets a creditor recover in full up to what it owes. Trade contracts often exclude it ('without set-off or counterclaim'), so the price is paid first and the quarrel comes after.","about":["set-off"]},
{"id":"LW-set-off-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “Debts each side owes the other cancel out to leave the balance”","o":["Floating charge","Subrogation","Demand guarantee","Set-off"],"a":[3],"s":1,"x":"Set-off: debts each side owes the other cancel out to leave the balance. Mandatory in an English insolvency (rule 14.25), where it lets a creditor recover in full up to what it owes. Trade contracts often exclude it ('without set-off or counterclaim'), so the price is paid first and the quarrel comes after.","about":["set-off"]},
{"id":"LW-close-out-netting","lv":"finance","d":7,"area":"Paying, securing, insuring","q":"What is meant by “Close-out netting”?","o":["on a default, every open trade ends and is valued as one balance","on a default, the open trades pass to a clearing house to finish","on a default, the trades in profit are paid and the rest are void","on a default, each open trade is settled separately as it falls due"],"a":[0],"s":1,"x":"Close-out netting: on a default, every open trade ends and is valued as one balance. The heart of the ISDA Master Agreement (1992 and 2002) and of commodity master agreements: it stops a liquidator cherry-picking the profitable contracts, and it's why exposures can be counted net.","about":["close-out-netting"]},
{"id":"LW-close-out-netting-name","lv":"finance","d":8,"area":"Paying, securing, insuring","q":"Which legal term means this? “On a default, every open trade ends and is valued as one balance”","o":["Strict compliance","Autonomy principle","Floating charge","Close-out netting"],"a":[3],"s":1,"x":"Close-out netting: on a default, every open trade ends and is valued as one balance. The heart of the ISDA Master Agreement (1992 and 2002) and of commodity master agreements: it stops a liquidator cherry-picking the profitable contracts, and it's why exposures can be counted net.","about":["close-out-netting"]},
{"id":"LW-pari-passu","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What does this mean? “Pari passu” (literally: with equal step)","o":["a new partner joins on equal terms with all the founding partners","both parties must perform at the same moment, neither first","a loan is repaid in equal steps, the same sum every month","creditors of the same rank share in proportion to their claims"],"a":[3],"s":1,"x":"Pari passu: creditors of the same rank share in proportion to their claims. Literally: with equal step. The default rule for unsecured creditors in an insolvency, and a standard clause in loans and bonds. Read as a duty to pay all holders ratably, it let Elliott freeze Argentina's payments on its restructured bonds from 2012 until 2016.","about":["pari-passu"]},
{"id":"LW-pari-passu-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “Creditors of the same rank share in proportion to their claims”","o":["Erga omnes","Uberrimae fidei","Ipso facto","Pari passu"],"a":[3],"s":1,"x":"Pari passu: creditors of the same rank share in proportion to their claims. Literally: with equal step. The default rule for unsecured creditors in an insolvency, and a standard clause in loans and bonds. Read as a duty to pay all holders ratably, it let Elliott freeze Argentina's payments on its restructured bonds from 2012 until 2016.","about":["pari-passu"]},
{"id":"LW-floating-charge","lv":"finance","d":7,"area":"Paying, securing, insuring","q":"What is meant by “Floating charge”?","o":["security over a changing pool of assets the debtor keeps trading","security by handing the lender the goods or their documents of title","security over a ship, registered and ranked by the date of filing","security over one named asset the debtor can't sell without consent"],"a":[0],"s":1,"x":"Floating charge: security over a changing pool of assets the debtor keeps trading. An English invention of the 19th century (Re Panama, New Zealand and Australian Royal Mail Co, 1870). On default it 'crystallises' into a fixed charge; in an insolvency it ranks after preferential creditors and a share kept for the unsecured.","about":["floating-charge"]},
{"id":"LW-floating-charge-name","lv":"finance","d":8,"area":"Paying, securing, insuring","q":"Which legal term means this? “Security over a changing pool of assets the debtor keeps trading”","o":["Strict compliance","Demand guarantee","Letter of credit","Floating charge"],"a":[3],"s":1,"x":"Floating charge: security over a changing pool of assets the debtor keeps trading. An English invention of the 19th century (Re Panama, New Zealand and Australian Royal Mail Co, 1870). On default it 'crystallises' into a fixed charge; in an insolvency it ranks after preferential creditors and a share kept for the unsecured.","about":["floating-charge"]},
{"id":"LW-pledge","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What is meant by “Pledge”?","o":["security by a third party's promise to pay if the debtor doesn't","security by registering a charge over the goods in a public register","security by handing the goods, or their title documents, to the lender","security by keeping ownership of the goods until the whole price is paid"],"a":[2],"s":1,"x":"Pledge: security by handing the goods, or their title documents, to the lender. The lender holds, the borrower still owns. A bank financing a cargo holds it in pledge through the bill of lading, and releasing the bill on a trust receipt so the buyer can sell keeps the pledge alive (North Western Bank v Poynter, 1895).","about":["pledge"]},
{"id":"LW-pledge-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “Security by handing the goods, or their title documents, to the lender”","o":["Floating charge","Strict compliance","Set-off","Pledge"],"a":[3],"s":1,"x":"Pledge: security by handing the goods, or their title documents, to the lender. The lender holds, the borrower still owns. A bank financing a cargo holds it in pledge through the bill of lading, and releasing the bill on a trust receipt so the buyer can sell keeps the pledge alive (North Western Bank v Poynter, 1895).","about":["pledge"]},
{"id":"LW-uberrimae-fidei","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What does this mean? “Uberrimae fidei” (literally: of the utmost good faith)","o":["an agent must never take a secret profit from its principal","a trustee must put the beneficiaries' interests above its own gain","both sides to any contract must deal honestly, by law","the insured must disclose every material fact before cover starts"],"a":[3],"s":1,"x":"Uberrimae fidei: the insured must disclose every material fact before cover starts. Literally: of the utmost good faith. Marine Insurance Act 1906, ss 17 and 18. The Insurance Act 2015 turned the duty to disclose into a 'duty of fair presentation', with remedies in proportion, from 2016.","about":["uberrimae-fidei"]},
{"id":"LW-uberrimae-fidei-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “The insured must disclose every material fact before cover starts”","o":["Ratio decidendi","Fraus omnia corrumpit","Ejusdem generis","Uberrimae fidei"],"a":[3],"s":1,"x":"Uberrimae fidei: the insured must disclose every material fact before cover starts. Literally: of the utmost good faith. Marine Insurance Act 1906, ss 17 and 18. The Insurance Act 2015 turned the duty to disclose into a 'duty of fair presentation', with remedies in proportion, from 2016.","about":["uberrimae-fidei"]},
{"id":"LW-insurable-interest","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What is meant by “Insurable interest”?","o":["the share of a loss each insurer pays when two cover one risk","a real stake in the thing covered, so that its loss would harm you","the rate charged for cover, as a share of the sum covered","the part of a loss the insured bears itself, before cover pays"],"a":[1],"s":1,"x":"Insurable interest: a real stake in the thing covered, so that its loss would harm you. Without it a policy is a wager. The Marine Insurance Act 1906 requires it at the time of the loss (s 6); an FOB or CIF buyer has it once the risk has passed, even before it owns the goods.","about":["insurable-interest"]},
{"id":"LW-insurable-interest-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “A real stake in the thing covered, so that its loss would harm you”","o":["Floating charge","Close-out netting","Autonomy principle","Insurable interest"],"a":[3],"s":1,"x":"Insurable interest: a real stake in the thing covered, so that its loss would harm you. Without it a policy is a wager. The Marine Insurance Act 1906 requires it at the time of the loss (s 6); an FOB or CIF buyer has it once the risk has passed, even before it owns the goods.","about":["insurable-interest"]},
{"id":"LW-subrogation","lv":"finance","d":5,"area":"Paying, securing, insuring","q":"What is meant by “Subrogation”?","o":["an insurer that has paid may cancel the policy for the rest of the year","an insurer that has paid may claim a share from the other insurers","an insurer that has paid may raise the premium on renewal","an insurer that has paid takes over the insured's own claims against others"],"a":[3],"s":1,"x":"Subrogation: an insurer that has paid takes over the insured's own claims against others. From Roman law by way of equity: the insurer can't recover more than it paid, and the insured mustn't release the wrongdoer and so lose the insurer its claim. A guarantor who pays is subrogated too.","about":["subrogation"]},
{"id":"LW-subrogation-name","lv":"finance","d":6,"area":"Paying, securing, insuring","q":"Which legal term means this? “An insurer that has paid takes over the insured's own claims against others”","o":["Floating charge","Demand guarantee","Close-out netting","Subrogation"],"a":[3],"s":1,"x":"Subrogation: an insurer that has paid takes over the insured's own claims against others. From Roman law by way of equity: the insurer can't recover more than it paid, and the insured mustn't release the wrongdoer and so lose the insurer its claim. A guarantor who pays is subrogated too.","about":["subrogation"]},
{"id":"LW-causa-proxima","lv":"finance","d":7,"area":"Paying, securing, insuring","q":"What does this mean? “Causa proxima non remota spectatur” (literally: the near cause is looked to, not the remote)","o":["a loss is paid only if it happened soon after the insured event","a wrongdoer answers only for harm to those standing near the act","a claim must be made at the place nearest to where the loss happened","an insurer pays only if an insured peril was the main cause of loss"],"a":[3],"s":1,"x":"Causa proxima non remota spectatur: an insurer pays only if an insured peril was the main cause of loss. Literally: the near cause is looked to, not the remote. Marine Insurance Act 1906, s 55: the proximate cause is the dominant or effective one, not the last in time. A torpedoed ship that sank in harbour in a storm was lost by the torpedo (Leyland Shipping v Norwich Union, 1918).","about":["causa-proxima"]},
{"id":"LW-causa-proxima-name","lv":"finance","d":8,"area":"Paying, securing, insuring","q":"Which legal term means this? “An insurer pays only if an insured peril was the main cause of loss”","o":["Lex specialis derogat legi generali","Fraus omnia corrumpit","Causa proxima non remota spectatur","Uberrimae fidei"],"a":[2],"s":1,"x":"Causa proxima non remota spectatur: an insurer pays only if an insured peril was the main cause of loss. Literally: the near cause is looked to, not the remote. Marine Insurance Act 1906, s 55: the proximate cause is the dominant or effective one, not the last in time. A torpedoed ship that sank in harbour in a storm was lost by the torpedo (Leyland Shipping v Norwich Union, 1918).","about":["causa-proxima"]},
{"id":"LW-pacta-sunt-servanda","lv":"contract","d":3,"area":"Contracts","q":"What does this mean? “Pacta sunt servanda”","o":["agreements bind only their parties, never anyone else","agreements made under pressure can be set aside by a court","agreements bind, and must be carried out in good faith","agreements bind only once they're written down and signed"],"a":[2],"s":1,"x":"Pacta sunt servanda: agreements bind, and must be carried out in good faith. Literally: agreements must be kept. The first rule of contract in the civil law, and of treaties in international law (Vienna Convention on the Law of Treaties, art. 26). Its counterweight is rebus sic stantibus.","about":["pacta-sunt-servanda"]},
{"id":"LW-pacta-sunt-servanda-name","lv":"contract","d":4,"area":"Contracts","q":"Which legal term means this? “Agreements bind, and must be carried out in good faith”","o":["Quantum meruit","Venire contra factum proprium","Audi alteram partem","Pacta sunt servanda"],"a":[3],"s":1,"x":"Pacta sunt servanda: agreements bind, and must be carried out in good faith. Literally: agreements must be kept. The first rule of contract in the civil law, and of treaties in international law (Vienna Convention on the Law of Treaties, art. 26). Its counterweight is rebus sic stantibus.","about":["pacta-sunt-servanda"]},
{"id":"LW-rebus-sic-stantibus","lv":"contract","d":5,"area":"Contracts","q":"What does this mean? “Rebus sic stantibus” (literally: things standing thus)","o":["a court leaves the parties where it finds them, ordering nothing","the existing state of affairs must be kept until a dispute is settled","a fundamental change of circumstances can end or alter an obligation","a contract is read in the light of the facts known when it was made"],"a":[2],"s":1,"x":"Rebus sic stantibus: a fundamental change of circumstances can end or alter an obligation. Literally: things standing thus. Vienna Convention on the Law of Treaties, art. 62, read narrowly. In German contract law, the Störung der Geschäftsgrundlage of § 313 BGB lets a court adjust a contract; English law has only the far stricter frustration.","about":["rebus-sic-stantibus"]},
{"id":"LW-rebus-sic-stantibus-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “A fundamental change of circumstances can end or alter an obligation”","o":["Contra proferentem","Bona fide","Culpa in contrahendo","Rebus sic stantibus"],"a":[3],"s":1,"x":"Rebus sic stantibus: a fundamental change of circumstances can end or alter an obligation. Literally: things standing thus. Vienna Convention on the Law of Treaties, art. 62, read narrowly. In German contract law, the Störung der Geschäftsgrundlage of § 313 BGB lets a court adjust a contract; English law has only the far stricter frustration.","about":["rebus-sic-stantibus"]},
{"id":"LW-invitation-to-treat","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Invitation to treat”?","o":["an offer that binds as soon as anyone accepts it by acting on it","a step that only asks for offers, like goods on a shop shelf","an offer that must stay open for a set time once it has been made","an offer that can only be accepted in the way it lays down"],"a":[1],"s":1,"x":"Invitation to treat: a step that only asks for offers, like goods on a shop shelf. Goods on a shelf (Pharmaceutical Society v Boots, 1953), adverts and price lists: the customer makes the offer and the seller accepts. An advert can be an offer if it's clear enough (Carlill v Carbolic Smoke Ball, 1893).","about":["invitation-to-treat"]},
{"id":"LW-invitation-to-treat-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “A step that only asks for offers, like goods on a shop shelf”","o":["Anticipatory breach","Promissory estoppel","Invitation to treat","Specific performance"],"a":[2],"s":1,"x":"Invitation to treat: a step that only asks for offers, like goods on a shop shelf. Goods on a shelf (Pharmaceutical Society v Boots, 1953), adverts and price lists: the customer makes the offer and the seller accepts. An advert can be an offer if it's clear enough (Carlill v Carbolic Smoke Ball, 1893).","about":["invitation-to-treat"]},
{"id":"LW-postal-rule","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Postal rule”?","o":["an offer sent by letter can't be withdrawn once it has been sent","a contract made by letter is governed by the law where it's received","an acceptance sent by letter binds when it's sent, not when it arrives","an acceptance sent by letter binds only when it arrives and is read"],"a":[2],"s":1,"x":"Postal rule: an acceptance sent by letter binds when it's sent, not when it arrives. Adams v Lindsell (1818). It never applied to instant means: a telex or an email binds when it reaches the offeror (Entores v Miles Far East, 1955). The CISG takes the other view: an acceptance takes effect when it reaches the offeror (art. 18).","about":["postal-rule"]},
{"id":"LW-postal-rule-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “An acceptance sent by letter binds when it's sent, not when it arrives”","o":["Mitigation","Consideration","Postal rule","Innominate term"],"a":[2],"s":1,"x":"Postal rule: an acceptance sent by letter binds when it's sent, not when it arrives. Adams v Lindsell (1818). It never applied to instant means: a telex or an email binds when it reaches the offeror (Entores v Miles Far East, 1955). The CISG takes the other view: an acceptance takes effect when it reaches the offeror (art. 18).","about":["postal-rule"]},
{"id":"LW-consideration","lv":"contract","d":3,"area":"Contracts","q":"What is meant by “Consideration”?","o":["the courtesy each party owes the other while the contract runs","a party's right to think an offer over before it must answer","something of value each side gives for the other's promise","a court's duty to weigh each side's case fairly before ruling"],"a":[2],"s":1,"x":"Consideration: something of value each side gives for the other's promise. What makes a promise a bargain in the common law: it must move from the promisee, needn't be adequate (a peppercorn will do), and past consideration is no consideration. Without it a promise binds only by deed; civil law needs no such thing.","about":["consideration"]},
{"id":"LW-consideration-name","lv":"contract","d":4,"area":"Contracts","q":"Which legal term means this? “Something of value each side gives for the other's promise”","o":["Consideration","Innominate term","Penalty rule","Postal rule"],"a":[0],"s":1,"x":"Consideration: something of value each side gives for the other's promise. What makes a promise a bargain in the common law: it must move from the promisee, needn't be adequate (a peppercorn will do), and past consideration is no consideration. Without it a promise binds only by deed; civil law needs no such thing.","about":["consideration"]},
{"id":"LW-privity","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Privity of contract”?","o":["a contract binds whoever later buys the goods it concerns","a contract made in private needn't be registered to bind","only the parties to an agreement can enforce it or be bound by it","a contract's terms must be kept secret from anyone outside the deal"],"a":[2],"s":1,"x":"Privity of contract: only the parties to an agreement can enforce it or be bound by it. Dunlop v Selfridge (1915). Softened by the Contracts (Rights of Third Parties) Act 1999: a third party may enforce a term that names it or is meant to benefit it, unless the contract says otherwise, as most commercial contracts do.","about":["privity"]},
{"id":"LW-privity-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “Only the parties to an agreement can enforce it or be bound by it”","o":["Time of the essence","Specific performance","Invitation to treat","Privity of contract"],"a":[3],"s":1,"x":"Privity of contract: only the parties to an agreement can enforce it or be bound by it. Dunlop v Selfridge (1915). Softened by the Contracts (Rights of Third Parties) Act 1999: a third party may enforce a term that names it or is meant to benefit it, unless the contract says otherwise, as most commercial contracts do.","about":["privity"]},
{"id":"LW-contra-proferentem","lv":"contract","d":5,"area":"Contracts","q":"What does this mean? “Contra proferentem” (literally: against the one who puts it forward)","o":["a late argument counts against the party that raises it","the party who brings a claim carries the whole burden of proving it","an unclear term is read against the party that put it forward","a party can't rely on its own breach to escape the contract"],"a":[2],"s":1,"x":"Contra proferentem: an unclear term is read against the party that put it forward. Literally: against the one who puts it forward. Strongest against exclusion clauses. English courts now reach for it only once the ordinary tools of interpretation have run out, especially between commercial parties of equal strength (Persimmon Homes v Ove Arup, 2017).","about":["contra-proferentem"]},
{"id":"LW-contra-proferentem-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “An unclear term is read against the party that put it forward”","o":["Bona fide","Culpa in contrahendo","Contra proferentem","Rebus sic stantibus"],"a":[2],"s":1,"x":"Contra proferentem: an unclear term is read against the party that put it forward. Literally: against the one who puts it forward. Strongest against exclusion clauses. English courts now reach for it only once the ordinary tools of interpretation have run out, especially between commercial parties of equal strength (Persimmon Homes v Ove Arup, 2017).","about":["contra-proferentem"]},
{"id":"LW-implied-terms","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Implied terms”?","o":["provisions the parties agreed by word of mouth but never wrote down","provisions a court strikes out because they're unfair to a consumer","provisions read into a deal because it couldn't work without them","provisions that bind only if the other side has signed beside them"],"a":[2],"s":1,"x":"Implied terms: provisions read into a deal because it couldn't work without them. Implied in fact by The Moorcock's business efficacy (1889) or the officious bystander's 'oh, of course!' (Shirlaw v Southern Foundries, 1939), never merely because reasonable (Marks & Spencer v BNP Paribas, 2015). Others are implied by law, as by the Sale of Goods Act.","about":["implied-terms"]},
{"id":"LW-implied-terms-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “Provisions read into a deal because it couldn't work without them”","o":["Implied terms","Consideration","Economic duress","Frustration"],"a":[0],"s":1,"x":"Implied terms: provisions read into a deal because it couldn't work without them. Implied in fact by The Moorcock's business efficacy (1889) or the officious bystander's 'oh, of course!' (Shirlaw v Southern Foundries, 1939), never merely because reasonable (Marks & Spencer v BNP Paribas, 2015). Others are implied by law, as by the Sale of Goods Act.","about":["implied-terms"]},
{"id":"LW-innominate-term","lv":"contract","d":7,"area":"Contracts","q":"What is meant by “Innominate term”?","o":["a term whose breach, however slight, lets the other side end the deal","a term whose breach lets the other side end the deal only if serious","a term whose breach only ever gives a claim for damages","a term the parties forgot to name, filled in by the court"],"a":[1],"s":1,"x":"Innominate term: a term whose breach lets the other side end the deal only if serious. Hongkong Fir Shipping v Kawasaki (1961): a ship unseaworthy for months didn't let the charterers walk away, as the delay didn't defeat the charter's purpose. Time clauses in commodity sales are usually conditions instead (Bunge v Tradax, 1981).","about":["innominate-term"]},
{"id":"LW-innominate-term-name","lv":"contract","d":8,"area":"Contracts","q":"Which legal term means this? “A term whose breach lets the other side end the deal only if serious”","o":["Implied terms","Anticipatory breach","Economic duress","Innominate term"],"a":[3],"s":1,"x":"Innominate term: a term whose breach lets the other side end the deal only if serious. Hongkong Fir Shipping v Kawasaki (1961): a ship unseaworthy for months didn't let the charterers walk away, as the delay didn't defeat the charter's purpose. Time clauses in commodity sales are usually conditions instead (Bunge v Tradax, 1981).","about":["innominate-term"]},
{"id":"LW-time-of-the-essence","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Time of the essence”?","o":["missing a deadline gives the other side only a claim for its loss","missing a deadline ends the contract at once, whatever either wants","missing a deadline, by however little, lets the other side terminate","missing a deadline lets the party that's late set a new one"],"a":[2],"s":1,"x":"Time of the essence: missing a deadline, by however little, lets the other side terminate. Equity treats time as not of the essence unless agreed; in mercantile contracts the courts presume the opposite. In Bunge v Tradax (1981) a buyer's notice of the ship's readiness, four days late, let the seller end an FOB sale of soya bean meal.","about":["time-of-the-essence"]},
{"id":"LW-time-of-the-essence-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “Missing a deadline, by however little, lets the other side terminate”","o":["Invitation to treat","Privity of contract","Remoteness of damage","Time of the essence"],"a":[3],"s":1,"x":"Time of the essence: missing a deadline, by however little, lets the other side terminate. Equity treats time as not of the essence unless agreed; in mercantile contracts the courts presume the opposite. In Bunge v Tradax (1981) a buyer's notice of the ship's readiness, four days late, let the seller end an FOB sale of soya bean meal.","about":["time-of-the-essence"]},
{"id":"LW-anticipatory-breach","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Anticipatory breach”?","o":["a clear refusal to perform, made well before performance falls due","a warning that performance may be late, made before the date","a failure to perform on the date it fell due, without excuse","a breach the other side forgives by carrying on with the deal"],"a":[0],"s":1,"x":"Anticipatory breach: a clear refusal to perform, made well before performance falls due. Hochster v De la Tour (1853): the innocent party may accept it and sue at once, or keep the contract alive and wait, at the risk that something meanwhile frees the other side (Avery v Bowden, 1855: the Crimean War closed Odessa).","about":["anticipatory-breach"]},
{"id":"LW-anticipatory-breach-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “A clear refusal to perform, made well before performance falls due”","o":["Subject to contract","Remoteness of damage","Time of the essence","Anticipatory breach"],"a":[3],"s":1,"x":"Anticipatory breach: a clear refusal to perform, made well before performance falls due. Hochster v De la Tour (1853): the innocent party may accept it and sue at once, or keep the contract alive and wait, at the risk that something meanwhile frees the other side (Avery v Bowden, 1855: the Crimean War closed Odessa).","about":["anticipatory-breach"]},
{"id":"LW-mitigation","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Mitigation”?","o":["a claimant can't recover loss it could reasonably have avoided","a claimant's damages are cut by its own share of blame for the loss","a claimant must give notice of its loss before it can recover","a claimant may recover the cost of a substitute, however high"],"a":[0],"s":1,"x":"Mitigation: a claimant can't recover loss it could reasonably have avoided. British Westinghouse v Underground Electric Railways (1912). In a sale, a seller who fails to deliver owes the difference between the contract and the market price, because the buyer should buy in the market (Sale of Goods Act 1979, s 51(3)).","about":["mitigation"]},
{"id":"LW-mitigation-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “A claimant can't recover loss it could reasonably have avoided”","o":["Penalty rule","Postal rule","Economic duress","Mitigation"],"a":[3],"s":1,"x":"Mitigation: a claimant can't recover loss it could reasonably have avoided. British Westinghouse v Underground Electric Railways (1912). In a sale, a seller who fails to deliver owes the difference between the contract and the market price, because the buyer should buy in the market (Sale of Goods Act 1979, s 51(3)).","about":["mitigation"]},
{"id":"LW-remoteness","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Remoteness of damage”?","o":["only loss foreseeable as likely when the deal was made is recoverable","only loss caused by the breaching party's own fault is recoverable","only loss that happens within a year of the breach is recoverable","only loss in the country where the contract was made is recoverable"],"a":[0],"s":1,"x":"Remoteness of damage: only loss foreseeable as likely when the deal was made is recoverable. Hadley v Baxendale (1854): a mill stood idle while its broken crankshaft was slow in transit, and its lost profits weren't in the carrier's contemplation. Refined for a time charter in The Achilleas (2008): a party is liable only for what it can be taken to have accepted responsibility for.","about":["remoteness"]},
{"id":"LW-remoteness-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “Only loss foreseeable as likely when the deal was made is recoverable”","o":["Subject to contract","Anticipatory breach","Time of the essence","Remoteness of damage"],"a":[3],"s":1,"x":"Remoteness of damage: only loss foreseeable as likely when the deal was made is recoverable. Hadley v Baxendale (1854): a mill stood idle while its broken crankshaft was slow in transit, and its lost profits weren't in the carrier's contemplation. Refined for a time charter in The Achilleas (2008): a party is liable only for what it can be taken to have accepted responsibility for.","about":["remoteness"]},
{"id":"LW-penalty-rule","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Penalty rule”?","o":["a sum fixed for breach isn't enforced if out of all proportion","a sum fixed for breach goes to the court, not to the injured party","a sum fixed for breach is enforced only if it equals the real loss","a sum fixed for breach is always enforced, being freely agreed"],"a":[0],"s":1,"x":"Penalty rule: a sum fixed for breach isn't enforced if out of all proportion. Cavendish Square v Makdessi and ParkingEye v Beavis (2015) replaced the old test, a genuine pre-estimate of loss (Dunlop v New Garage, 1915), with legitimate interest and proportion. French law lets a judge reduce an excessive sum instead (Code civil, art. 1231-5).","about":["penalty-rule"]},
{"id":"LW-penalty-rule-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “A sum fixed for breach isn't enforced if out of all proportion”","o":["Mitigation","Innominate term","Postal rule","Penalty rule"],"a":[3],"s":1,"x":"Penalty rule: a sum fixed for breach isn't enforced if out of all proportion. Cavendish Square v Makdessi and ParkingEye v Beavis (2015) replaced the old test, a genuine pre-estimate of loss (Dunlop v New Garage, 1915), with legitimate interest and proportion. French law lets a judge reduce an excessive sum instead (Code civil, art. 1231-5).","about":["penalty-rule"]},
{"id":"LW-specific-performance","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Specific performance”?","o":["a court order to pay a fixed sum agreed in advance for breach","a court order to return what each side received under the deal","a court order to stop doing something the contract forbids","a court order to do what was promised, not merely to pay damages"],"a":[3],"s":1,"x":"Specific performance: a court order to do what was promised, not merely to pay damages. Discretionary in English law, given only where damages won't do: land, a unique thing, rarely ordinary goods (Sale of Goods Act 1979, s 52). In German and French law it's the primary remedy.","about":["specific-performance"]},
{"id":"LW-specific-performance-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “A court order to do what was promised, not merely to pay damages”","o":["Promissory estoppel","Specific performance","Anticipatory breach","Remoteness of damage"],"a":[1],"s":1,"x":"Specific performance: a court order to do what was promised, not merely to pay damages. Discretionary in English law, given only where damages won't do: land, a unique thing, rarely ordinary goods (Sale of Goods Act 1979, s 52). In German and French law it's the primary remedy.","about":["specific-performance"]},
{"id":"LW-misrepresentation","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Misrepresentation”?","o":["a failure to mention a fact the other side would have liked to know","an honest opinion, given by an expert, that turned out wrong","a promise about the future that wasn't kept, however honest","a false statement of fact that induced the other side to contract"],"a":[3],"s":1,"x":"Misrepresentation: a false statement of fact that induced the other side to contract. It lets the misled party rescind and, under the Misrepresentation Act 1967, s 2(1), claim damages as if for fraud unless the maker proves it reasonably believed the statement true. Silence isn't a misrepresentation, except in insurance and the like.","about":["misrepresentation"]},
{"id":"LW-misrepresentation-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “A false statement of fact that induced the other side to contract”","o":["Subject to contract","Innominate term","Economic duress","Misrepresentation"],"a":[3],"s":1,"x":"Misrepresentation: a false statement of fact that induced the other side to contract. It lets the misled party rescind and, under the Misrepresentation Act 1967, s 2(1), claim damages as if for fraud unless the maker proves it reasonably believed the statement true. Silence isn't a misrepresentation, except in insurance and the like.","about":["misrepresentation"]},
{"id":"LW-economic-duress","lv":"contract","d":7,"area":"Contracts","q":"What is meant by “Economic duress”?","o":["illegitimate pressure on a business that left it no real choice","a sudden rise in costs that makes the contract ruinous to perform","hard bargaining by the stronger party over price, which courts allow","a threat of physical harm to a party, which makes its contract void"],"a":[0],"s":1,"x":"Economic duress: illegitimate pressure on a business that left it no real choice. A threat to break a contract can be enough (The Atlantic Baron, 1979); a lawful act very rarely is (Pakistan International Airline v Times Travel, 2021). The contract is voidable, and the victim must act promptly.","about":["economic-duress"]},
{"id":"LW-economic-duress-name","lv":"contract","d":8,"area":"Contracts","q":"Which legal term means this? “Illegitimate pressure on a business that left it no real choice”","o":["Consideration","Anticipatory breach","Innominate term","Economic duress"],"a":[3],"s":1,"x":"Economic duress: illegitimate pressure on a business that left it no real choice. A threat to break a contract can be enough (The Atlantic Baron, 1979); a lawful act very rarely is (Pakistan International Airline v Times Travel, 2021). The contract is voidable, and the victim must act promptly.","about":["economic-duress"]},
{"id":"LW-frustration","lv":"contract","d":3,"area":"Contracts","q":"What is meant by “Frustration”?","o":["an event no one foresaw makes performance impossible or radically different","an event no one foresaw makes performance dearer, so the price may be raised","an event no one foresaw lets the party it hurts suspend the deal awhile","an event the parties foresaw and named excuses whoever it hits"],"a":[0],"s":1,"x":"Frustration: an event no one foresaw makes performance impossible or radically different. Taylor v Caldwell (1863): the music hall burnt down. Narrow: closing the Suez Canal in 1956 didn't frustrate a CIF sale of groundnuts, shipping round the Cape being merely dearer (Tsakiroglou v Noblee Thorl, 1962). The contract ends, and the Law Reform (Frustrated Contracts) Act 1943 settles the money.","about":["frustration"]},
{"id":"LW-frustration-name","lv":"contract","d":4,"area":"Contracts","q":"Which legal term means this? “An event no one foresaw makes performance impossible or radically different”","o":["Consideration","Penalty rule","Innominate term","Frustration"],"a":[3],"s":1,"x":"Frustration: an event no one foresaw makes performance impossible or radically different. Taylor v Caldwell (1863): the music hall burnt down. Narrow: closing the Suez Canal in 1956 didn't frustrate a CIF sale of groundnuts, shipping round the Cape being merely dearer (Tsakiroglou v Noblee Thorl, 1962). The contract ends, and the Law Reform (Frustrated Contracts) Act 1943 settles the money.","about":["frustration"]},
{"id":"LW-quantum-meruit","lv":"contract","d":5,"area":"Contracts","q":"What does this mean? “Quantum meruit” (literally: as much as he deserved)","o":["a reasonable sum for work done where no price was agreed","a bonus a court may add to damages for an especially bad breach","a fee an agent earns in proportion to the deals it brought in","damages set by the judge at what the wrongdoer can afford to pay"],"a":[0],"s":1,"x":"Quantum meruit: a reasonable sum for work done where no price was agreed. Literally: as much as he deserved. A claim in unjust enrichment, or on an implied promise to pay a reasonable price; common where work began before a contract was signed. For goods, the Sale of Goods Act's reasonable price does the same (s 8).","about":["quantum-meruit"]},
{"id":"LW-quantum-meruit-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “A reasonable sum for work done where no price was agreed”","o":["Pacta sunt servanda","Rebus sic stantibus","Quantum meruit","Contra proferentem"],"a":[2],"s":1,"x":"Quantum meruit: a reasonable sum for work done where no price was agreed. Literally: as much as he deserved. A claim in unjust enrichment, or on an implied promise to pay a reasonable price; common where work began before a contract was signed. For goods, the Sale of Goods Act's reasonable price does the same (s 8).","about":["quantum-meruit"]},
{"id":"LW-culpa-in-contrahendo","lv":"contract","d":7,"area":"Contracts","q":"What does this mean? “Culpa in contrahendo” (literally: fault in contracting)","o":["a contract made by mistake about its terms, void for both sides","liability of an agent who signs a contract without authority","liability for fault while negotiating, before any deal exists","liability for a breach, shared out by each side's degree of fault"],"a":[2],"s":1,"x":"Culpa in contrahendo: liability for fault while negotiating, before any deal exists. Literally: fault in contracting. Jhering's discovery (1861), now § 311(2) BGB: breaking off talks in bad faith, or misleading the other side in them, gives a claim for wasted costs. English law has no such duty (Walford v Miles, 1992).","about":["culpa-in-contrahendo"]},
{"id":"LW-culpa-in-contrahendo-name","lv":"contract","d":8,"area":"Contracts","q":"Which legal term means this? “Liability for fault while negotiating, before any deal exists”","o":["Bona fide","Venire contra factum proprium","Pacta sunt servanda","Culpa in contrahendo"],"a":[3],"s":1,"x":"Culpa in contrahendo: liability for fault while negotiating, before any deal exists. Literally: fault in contracting. Jhering's discovery (1861), now § 311(2) BGB: breaking off talks in bad faith, or misleading the other side in them, gives a claim for wasted costs. English law has no such duty (Walford v Miles, 1992).","about":["culpa-in-contrahendo"]},
{"id":"LW-treu-und-glauben","lv":"contract","d":5,"area":"Contracts","q":"What does this mean? “Treu und Glauben” (literally: loyalty and faith)","o":["a contract made on trust needs no written form to bind","a party who trusted another's word may sue if that word is broken","every duty must be carried out as fairness and custom require","a merchant's word given on the exchange floor is binding at once"],"a":[2],"s":1,"x":"Treu und Glauben: every duty must be carried out as fairness and custom require. Literally: loyalty and faith. § 242 BGB, the most powerful clause in German private law: on it courts have built duties of disclosure, the adjustment of contracts and the bar on self-contradiction. English law has no general duty of good faith, only pieces of one.","about":["treu-und-glauben"]},
{"id":"LW-treu-und-glauben-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “Every duty must be carried out as fairness and custom require”","o":["Abstraktionsprinzip","Rebus sic stantibus","Culpa in contrahendo","Treu und Glauben"],"a":[3],"s":1,"x":"Treu und Glauben: every duty must be carried out as fairness and custom require. Literally: loyalty and faith. § 242 BGB, the most powerful clause in German private law: on it courts have built duties of disclosure, the adjustment of contracts and the bar on self-contradiction. English law has no general duty of good faith, only pieces of one.","about":["treu-und-glauben"]},
{"id":"LW-venire-contra-factum-proprium","lv":"contract","d":7,"area":"Contracts","q":"What does this mean? “Venire contra factum proprium” (literally: to come against one's own act)","o":["no one may undo a contract they signed, however unfair it is","no one may be made to give evidence against their own case","no one may go back on their own conduct to another's cost","no one may sue over a wrong they took part in themselves"],"a":[2],"s":1,"x":"Venire contra factum proprium: no one may go back on their own conduct to another's cost. Literally: to come against one's own act. A face of good faith in civil law (§ 242 BGB) and a principle of international arbitration; the common law's nearest kin is estoppel.","about":["venire-contra-factum-proprium"]},
{"id":"LW-venire-contra-factum-proprium-name","lv":"contract","d":8,"area":"Contracts","q":"Which legal term means this? “No one may go back on their own conduct to another's cost”","o":["Quid pro quo","Quantum meruit","Rebus sic stantibus","Venire contra factum proprium"],"a":[3],"s":1,"x":"Venire contra factum proprium: no one may go back on their own conduct to another's cost. Literally: to come against one's own act. A face of good faith in civil law (§ 242 BGB) and a principle of international arbitration; the common law's nearest kin is estoppel.","about":["venire-contra-factum-proprium"]},
{"id":"LW-promissory-estoppel","lv":"contract","d":7,"area":"Contracts","q":"What is meant by “Promissory estoppel”?","o":["an assurance given in talks, once relied on, makes a full binding contract","an assurance not to enforce a right, once relied on, binds though unpaid","an assurance made under seal binds though nothing was paid for it","an assurance not to sue, once given, can never be withdrawn at all"],"a":[1],"s":1,"x":"Promissory estoppel: an assurance not to enforce a right, once relied on, binds though unpaid. Central London Property Trust v High Trees House (1947): wartime rent halved by agreement couldn't be claimed back in full. A shield, not a sword: it suspends a right and can't found a claim.","about":["promissory-estoppel"]},
{"id":"LW-promissory-estoppel-name","lv":"contract","d":8,"area":"Contracts","q":"Which legal term means this? “An assurance not to enforce a right, once relied on, binds though unpaid”","o":["Specific performance","Promissory estoppel","Invitation to treat","Time of the essence"],"a":[1],"s":1,"x":"Promissory estoppel: an assurance not to enforce a right, once relied on, binds though unpaid. Central London Property Trust v High Trees House (1947): wartime rent halved by agreement couldn't be claimed back in full. A shield, not a sword: it suspends a right and can't found a claim.","about":["promissory-estoppel"]},
{"id":"LW-subject-to-contract","lv":"contract","d":5,"area":"Contracts","q":"What is meant by “Subject to contract”?","o":["the deal binds only if a regulator approves it within a set time","the deal binds now, though some details are left to be agreed","the deal binds the parties, though not their parent companies","nothing binds until the formal document is both signed and exchanged"],"a":[3],"s":1,"x":"Subject to contract: nothing binds until the formal document is both signed and exchanged. The words keep a deal open until signature, though conduct can override them (RTS Flexible Systems v Molkerei Alois Müller, 2010). In chartering, a fixture 'on subjects' (to stem, to board approval) stays open until they're lifted.","about":["subject-to-contract"]},
{"id":"LW-subject-to-contract-name","lv":"contract","d":6,"area":"Contracts","q":"Which legal term means this? “Nothing binds until the formal document is both signed and exchanged”","o":["Specific performance","Promissory estoppel","Anticipatory breach","Subject to contract"],"a":[3],"s":1,"x":"Subject to contract: nothing binds until the formal document is both signed and exchanged. The words keep a deal open until signature, though conduct can override them (RTS Flexible Systems v Molkerei Alois Müller, 2010). In chartering, a fixture 'on subjects' (to stem, to board approval) stays open until they're lifted.","about":["subject-to-contract"]},
{"id":"LW-audi-alteram-partem","lv":"disputes","d":3,"area":"Courts and arbitration","q":"What does this mean? “Audi alteram partem”","o":["no one may be condemned without a chance to answer the case","no one may be made to give evidence against themselves","no one may be tried a second time for the same offence","no one may be judged by someone with a personal stake in the outcome"],"a":[0],"s":1,"x":"Audi alteram partem: no one may be condemned without a chance to answer the case. Literally: hear the other side. With nemo iudex in causa sua, one of the two pillars of natural justice. An arbitral award made without it may be refused enforcement under the New York Convention (art. V(1)(b)).","about":["audi-alteram-partem"]},
{"id":"LW-audi-alteram-partem-name","lv":"disputes","d":4,"area":"Courts and arbitration","q":"Which legal term means this? “No one may be condemned without a chance to answer the case”","o":["Obiter dictum","Audi alteram partem","Nemo iudex in causa sua","Res judicata"],"a":[1],"s":1,"x":"Audi alteram partem: no one may be condemned without a chance to answer the case. Literally: hear the other side. With nemo iudex in causa sua, one of the two pillars of natural justice. An arbitral award made without it may be refused enforcement under the New York Convention (art. V(1)(b)).","about":["audi-alteram-partem"]},
{"id":"LW-nemo-iudex","lv":"disputes","d":3,"area":"Courts and arbitration","q":"What does this mean? “Nemo iudex in causa sua”","o":["no one may decide a case in which they have an interest","no one may bring a claim on behalf of somebody else","no one may appeal a decision they agreed to in advance","no one may be condemned without a chance to answer the case"],"a":[0],"s":1,"x":"Nemo iudex in causa sua: no one may decide a case in which they have an interest. Literally: no one is judge in their own cause. The appearance of bias is enough: the House of Lords set aside its own decision in Pinochet (1999) because Lord Hoffmann was linked to Amnesty International, a party. Arbitrators must disclose such links (Halliburton v Chubb, 2020).","about":["nemo-iudex"]},
{"id":"LW-nemo-iudex-name","lv":"disputes","d":4,"area":"Courts and arbitration","q":"Which legal term means this? “No one may decide a case in which they have an interest”","o":["Audi alteram partem","Obiter dictum","Res judicata","Nemo iudex in causa sua"],"a":[3],"s":1,"x":"Nemo iudex in causa sua: no one may decide a case in which they have an interest. Literally: no one is judge in their own cause. The appearance of bias is enough: the House of Lords set aside its own decision in Pinochet (1999) because Lord Hoffmann was linked to Amnesty International, a party. Arbitrators must disclose such links (Halliburton v Chubb, 2020).","about":["nemo-iudex"]},
{"id":"LW-res-judicata","lv":"disputes","d":3,"area":"Courts and arbitration","q":"What does this mean? “Res judicata”","o":["a matter still before one court can't be brought before another","a matter finally decided can't be fought again by the same parties","a claim can't be brought once the time allowed for bringing it has run out","a court must follow the earlier decisions of the courts above it"],"a":[1],"s":1,"x":"Res judicata: a matter finally decided can't be fought again by the same parties. Literally: a thing judged. With issue estoppel and the rule in Henderson v Henderson (1843), which bars points that should have been raised the first time. An arbitral award is res judicata between its parties too.","about":["res-judicata"]},
{"id":"LW-res-judicata-name","lv":"disputes","d":4,"area":"Courts and arbitration","q":"Which legal term means this? “A matter finally decided can't be fought again by the same parties”","o":["Stare decisis","Pro bono","Locus standi","Res judicata"],"a":[3],"s":1,"x":"Res judicata: a matter finally decided can't be fought again by the same parties. Literally: a thing judged. With issue estoppel and the rule in Henderson v Henderson (1843), which bars points that should have been raised the first time. An arbitral award is res judicata between its parties too.","about":["res-judicata"]},
{"id":"LW-stare-decisis","lv":"disputes","d":3,"area":"Courts and arbitration","q":"What does this mean? “Stare decisis”","o":["a judge must decide the case on the evidence given, nothing else","a matter finally decided can't be fought again between the same parties","courts follow the earlier rulings of higher courts on the same point","a judgment stays in force until an appeal court sets it aside"],"a":[2],"s":1,"x":"Stare decisis: courts follow the earlier rulings of higher courts on the same point. Literally: to stand by things decided. Only the ratio decidendi binds, not obiter dicta. The UK Supreme Court may depart from its own decisions (Practice Statement, 1966); civil law courts follow settled case law without a formal rule.","about":["stare-decisis"]},
{"id":"LW-stare-decisis-name","lv":"disputes","d":4,"area":"Courts and arbitration","q":"Which legal term means this? “Courts follow the earlier rulings of higher courts on the same point”","o":["Obiter dictum","Audi alteram partem","Res judicata","Stare decisis"],"a":[3],"s":1,"x":"Stare decisis: courts follow the earlier rulings of higher courts on the same point. Literally: to stand by things decided. Only the ratio decidendi binds, not obiter dicta. The UK Supreme Court may depart from its own decisions (Practice Statement, 1966); civil law courts follow settled case law without a formal rule.","about":["stare-decisis"]},
{"id":"LW-ratio-decidendi","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What does this mean? “Ratio decidendi” (literally: the reason for deciding)","o":["the reasons a court gives for awarding costs to one side","the judge's remarks in passing, which persuade but don't bind","the legal reasoning a decision rests on, binding later courts","the facts the court found proved, on which it based the result"],"a":[2],"s":1,"x":"Ratio decidendi: the legal reasoning a decision rests on, binding later courts. Literally: the reason for deciding. Its opposite is obiter dictum, a thing said by the way. Finding the ratio of a case with several judgments is half of a common lawyer's training.","about":["ratio-decidendi"]},
{"id":"LW-ratio-decidendi-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “The legal reasoning a decision rests on, binding later courts”","o":["Obiter dictum","Ratio decidendi","Res judicata","Locus standi"],"a":[1],"s":1,"x":"Ratio decidendi: the legal reasoning a decision rests on, binding later courts. Literally: the reason for deciding. Its opposite is obiter dictum, a thing said by the way. Finding the ratio of a case with several judgments is half of a common lawyer's training.","about":["ratio-decidendi"]},
{"id":"LW-obiter-dictum","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What does this mean? “Obiter dictum” (literally: a thing said by the way)","o":["a judgment given without reasons, as some courts may do","a remark in a judgment not needed for the result, so not binding","a ruling given before the full hearing, to keep things as they are","a judge's note to the parties, sent after the judgment is given"],"a":[1],"s":1,"x":"Obiter dictum: a remark in a judgment not needed for the result, so not binding. Literally: a thing said by the way. Not binding, but a considered obiter from a high court is often followed: Hedley Byrne v Heller (1964), which gave English law liability for negligent misstatement, was strictly obiter.","about":["obiter-dictum"]},
{"id":"LW-obiter-dictum-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “A remark in a judgment not needed for the result, so not binding”","o":["Locus standi","Lis pendens","Lex fori","Obiter dictum"],"a":[3],"s":1,"x":"Obiter dictum: a remark in a judgment not needed for the result, so not binding. Literally: a thing said by the way. Not binding, but a considered obiter from a high court is often followed: Hedley Byrne v Heller (1964), which gave English law liability for negligent misstatement, was strictly obiter.","about":["obiter-dictum"]},
{"id":"LW-ei-incumbit-probatio","lv":"disputes","d":3,"area":"Courts and arbitration","q":"What does this mean? “Ei incumbit probatio qui dicit, non qui negat” (literally: the proof lies on the one who asserts, not on the one who denies)","o":["the side with more witnesses on a fact wins it, unless discredited","a witness who asserts a fact must swear to it before it's heard","the claimant must prove its case; the defendant needn't disprove it","the defendant must disprove the claim once the claimant states it"],"a":[2],"s":1,"x":"Ei incumbit probatio qui dicit, non qui negat: the claimant must prove its case; the defendant needn't disprove it. Literally: the proof lies on the one who asserts, not on the one who denies. Paul, in Justinian's Digest (22.3.2), and behind the presumption of innocence (European Convention on Human Rights, art. 6(2)). In civil cases the standard is the balance of probabilities; in criminal ones, beyond reasonable doubt.","about":["ei-incumbit-probatio"]},
{"id":"LW-ei-incumbit-probatio-name","lv":"disputes","d":4,"area":"Courts and arbitration","q":"Which legal term means this? “The claimant must prove its case; the defendant needn't disprove it”","o":["Pacta tertiis nec nocent nec prosunt","Expressio unius est exclusio alterius","Nemo iudex in causa sua","Ei incumbit probatio qui dicit, non qui negat"],"a":[3],"s":1,"x":"Ei incumbit probatio qui dicit, non qui negat: the claimant must prove its case; the defendant needn't disprove it. Literally: the proof lies on the one who asserts, not on the one who denies. Paul, in Justinian's Digest (22.3.2), and behind the presumption of innocence (European Convention on Human Rights, art. 6(2)). In civil cases the standard is the balance of probabilities; in criminal ones, beyond reasonable doubt.","about":["ei-incumbit-probatio"]},
{"id":"LW-locus-standi","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What does this mean? “Locus standi” (literally: a place to stand)","o":["the place where the thing in dispute lies, whose law governs it","the right to bring a claim, by having a sufficient interest in it","the right of a party to be present in person at its own hearing","the court where a claim must be brought, by where the defendant lives"],"a":[1],"s":1,"x":"Locus standi: the right to bring a claim, by having a sufficient interest in it. Literally: a place to stand. In judicial review, a 'sufficient interest in the matter'. Before the EU's courts, a private party may challenge an act only if it concerns it directly and individually (Plaumann, 1963).","about":["locus-standi"]},
{"id":"LW-locus-standi-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “The right to bring a claim, by having a sufficient interest in it”","o":["Stare decisis","Lex fori","Locus standi","Ratio decidendi"],"a":[2],"s":1,"x":"Locus standi: the right to bring a claim, by having a sufficient interest in it. Literally: a place to stand. In judicial review, a 'sufficient interest in the matter'. Before the EU's courts, a private party may challenge an act only if it concerns it directly and individually (Plaumann, 1963).","about":["locus-standi"]},
{"id":"LW-forum-non-conveniens","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What does this mean? “Forum non conveniens” (literally: not a suitable forum)","o":["a court may refuse a case the parties agreed to arbitrate instead","a court may hold a hearing by video if its own building is unsuitable","a court may refuse a case brought only to delay or harass the defendant","a court may decline a case that another country's courts should hear"],"a":[3],"s":1,"x":"Forum non conveniens: a court may decline a case that another country's courts should hear. Literally: not a suitable forum. The Spiliada (1987): an English court stays its proceedings where another forum is clearly more appropriate for the interests of the parties and the ends of justice. EU courts may not use it (Owusu v Jackson, 2005).","about":["forum-non-conveniens"]},
{"id":"LW-forum-non-conveniens-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “A court may decline a case that another country's courts should hear”","o":["Stare decisis","Locus standi","Res judicata","Forum non conveniens"],"a":[3],"s":1,"x":"Forum non conveniens: a court may decline a case that another country's courts should hear. Literally: not a suitable forum. The Spiliada (1987): an English court stays its proceedings where another forum is clearly more appropriate for the interests of the parties and the ends of justice. EU courts may not use it (Owusu v Jackson, 2005).","about":["forum-non-conveniens"]},
{"id":"LW-lis-pendens","lv":"disputes","d":7,"area":"Courts and arbitration","q":"What does this mean? “Lis pendens” (literally: a suit pending)","o":["a claim not yet decided may be dropped without paying the costs","a claim may be paused while the parties try to settle it","a dispute already before one court can't be begun in another","a claim can't be brought until an earlier appeal is decided"],"a":[2],"s":1,"x":"Lis pendens: a dispute already before one court can't be begun in another. Literally: a suit pending. Brussels I (recast), art. 29: the court second seised waits until the first decides whether it has jurisdiction, though a court chosen in an exclusive jurisdiction clause now goes first (art. 31(2)), ending the 'Italian torpedo'.","about":["lis-pendens"]},
{"id":"LW-lis-pendens-name","lv":"disputes","d":8,"area":"Courts and arbitration","q":"Which legal term means this? “A dispute already before one court can't be begun in another”","o":["Obiter dictum","Ratio decidendi","Res judicata","Lis pendens"],"a":[3],"s":1,"x":"Lis pendens: a dispute already before one court can't be begun in another. Literally: a suit pending. Brussels I (recast), art. 29: the court second seised waits until the first decides whether it has jurisdiction, though a court chosen in an exclusive jurisdiction clause now goes first (art. 31(2)), ending the 'Italian torpedo'.","about":["lis-pendens"]},
{"id":"LW-lex-fori","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What does this mean? “Lex fori” (literally: the law of the forum)","o":["the law of the court hearing the case, which governs its procedure","the law of the place the contract was signed, which governs it","the law the parties chose, which every court must apply","the law of the market where goods were sold, which governs the sale"],"a":[0],"s":1,"x":"Lex fori: the law of the court hearing the case, which governs its procedure. Literally: the law of the forum. Procedure is always for the lex fori. The law of the contract is the parties' choice or is found by rules such as Rome I, which the UK kept after Brexit.","about":["lex-fori"]},
{"id":"LW-lex-fori-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “The law of the court hearing the case, which governs its procedure”","o":["Obiter dictum","Locus standi","Res judicata","Lex fori"],"a":[3],"s":1,"x":"Lex fori: the law of the court hearing the case, which governs its procedure. Literally: the law of the forum. Procedure is always for the lex fori. The law of the contract is the parties' choice or is found by rules such as Rome I, which the UK kept after Brexit.","about":["lex-fori"]},
{"id":"LW-kompetenz-kompetenz","lv":"disputes","d":7,"area":"Courts and arbitration","q":"What does this mean? “Kompetenz-Kompetenz” (literally: competence-competence)","o":["a tribunal must give way to the courts on any point of law","a court must check an arbitrator's qualifications before the hearing","a tribunal of two arbitrators names a third to chair it","an arbitral tribunal may rule on its own jurisdiction"],"a":[3],"s":1,"x":"Kompetenz-Kompetenz: an arbitral tribunal may rule on its own jurisdiction. Literally: competence-competence. UNCITRAL Model Law, art. 16; Arbitration Act 1996, s 30. The tribunal's own ruling isn't final: the courts of the seat may review it (s 67).","about":["kompetenz-kompetenz"]},
{"id":"LW-kompetenz-kompetenz-name","lv":"disputes","d":8,"area":"Courts and arbitration","q":"Which legal term means this? “An arbitral tribunal may rule on its own jurisdiction”","o":["Obiter dictum","Forum non conveniens","Abstraktionsprinzip","Kompetenz-Kompetenz"],"a":[3],"s":1,"x":"Kompetenz-Kompetenz: an arbitral tribunal may rule on its own jurisdiction. Literally: competence-competence. UNCITRAL Model Law, art. 16; Arbitration Act 1996, s 30. The tribunal's own ruling isn't final: the courts of the seat may review it (s 67).","about":["kompetenz-kompetenz"]},
{"id":"LW-separability","lv":"disputes","d":7,"area":"Courts and arbitration","q":"What is meant by “Separability”?","o":["an arbitration clause covers only disputes arising after signing","an arbitration clause falls with the contract it's part of","an arbitration clause survives even if the main contract is held void","an arbitration clause must be signed separately from the contract"],"a":[2],"s":1,"x":"Separability: an arbitration clause survives even if the main contract is held void. Arbitration Act 1996, s 7. Fiona Trust v Privalov (2007): a claim that the charters were procured by bribery still went to arbitration, the clause read to cover every dispute from the relationship.","about":["separability"]},
{"id":"LW-separability-name","lv":"disputes","d":8,"area":"Courts and arbitration","q":"Which legal term means this? “An arbitration clause survives even if the main contract is held void”","o":["Separability","Without prejudice","Limitation period","New York Convention"],"a":[0],"s":1,"x":"Separability: an arbitration clause survives even if the main contract is held void. Arbitration Act 1996, s 7. Fiona Trust v Privalov (2007): a claim that the charters were procured by bribery still went to arbitration, the clause read to cover every dispute from the relationship.","about":["separability"]},
{"id":"LW-seat-of-arbitration","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What is meant by “Seat of arbitration”?","o":["the place where the hearings must be held under the contract","the place where the losing party has to pay the award in full","the legal home of the case, whose courts can set an award aside","the country whose law the chair of the tribunal practises"],"a":[2],"s":1,"x":"Seat of arbitration: the legal home of the case, whose courts can set an award aside. A legal concept, not a physical one: hearings can be held in Geneva with London as the seat (Arbitration Act 1996, s 3). The courts of the seat hear challenges to the award and can set it aside; elsewhere it can only be refused enforcement. The Arbitration Act 2025 makes the law of the seat govern the arbitration agreement unless the parties expressly choose another.","about":["seat-of-arbitration"]},
{"id":"LW-seat-of-arbitration-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “The legal home of the case, whose courts can set an award aside”","o":["Anticipatory breach","Seat of arbitration","Separability","Limitation period"],"a":[1],"s":1,"x":"Seat of arbitration: the legal home of the case, whose courts can set an award aside. A legal concept, not a physical one: hearings can be held in Geneva with London as the seat (Arbitration Act 1996, s 3). The courts of the seat hear challenges to the award and can set it aside; elsewhere it can only be refused enforcement. The Arbitration Act 2025 makes the law of the seat govern the arbitration agreement unless the parties expressly choose another.","about":["seat-of-arbitration"]},
{"id":"LW-new-york-convention","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What is meant by “New York Convention”?","o":["the treaty that set up the UN's court for disputes between states","the treaty under which arbitral awards are enforced around the world","the treaty under which court judgments are enforced around the world","the treaty that founded the ICC's court of arbitration in Paris"],"a":[1],"s":1,"x":"New York Convention: the treaty under which arbitral awards are enforced around the world. The Convention on the Recognition and Enforcement of Foreign Arbitral Awards (1958), with over 170 states party: an award may be refused only on the narrow grounds of its article V. It's why commodity disputes go to GAFTA, FOSFA, LMAA or ICC arbitration rather than to court.","about":["new-york-convention"]},
{"id":"LW-new-york-convention-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “The treaty under which arbitral awards are enforced around the world”","o":["Without prejudice","New York Convention","Freezing injunction","Anticipatory breach"],"a":[1],"s":1,"x":"New York Convention: the treaty under which arbitral awards are enforced around the world. The Convention on the Recognition and Enforcement of Foreign Arbitral Awards (1958), with over 170 states party: an award may be refused only on the narrow grounds of its article V. It's why commodity disputes go to GAFTA, FOSFA, LMAA or ICC arbitration rather than to court.","about":["new-york-convention"]},
{"id":"LW-freezing-injunction","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What is meant by “Freezing injunction”?","o":["a court order stopping a defendant from moving assets out of reach","a court order seizing a ship as security for a claim against it","a court order stopping a party from suing in another country","a court order letting a claimant search the defendant's premises"],"a":[0],"s":1,"x":"Freezing injunction: a court order stopping a defendant from moving assets out of reach. Once a Mareva injunction, after Mareva Compania Naviera v International Bulkcarriers (1975), a claim for charter hire. It can reach assets worldwide, and a bank served with one must freeze the accounts at once. Its sibling, the Anton Piller search order, came a year later.","about":["freezing-injunction"]},
{"id":"LW-freezing-injunction-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “A court order stopping a defendant from moving assets out of reach”","o":["Without prejudice","Anticipatory breach","Anti-suit injunction","Freezing injunction"],"a":[3],"s":1,"x":"Freezing injunction: a court order stopping a defendant from moving assets out of reach. Once a Mareva injunction, after Mareva Compania Naviera v International Bulkcarriers (1975), a claim for charter hire. It can reach assets worldwide, and a bank served with one must freeze the accounts at once. Its sibling, the Anton Piller search order, came a year later.","about":["freezing-injunction"]},
{"id":"LW-anti-suit-injunction","lv":"disputes","d":7,"area":"Courts and arbitration","q":"What is meant by “Anti-suit injunction”?","o":["an order stopping a party from suing abroad in breach of agreement","an order letting a foreign judgment be enforced as a local one","an order striking out a claim brought only to harass the other side","an order stopping a defendant from moving its assets out of reach"],"a":[0],"s":1,"x":"Anti-suit injunction: an order stopping a party from suing abroad in breach of agreement. Aimed at the party, not the foreign court; English courts grant them readily to enforce arbitration and jurisdiction clauses. While the UK was in the Brussels regime they couldn't be used against proceedings in EU courts (West Tankers, 2009).","about":["anti-suit-injunction"]},
{"id":"LW-anti-suit-injunction-name","lv":"disputes","d":8,"area":"Courts and arbitration","q":"Which legal term means this? “An order stopping a party from suing abroad in breach of agreement”","o":["Separability","New York Convention","Clean bill of lading","Anti-suit injunction"],"a":[3],"s":1,"x":"Anti-suit injunction: an order stopping a party from suing abroad in breach of agreement. Aimed at the party, not the foreign court; English courts grant them readily to enforce arbitration and jurisdiction clauses. While the UK was in the Brussels regime they couldn't be used against proceedings in EU courts (West Tankers, 2009).","about":["anti-suit-injunction"]},
{"id":"LW-without-prejudice","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What is meant by “Without prejudice”?","o":["talks to settle a dispute can't be shown to the court later","a concession made now doesn't stop the party arguing it later","a settlement offer binds the offeror until the other side answers","a judge must hold no earlier view of the parties or the case"],"a":[0],"s":1,"x":"Without prejudice: talks to settle a dispute can't be shown to the court later. Protects genuine attempts to settle (Rush & Tompkins v Greater London Council, 1989), unless there's unambiguous impropriety. 'Without prejudice save as to costs' (a Calderbank offer) can be shown to the judge when costs are decided.","about":["without-prejudice"]},
{"id":"LW-without-prejudice-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “Talks to settle a dispute can't be shown to the court later”","o":["Limitation period","Anti-suit injunction","Seat of arbitration","Without prejudice"],"a":[3],"s":1,"x":"Without prejudice: talks to settle a dispute can't be shown to the court later. Protects genuine attempts to settle (Rush & Tompkins v Greater London Council, 1989), unless there's unambiguous impropriety. 'Without prejudice save as to costs' (a Calderbank offer) can be shown to the judge when costs are decided.","about":["without-prejudice"]},
{"id":"LW-limitation-period","lv":"disputes","d":5,"area":"Courts and arbitration","q":"What is meant by “Limitation period”?","o":["the cap on damages a party can claim under the contract","the time allowed to bring a claim, after which it's barred","the time a buyer has to reject goods once they're delivered","the time a court has to give judgment after the hearing"],"a":[1],"s":1,"x":"Limitation period: the time allowed to bring a claim, after which it's barred. In England six years for contract and tort and twelve for a deed (Limitation Act 1980); three years in Germany (§ 195 BGB) and five in France, from when the claimant knew. Cargo claims under the Hague-Visby Rules: one year.","about":["limitation-period"]},
{"id":"LW-limitation-period-name","lv":"disputes","d":6,"area":"Courts and arbitration","q":"Which legal term means this? “The time allowed to bring a claim, after which it's barred”","o":["Close-out netting","Anti-suit injunction","Without prejudice","Limitation period"],"a":[3],"s":1,"x":"Limitation period: the time allowed to bring a claim, after which it's barred. In England six years for contract and tort and twelve for a deed (Limitation Act 1980); three years in Germany (§ 195 BGB) and five in France, from when the claimant knew. Cargo claims under the Hague-Visby Rules: one year.","about":["limitation-period"]},
{"id":"LW-cuius-est-solum","lv":"property","d":5,"area":"Property and equity","q":"What does this mean? “Cuius est solum, eius est usque ad caelum et ad inferos” (literally: whoever owns the soil owns up to the sky and down to the depths)","o":["a landowner owns the air above and the ground below, within reason","a landowner owns the shore down to the low-water mark of the sea","a landowner owns whatever is found buried on the land, even treasure","a landowner may build as high as it likes, whatever the neighbours say"],"a":[0],"s":1,"x":"Cuius est solum: a landowner owns the air above and the ground below, within reason. Literally: whoever owns the soil owns up to the sky and down to the depths. Accursius's gloss, taken up by Coke and Blackstone. Cut back by the air age: an owner's airspace reaches only as high as its ordinary use needs (Bernstein v Skyviews, 1978), and oil, gas and coal beneath British land belong to the state.","about":["cuius-est-solum"]},
{"id":"LW-cuius-est-solum-name","lv":"property","d":6,"area":"Property and equity","q":"Which legal term means this? “A landowner owns the air above and the ground below, within reason”","o":["Superficies solo cedit","Cuius est solum","Prior tempore, potior iure","Res nullius"],"a":[1],"s":1,"x":"Cuius est solum: a landowner owns the air above and the ground below, within reason. Literally: whoever owns the soil owns up to the sky and down to the depths. Accursius's gloss, taken up by Coke and Blackstone. Cut back by the air age: an owner's airspace reaches only as high as its ordinary use needs (Bernstein v Skyviews, 1978), and oil, gas and coal beneath British land belong to the state.","about":["cuius-est-solum"]},
{"id":"LW-superficies-solo-cedit","lv":"property","d":7,"area":"Property and equity","q":"What does this mean? “Superficies solo cedit” (literally: what is on the surface goes with the soil)","o":["rights over land give way to rights over the buildings on it","a building on borrowed land may be taken away by whoever built it","a right over the surface lapses once the land beneath is sold","whatever is built on or fixed to land belongs to the landowner"],"a":[3],"s":1,"x":"Superficies solo cedit: whatever is built on or fixed to land belongs to the landowner. Literally: what is on the surface goes with the soil. Roman law, and still German law (§ 94 BGB); the common law's fixtures follow it. Its exceptions make modern property: leases, flats, and the German Erbbaurecht, a building on another's land for decades.","about":["superficies-solo-cedit"]},
{"id":"LW-superficies-solo-cedit-name","lv":"property","d":8,"area":"Property and equity","q":"Which legal term means this? “Whatever is built on or fixed to land belongs to the landowner”","o":["Beati possidentes","Nemo dat quod non habet","Res nullius","Superficies solo cedit"],"a":[3],"s":1,"x":"Superficies solo cedit: whatever is built on or fixed to land belongs to the landowner. Literally: what is on the surface goes with the soil. Roman law, and still German law (§ 94 BGB); the common law's fixtures follow it. Its exceptions make modern property: leases, flats, and the German Erbbaurecht, a building on another's land for decades.","about":["superficies-solo-cedit"]},
{"id":"LW-res-nullius","lv":"property","d":5,"area":"Property and equity","q":"What does this mean? “Res nullius” (literally: nobody's thing)","o":["a thing whose owner died without heirs, so it goes to the crown","a thing owned by no one, which becomes the first taker's","a thing that can never be owned, like the air or the open sea","a thing so worthless that no court will hear a claim for it"],"a":[1],"s":1,"x":"Res nullius: a thing owned by no one, which becomes the first taker's. Literally: nobody's thing. Wild animals and fish, abandoned things: ownership by taking (occupatio). Its cousin terra nullius, land belonging to no state, was the excuse for many colonial claims, rejected for Australia in Mabo (1992).","about":["res-nullius"]},
{"id":"LW-res-nullius-name","lv":"property","d":6,"area":"Property and equity","q":"Which legal term means this? “A thing owned by no one, which becomes the first taker's”","o":["Beati possidentes","Res nullius","Lex situs","Superficies solo cedit"],"a":[1],"s":1,"x":"Res nullius: a thing owned by no one, which becomes the first taker's. Literally: nobody's thing. Wild animals and fish, abandoned things: ownership by taking (occupatio). Its cousin terra nullius, land belonging to no state, was the excuse for many colonial claims, rejected for Australia in Mabo (1992).","about":["res-nullius"]},
{"id":"LW-adverse-possession","lv":"property","d":5,"area":"Property and equity","q":"What is meant by “Adverse possession”?","o":["title gained by buying land in good faith from a non-owner","title gained by holding land openly as if owner for long enough","title gained by the state over land whose owner can't be found","title gained by a tenant who has paid rent for twenty years"],"a":[1],"s":1,"x":"Adverse possession: title gained by holding land openly as if owner for long enough. Twelve years for unregistered land in England (Limitation Act 1980); for registered land, ten years and then an application the owner can usually defeat (Land Registration Act 2002). Roman law's usucapio; in Germany, ten years for movables (§ 937 BGB).","about":["adverse-possession"]},
{"id":"LW-adverse-possession-name","lv":"property","d":6,"area":"Property and equity","q":"Which legal term means this? “Title gained by holding land openly as if owner for long enough”","o":["Insurable interest","Trust","Bailment","Adverse possession"],"a":[3],"s":1,"x":"Adverse possession: title gained by holding land openly as if owner for long enough. Twelve years for unregistered land in England (Limitation Act 1980); for registered land, ten years and then an application the owner can usually defeat (Land Registration Act 2002). Roman law's usucapio; in Germany, ten years for movables (§ 937 BGB).","about":["adverse-possession"]},
{"id":"LW-prior-tempore","lv":"property","d":5,"area":"Property and equity","q":"What does this mean? “Prior tempore, potior iure”","o":["of two rights over the same thing, the registered one prevails","of two claims, the one brought to court first is heard first","of two laws on the same point, the later one prevails","of two rights over the same thing, the earlier one prevails"],"a":[3],"s":1,"x":"Prior tempore, potior iure: of two rights over the same thing, the earlier one prevails. Literally: earlier in time, stronger in right. The rule for competing interests in equity and for security over the same asset, unless registration or notice reorders them: ships' mortgages, for instance, rank by the date they were registered.","about":["prior-tempore"]},
{"id":"LW-prior-tempore-name","lv":"property","d":6,"area":"Property and equity","q":"Which legal term means this? “Of two rights over the same thing, the earlier one prevails”","o":["Lex situs","Beati possidentes","Cuius est solum","Prior tempore, potior iure"],"a":[3],"s":1,"x":"Prior tempore, potior iure: of two rights over the same thing, the earlier one prevails. Literally: earlier in time, stronger in right. The rule for competing interests in equity and for security over the same asset, unless registration or notice reorders them: ships' mortgages, for instance, rank by the date they were registered.","about":["prior-tempore"]},
{"id":"LW-bona-fide-purchaser","lv":"property","d":7,"area":"Property and equity","q":"What is meant by “Bona fide purchaser”?","o":["a buyer at a public auction takes free of any claim to the goods sold","a buyer who pays full value is always safe from the true owner","a buyer acting in good faith may keep goods later found stolen","a buyer for value without notice takes free of equitable claims"],"a":[3],"s":1,"x":"Bona fide purchaser: a buyer for value without notice takes free of equitable claims. 'Equity's darling': a purchaser of the legal title for value without notice defeats earlier equitable interests, such as a beneficiary's under a trust. Notice includes what proper inquiries would have shown.","about":["bona-fide-purchaser"]},
{"id":"LW-bona-fide-purchaser-name","lv":"property","d":8,"area":"Property and equity","q":"Which legal term means this? “A buyer for value without notice takes free of equitable claims”","o":["Freezing injunction","Adverse possession","Bona fide purchaser","Bailment"],"a":[2],"s":1,"x":"Bona fide purchaser: a buyer for value without notice takes free of equitable claims. 'Equity's darling': a purchaser of the legal title for value without notice defeats earlier equitable interests, such as a beneficiary's under a trust. Notice includes what proper inquiries would have shown.","about":["bona-fide-purchaser"]},
{"id":"LW-trust","lv":"property","d":3,"area":"Property and equity","q":"What is meant by “Trust”?","o":["property held by one person for the benefit of another","property owned in shares by several people at once","property pledged to a lender until a debt is repaid","property lent to another, to be returned in the same kind"],"a":[0],"s":1,"x":"Trust: property held by one person for the benefit of another. Equity's great invention: the trustee holds the legal title, the beneficiary the benefit, and trust property is safe from the trustee's creditors. A Quistclose trust (Barclays Bank v Quistclose, 1970) keeps money lent for one purpose apart if the borrower fails.","about":["trust"]},
{"id":"LW-trust-name","lv":"property","d":4,"area":"Property and equity","q":"Which legal term means this? “Property held by one person for the benefit of another”","o":["Adverse possession","Laytime","Bona fide purchaser","Trust"],"a":[3],"s":1,"x":"Trust: property held by one person for the benefit of another. Equity's great invention: the trustee holds the legal title, the beneficiary the benefit, and trust property is safe from the trustee's creditors. A Quistclose trust (Barclays Bank v Quistclose, 1970) keeps money lent for one purpose apart if the borrower fails.","about":["trust"]},
{"id":"LW-clean-hands","lv":"property","d":3,"area":"Property and equity","q":"What does this mean? “He who comes to equity must come with clean hands”","o":["a claimant must show it has no other remedy at law","a claimant must bring every claim it has in a single action","a claimant must first pay whatever it owes the other side","a claimant who acted wrongly in the matter is refused relief"],"a":[3],"s":1,"x":"He who comes to equity must come with clean hands: a claimant who acted wrongly in the matter is refused relief. The misconduct must touch the very matter claimed, not the claimant's character at large. Its partner: he who seeks equity must do equity.","about":["clean-hands"]},
{"id":"LW-clean-hands-name","lv":"property","d":4,"area":"Property and equity","q":"Which legal term means this? “A claimant who acted wrongly in the matter is refused relief”","o":["En fait de meubles, la possession vaut titre","Superficies solo cedit","Ei incumbit probatio qui dicit, non qui negat","He who comes to equity must come with clean hands"],"a":[3],"s":1,"x":"He who comes to equity must come with clean hands: a claimant who acted wrongly in the matter is refused relief. The misconduct must touch the very matter claimed, not the claimant's character at large. Its partner: he who seeks equity must do equity.","about":["clean-hands"]},
{"id":"LW-vigilantibus","lv":"property","d":5,"area":"Property and equity","q":"What does this mean? “Vigilantibus non dormientibus aequitas subvenit” (literally: equity helps the watchful, not those who sleep)","o":["a party who watches over its goods may claim for their loss","a party absent from its own hearing loses the case by default","a party who never read a contract is still bound by it","a claimant who delays unreasonably may lose its remedy"],"a":[3],"s":1,"x":"Vigilantibus non dormientibus aequitas subvenit: a claimant who delays unreasonably may lose its remedy. Literally: equity helps the watchful, not those who sleep. Laches: delay that makes relief unjust bars it, even within any limitation period. In English, 'delay defeats equity'.","about":["vigilantibus"]},
{"id":"LW-vigilantibus-name","lv":"property","d":6,"area":"Property and equity","q":"Which legal term means this? “A claimant who delays unreasonably may lose its remedy”","o":["Vigilantibus non dormientibus aequitas subvenit","Pacta tertiis nec nocent nec prosunt","Lex specialis derogat legi generali","Actus non facit reum nisi mens sit rea"],"a":[0],"s":1,"x":"Vigilantibus non dormientibus aequitas subvenit: a claimant who delays unreasonably may lose its remedy. Literally: equity helps the watchful, not those who sleep. Laches: delay that makes relief unjust bars it, even within any limitation period. In English, 'delay defeats equity'.","about":["vigilantibus"]},
{"id":"LW-regards-as-done","lv":"property","d":7,"area":"Property and equity","q":"What does this mean? “Equity regards as done that which ought to be done”","o":["a promise made is treated as kept until it's shown to be broken","a binding agreement to transfer is treated as already carried out","a debt is treated as paid once the creditor has been told of it","a work begun is treated as finished for paying the builder"],"a":[1],"s":1,"x":"Equity regards as done that which ought to be done: a binding agreement to transfer is treated as already carried out. So a buyer under a contract for land owns it in equity before completion, and an agreement for a lease is as good as a lease (Walsh v Lonsdale, 1882).","about":["regards-as-done"]},
{"id":"LW-regards-as-done-name","lv":"property","d":8,"area":"Property and equity","q":"Which legal term means this? “A binding agreement to transfer is treated as already carried out”","o":["Actus non facit reum nisi mens sit rea","Prior tempore, potior iure","He who comes to equity must come with clean hands","Equity regards as done that which ought to be done"],"a":[3],"s":1,"x":"Equity regards as done that which ought to be done: a binding agreement to transfer is treated as already carried out. So a buyer under a contract for land owns it in equity before completion, and an agreement for a lease is as good as a lease (Walsh v Lonsdale, 1882).","about":["regards-as-done"]},
{"id":"LW-abstraktionsprinzip","lv":"property","d":7,"area":"Property and equity","q":"What does this mean? “Abstraktionsprinzip” (literally: the principle of abstraction)","o":["a claim for money is a right in the abstract, not to any thing","a contract's terms are read in the abstract, without their context","a company is an abstract person, separate from its members","a transfer of ownership stands apart from the sale that caused it"],"a":[3],"s":1,"x":"Abstraktionsprinzip: a transfer of ownership stands apart from the sale that caused it. Literally: the principle of abstraction. The German divide between the obligation (the sale, § 433 BGB) and the transfer that carries it out (agreement and delivery, § 929): if the sale is void, ownership still passes, and the seller's remedy is unjust enrichment. French law passes ownership by the contract itself.","about":["abstraktionsprinzip"]},
{"id":"LW-abstraktionsprinzip-name","lv":"property","d":8,"area":"Property and equity","q":"Which legal term means this? “A transfer of ownership stands apart from the sale that caused it”","o":["Beati possidentes","Prior tempore, potior iure","Cuius est solum","Abstraktionsprinzip"],"a":[3],"s":1,"x":"Abstraktionsprinzip: a transfer of ownership stands apart from the sale that caused it. Literally: the principle of abstraction. The German divide between the obligation (the sale, § 433 BGB) and the transfer that carries it out (agreement and delivery, § 929): if the sale is void, ownership still passes, and the seller's remedy is unjust enrichment. French law passes ownership by the contract itself.","about":["abstraktionsprinzip"]},
{"id":"LW-bailment","lv":"property","d":5,"area":"Property and equity","q":"What is meant by “Bailment”?","o":["a charge on goods registered as security for a lender","possession of goods given to another without giving up ownership","release of a prisoner before trial against a sum of money","ownership of goods given to another while keeping possession of them"],"a":[1],"s":1,"x":"Bailment: possession of goods given to another without giving up ownership. A carrier, a warehouse, a tank terminal: each holds as bailee, bound to take reasonable care and to deliver to the bailor or its order. Oil of several owners mixed in one tank is owned in common, each by its share (Indian Oil v Greenstone Shipping, 1988).","about":["bailment"]},
{"id":"LW-bailment-name","lv":"property","d":6,"area":"Property and equity","q":"Which legal term means this? “Possession of goods given to another without giving up ownership”","o":["Incoterms","Laytime","Trust","Bailment"],"a":[3],"s":1,"x":"Bailment: possession of goods given to another without giving up ownership. A carrier, a warehouse, a tank terminal: each holds as bailee, bound to take reasonable care and to deliver to the bailor or its order. Oil of several owners mixed in one tank is owned in common, each by its share (Indian Oil v Greenstone Shipping, 1988).","about":["bailment"]},
{"id":"LW-lex-situs","lv":"property","d":5,"area":"Property and equity","q":"What does this mean? “Lex situs” (literally: the law of where it lies)","o":["a will is governed by the law of where the testator lived","a contract is governed by the law of the place it was made","ownership of a thing is decided by the law of where it lies","a ship is governed by the law of the country where it is registered"],"a":[2],"s":1,"x":"Lex situs: ownership of a thing is decided by the law of where it lies. Literally: the law of where it lies. For goods, the law of where they were when the transfer happened; so a cargo bought afloat is a puzzle, one reason title passes by the documents. Land always follows its lex situs.","about":["lex-situs"]},
{"id":"LW-lex-situs-name","lv":"property","d":6,"area":"Property and equity","q":"Which legal term means this? “Ownership of a thing is decided by the law of where it lies”","o":["Pro forma","Lex situs","Prior tempore, potior iure","Superficies solo cedit"],"a":[1],"s":1,"x":"Lex situs: ownership of a thing is decided by the law of where it lies. Literally: the law of where it lies. For goods, the law of where they were when the transfer happened; so a cargo bought afloat is a puzzle, one reason title passes by the documents. Land always follows its lex situs.","about":["lex-situs"]},
{"id":"LW-beati-possidentes","lv":"property","d":5,"area":"Property and equity","q":"What does this mean? “Beati possidentes” (literally: blessed are those in possession)","o":["the one in possession must pay the taxes due on the thing","the one in possession owns it outright once a full year has passed","the one in possession keeps it until a better right is proved","the one in possession is liable for any harm the thing does"],"a":[2],"s":1,"x":"Beati possidentes: the one in possession keeps it until a better right is proved. Literally: blessed are those in possession. In English, 'possession is nine-tenths of the law'. Possession gives a title good against everyone but a person with a better one (Armory v Delamirie, 1722: a chimney sweep's boy who found a jewel).","about":["beati-possidentes"]},
{"id":"LW-beati-possidentes-name","lv":"property","d":6,"area":"Property and equity","q":"Which legal term means this? “The one in possession keeps it until a better right is proved”","o":["Lex situs","Cuius est solum","Beati possidentes","Prior tempore, potior iure"],"a":[2],"s":1,"x":"Beati possidentes: the one in possession keeps it until a better right is proved. Literally: blessed are those in possession. In English, 'possession is nine-tenths of the law'. Possession gives a title good against everyone but a person with a better one (Armory v Delamirie, 1722: a chimney sweep's boy who found a jewel).","about":["beati-possidentes"]},
{"id":"LW-duty-of-care","lv":"wrongs","d":3,"area":"Wrongs and crimes","q":"What is meant by “Duty of care”?","o":["the obligation to look after goods you hold for someone else","the obligation to rescue anyone you see in danger, if you safely can","the obligation to tell a buyer of every defect you know of","the obligation to avoid acts you can foresee would harm your neighbour"],"a":[3],"s":1,"x":"Duty of care: the obligation to avoid acts you can foresee would harm your neighbour. Donoghue v Stevenson (1932): a snail in a bottle of ginger beer, and Lord Atkin's 'neighbour', anyone so closely and directly affected that you ought to have them in mind. Caparo v Dickman (1990) asks foreseeability, proximity and whether a duty is fair.","about":["duty-of-care"]},
{"id":"LW-duty-of-care-name","lv":"wrongs","d":4,"area":"Wrongs and crimes","q":"Which legal term means this? “The obligation to avoid acts you can foresee would harm your neighbour”","o":["Rylands v Fletcher","Contributory negligence","Anti-dumping","Duty of care"],"a":[3],"s":1,"x":"Duty of care: the obligation to avoid acts you can foresee would harm your neighbour. Donoghue v Stevenson (1932): a snail in a bottle of ginger beer, and Lord Atkin's 'neighbour', anyone so closely and directly affected that you ought to have them in mind. Caparo v Dickman (1990) asks foreseeability, proximity and whether a duty is fair.","about":["duty-of-care"]},
{"id":"LW-res-ipsa-loquitur","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What does this mean? “Res ipsa loquitur” (literally: the thing speaks for itself)","o":["an accident that wouldn't happen without negligence implies it","a thing found in someone's hands is presumed to be theirs","a document's meaning is taken from its own words, nothing else","the facts are so plain that the court needs to hear no argument on them"],"a":[0],"s":1,"x":"Res ipsa loquitur: an accident that wouldn't happen without negligence implies it. Literally: the thing speaks for itself. Byrne v Boadle (1863): a barrel of flour fell from a warehouse window onto a passer-by. It puts the burden of explaining on the defendant.","about":["res-ipsa-loquitur"]},
{"id":"LW-res-ipsa-loquitur-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “An accident that wouldn't happen without negligence implies it”","o":["Lex talionis","Ne bis in idem","Habeas corpus","Res ipsa loquitur"],"a":[3],"s":1,"x":"Res ipsa loquitur: an accident that wouldn't happen without negligence implies it. Literally: the thing speaks for itself. Byrne v Boadle (1863): a barrel of flour fell from a warehouse window onto a passer-by. It puts the burden of explaining on the defendant.","about":["res-ipsa-loquitur"]},
{"id":"LW-volenti","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What does this mean? “Volenti non fit injuria” (literally: to one who is willing, no wrong is done)","o":["a wrong done willingly is punished more than one by accident","someone who agreed to a contract can't later call it unfair","someone who helps in an emergency can't be sued for the harm","someone who freely accepts a risk can't sue for the harm"],"a":[3],"s":1,"x":"Volenti non fit injuria: someone who freely accepts a risk can't sue for the harm. Literally: to one who is willing, no wrong is done. Narrow: knowing of a risk isn't agreeing to it, and a rescuer is never volens (Haynes v Harwood, 1935). It can't be pleaded against employees, or against passengers in cars.","about":["volenti"]},
{"id":"LW-volenti-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “Someone who freely accepts a risk can't sue for the harm”","o":["Nullum crimen sine lege","Nemo tenetur se ipsum accusare","Ex turpi causa non oritur actio","Volenti non fit injuria"],"a":[3],"s":1,"x":"Volenti non fit injuria: someone who freely accepts a risk can't sue for the harm. Literally: to one who is willing, no wrong is done. Narrow: knowing of a risk isn't agreeing to it, and a rescuer is never volens (Haynes v Harwood, 1935). It can't be pleaded against employees, or against passengers in cars.","about":["volenti"]},
{"id":"LW-ex-turpi-causa","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What does this mean? “Ex turpi causa non oritur actio” (literally: no action arises from a base cause)","o":["a claim brought from an improper motive must be struck out","a claimant can't build a claim on its own illegal act","a defendant who acted from a base motive pays extra damages","a contract made at a bad price can't be enforced by the gainer"],"a":[1],"s":1,"x":"Ex turpi causa non oritur actio: a claimant can't build a claim on its own illegal act. Literally: no action arises from a base cause. Since Patel v Mirza (2016) not applied mechanically: a court asks whether enforcing the claim would harm the integrity of the law, weighing the purpose of the rule broken, other policies and proportion.","about":["ex-turpi-causa"]},
{"id":"LW-ex-turpi-causa-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “A claimant can't build a claim on its own illegal act”","o":["Nullum crimen sine lege","Nemo tenetur se ipsum accusare","Volenti non fit injuria","Ex turpi causa non oritur actio"],"a":[3],"s":1,"x":"Ex turpi causa non oritur actio: a claimant can't build a claim on its own illegal act. Literally: no action arises from a base cause. Since Patel v Mirza (2016) not applied mechanically: a court asks whether enforcing the claim would harm the integrity of the law, weighing the purpose of the rule broken, other policies and proportion.","about":["ex-turpi-causa"]},
{"id":"LW-novus-actus","lv":"wrongs","d":7,"area":"Wrongs and crimes","q":"What does this mean? “Novus actus interveniens” (literally: a new act intervening)","o":["a later free act or event breaks the chain from wrong to harm","a later law changes the outcome of a case already under way","a second wrongdoer shares the damages equally with the first","a new claim may be added to a case already before the court"],"a":[0],"s":1,"x":"Novus actus interveniens: a later free act or event breaks the chain from wrong to harm. Literally: a new act intervening. It must be free, deliberate and informed, or wholly abnormal: a doctor's ordinary negligence after an accident doesn't break the chain; a deliberate crime usually does.","about":["novus-actus"]},
{"id":"LW-novus-actus-name","lv":"wrongs","d":8,"area":"Wrongs and crimes","q":"Which legal term means this? “A later free act or event breaks the chain from wrong to harm”","o":["Nullum crimen sine lege","Nemo tenetur se ipsum accusare","Novus actus interveniens","In dubio pro reo"],"a":[2],"s":1,"x":"Novus actus interveniens: a later free act or event breaks the chain from wrong to harm. Literally: a new act intervening. It must be free, deliberate and informed, or wholly abnormal: a doctor's ordinary negligence after an accident doesn't break the chain; a deliberate crime usually does.","about":["novus-actus"]},
{"id":"LW-but-for-test","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What is meant by “But-for test”?","o":["harm is caused by a wrong if it would not have happened without it","harm is caused by a wrong if the wrong was its last cause in time","harm is caused by a wrong if the wrongdoer meant it to happen","harm is caused by a wrong if a reasonable person would say so"],"a":[0],"s":1,"x":"But-for test: harm is caused by a wrong if it would not have happened without it. Barnett v Chelsea and Kensington Hospital (1969): the doctor who sent a poisoned night-watchman home wasn't liable, as he'd have died anyway. The Romans' conditio sine qua non; relaxed for mesothelioma (Fairchild, 2002).","about":["but-for-test"]},
{"id":"LW-but-for-test-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “Harm is caused by a wrong if it would not have happened without it”","o":["Anti-dumping","Hull formula","Market overt","But-for test"],"a":[3],"s":1,"x":"But-for test: harm is caused by a wrong if it would not have happened without it. Barnett v Chelsea and Kensington Hospital (1969): the doctor who sent a poisoned night-watchman home wasn't liable, as he'd have died anyway. The Romans' conditio sine qua non; relaxed for mesothelioma (Fairchild, 2002).","about":["but-for-test"]},
{"id":"LW-contributory-negligence","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What is meant by “Contributory negligence”?","o":["damages are cut if the claimant didn't try to limit its loss","damages are cut by the claimant's own share in causing its harm","damages are refused if the claimant knowingly accepted the risk","damages are shared equally between two wrongdoers of one harm"],"a":[1],"s":1,"x":"Contributory negligence: damages are cut by the claimant's own share in causing its harm. Since the Law Reform (Contributory Negligence) Act 1945 a reduction 'as the court thinks just and equitable', where before it was a complete defence. A car passenger without a seat belt typically loses a quarter or less (Froom v Butcher, 1976).","about":["contributory-negligence"]},
{"id":"LW-contributory-negligence-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “Damages are cut by the claimant's own share in causing its harm”","o":["Contributory negligence","Duty of care","Rylands v Fletcher","Conversion"],"a":[0],"s":1,"x":"Contributory negligence: damages are cut by the claimant's own share in causing its harm. Since the Law Reform (Contributory Negligence) Act 1945 a reduction 'as the court thinks just and equitable', where before it was a complete defence. A car passenger without a seat belt typically loses a quarter or less (Froom v Butcher, 1976).","about":["contributory-negligence"]},
{"id":"LW-respondeat-superior","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What does this mean? “Respondeat superior” (literally: let the superior answer)","o":["an appeal court must answer a question sent up by a lower court","a senior officer answers for a junior's crime as if it were his own","an employer is liable for wrongs its employees commit at work","a parent company answers for every debt of its subsidiaries"],"a":[2],"s":1,"x":"Respondeat superior: an employer is liable for wrongs its employees commit at work. Literally: let the superior answer. Vicarious liability: strict, but only for acts closely connected with the job (Lister v Hesley Hall, 2001), and not for an independent contractor's (Various Claimants v Barclays, 2020).","about":["respondeat-superior"]},
{"id":"LW-respondeat-superior-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “An employer is liable for wrongs its employees commit at work”","o":["Respondeat superior","Volenti non fit injuria","In dubio pro reo","Habeas corpus"],"a":[0],"s":1,"x":"Respondeat superior: an employer is liable for wrongs its employees commit at work. Literally: let the superior answer. Vicarious liability: strict, but only for acts closely connected with the job (Lister v Hesley Hall, 2001), and not for an independent contractor's (Various Claimants v Barclays, 2020).","about":["respondeat-superior"]},
{"id":"LW-rylands-v-fletcher","lv":"wrongs","d":7,"area":"Wrongs and crimes","q":"What is meant by “Rylands v Fletcher”?","o":["an occupier is liable only if it failed to fence its land properly","an occupier owes trespassers no duty, whatever the danger","an occupier must remove at once any danger it finds on its land","an occupier is strictly liable if something dangerous escapes"],"a":[3],"s":1,"x":"Rylands v Fletcher: an occupier is strictly liable if something dangerous escapes. Rylands v Fletcher (1868): water from a mill-owner's new reservoir flooded the mine below. The use must be non-natural and the harm foreseeable (Cambridge Water v Eastern Counties Leather, 1994); it matters to anyone storing oil or chemicals.","about":["rylands-v-fletcher"]},
{"id":"LW-rylands-v-fletcher-name","lv":"wrongs","d":8,"area":"Wrongs and crimes","q":"Which legal term means this? “An occupier is strictly liable if something dangerous escapes”","o":["Rylands v Fletcher","Autonomy principle","Contributory negligence","Adverse possession"],"a":[0],"s":1,"x":"Rylands v Fletcher: an occupier is strictly liable if something dangerous escapes. Rylands v Fletcher (1868): water from a mill-owner's new reservoir flooded the mine below. The use must be non-natural and the harm foreseeable (Cambridge Water v Eastern Counties Leather, 1994); it matters to anyone storing oil or chemicals.","about":["rylands-v-fletcher"]},
{"id":"LW-conversion","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What is meant by “Conversion”?","o":["swapping a debt for shares in the company that owes it","dealing with goods in a way that denies the owner's right to them","taking goods openly and returning them before the owner asks","changing goods into a new product, which then belongs to its maker"],"a":[1],"s":1,"x":"Conversion: dealing with goods in a way that denies the owner's right to them. Strict: honesty is no defence. A carrier or terminal that hands cargo to someone without the bill of lading converts it, against the holder; hence the letters of indemnity.","about":["conversion"]},
{"id":"LW-conversion-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “Dealing with goods in a way that denies the owner's right to them”","o":["But-for test","Duty of care","Frustration","Conversion"],"a":[3],"s":1,"x":"Conversion: dealing with goods in a way that denies the owner's right to them. Strict: honesty is no defence. A carrier or terminal that hands cargo to someone without the bill of lading converts it, against the holder; hence the letters of indemnity.","about":["conversion"]},
{"id":"LW-actus-non-facit-reum","lv":"wrongs","d":3,"area":"Wrongs and crimes","q":"What does this mean? “Actus non facit reum nisi mens sit rea”","o":["a crime needs a victim who complains as well as an act","a crime needs a guilty mind as well as a guilty act","a crime planned but never carried out can't be punished","a crime done under orders is the commander's, not the soldier's"],"a":[1],"s":1,"x":"Actus non facit reum nisi mens sit rea: a crime needs a guilty mind as well as a guilty act. Literally: the act doesn't make one guilty unless the mind is guilty. Coke's maxim, behind a crime's two elements: actus reus, the guilty act, and mens rea, the guilty mind (intention, recklessness, knowledge). Strict liability offences, common in regulation, need no mens rea.","about":["actus-non-facit-reum"]},
{"id":"LW-actus-non-facit-reum-name","lv":"wrongs","d":4,"area":"Wrongs and crimes","q":"Which legal term means this? “A crime needs a guilty mind as well as a guilty act”","o":["Ex turpi causa non oritur actio","Actus non facit reum nisi mens sit rea","Pacta tertiis nec nocent nec prosunt","Nemo tenetur se ipsum accusare"],"a":[1],"s":1,"x":"Actus non facit reum nisi mens sit rea: a crime needs a guilty mind as well as a guilty act. Literally: the act doesn't make one guilty unless the mind is guilty. Coke's maxim, behind a crime's two elements: actus reus, the guilty act, and mens rea, the guilty mind (intention, recklessness, knowledge). Strict liability offences, common in regulation, need no mens rea.","about":["actus-non-facit-reum"]},
{"id":"LW-nullum-crimen","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What does this mean? “Nullum crimen sine lege” (literally: no crime without a law)","o":["no one can be punished for what the law hadn't forbidden when done","no one can be punished for a crime the police never saw committed","no one can be punished twice under two laws for one act","no one can be punished at home for a crime done abroad"],"a":[0],"s":1,"x":"Nullum crimen sine lege: no one can be punished for what the law hadn't forbidden when done. Literally: no crime without a law. With nulla poena sine lege, in Feuerbach's form (1801): the European Convention on Human Rights, art. 7, and the German Basic Law, art. 103(2). Retroactive criminal laws are barred.","about":["nullum-crimen"]},
{"id":"LW-nullum-crimen-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “No one can be punished for what the law hadn't forbidden when done”","o":["Nemo tenetur se ipsum accusare","Volenti non fit injuria","Respondeat superior","Nullum crimen sine lege"],"a":[3],"s":1,"x":"Nullum crimen sine lege: no one can be punished for what the law hadn't forbidden when done. Literally: no crime without a law. With nulla poena sine lege, in Feuerbach's form (1801): the European Convention on Human Rights, art. 7, and the German Basic Law, art. 103(2). Retroactive criminal laws are barred.","about":["nullum-crimen"]},
{"id":"LW-ne-bis-in-idem","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What does this mean? “Ne bis in idem”","o":["no one may be tried or punished twice for the same offence","no one may be sued in two countries' courts at the same time","no one may be made to pay the same debt to two creditors","no one may be tried by a judge who has heard their case before"],"a":[0],"s":1,"x":"Ne bis in idem: no one may be tried or punished twice for the same offence. Literally: not twice for the same. Double jeopardy: in the European Convention (Protocol 7, art. 4), the EU Charter (art. 50) and the German Basic Law (art. 103(3)). England allows a retrial for murder and other grave crimes on compelling new evidence (Criminal Justice Act 2003).","about":["ne-bis-in-idem"]},
{"id":"LW-ne-bis-in-idem-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “No one may be tried or punished twice for the same offence”","o":["Lex talionis","Ne bis in idem","Res ipsa loquitur","In dubio pro reo"],"a":[1],"s":1,"x":"Ne bis in idem: no one may be tried or punished twice for the same offence. Literally: not twice for the same. Double jeopardy: in the European Convention (Protocol 7, art. 4), the EU Charter (art. 50) and the German Basic Law (art. 103(3)). England allows a retrial for murder and other grave crimes on compelling new evidence (Criminal Justice Act 2003).","about":["ne-bis-in-idem"]},
{"id":"LW-in-dubio-pro-reo","lv":"wrongs","d":3,"area":"Wrongs and crimes","q":"What does this mean? “In dubio pro reo”","o":["a doubt about a contract's words is resolved against its writer","a doubt about a witness is resolved by hearing them a second time","a doubt about the law must be resolved in the state's favour","a doubt about the facts must be resolved in the accused's favour"],"a":[3],"s":1,"x":"In dubio pro reo: a doubt about the facts must be resolved in the accused's favour. Literally: in doubt, for the accused. Behind the presumption of innocence and the criminal standard, proof beyond reasonable doubt. It governs the facts, not how the law is read.","about":["in-dubio-pro-reo"]},
{"id":"LW-in-dubio-pro-reo-name","lv":"wrongs","d":4,"area":"Wrongs and crimes","q":"Which legal term means this? “A doubt about the facts must be resolved in the accused's favour”","o":["Nullum crimen sine lege","Lex talionis","Habeas corpus","In dubio pro reo"],"a":[3],"s":1,"x":"In dubio pro reo: a doubt about the facts must be resolved in the accused's favour. Literally: in doubt, for the accused. Behind the presumption of innocence and the criminal standard, proof beyond reasonable doubt. It governs the facts, not how the law is read.","about":["in-dubio-pro-reo"]},
{"id":"LW-nemo-tenetur","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What does this mean? “Nemo tenetur se ipsum accusare” (literally: no one is bound to accuse himself)","o":["no one is bound to report a crime they saw another commit","no one is bound to answer a claim made by an unknown accuser","no one is bound to give evidence that incriminates themselves","no one is bound to pay a debt they never acknowledged in writing"],"a":[2],"s":1,"x":"Nemo tenetur se ipsum accusare: no one is bound to give evidence that incriminates themselves. Literally: no one is bound to accuse himself. The privilege against self-incrimination and the right to silence, implied in the European Convention's fair trial (art. 6; Saunders v UK, 1996, on answers compelled by inspectors); 'pleading the Fifth' in the US.","about":["nemo-tenetur"]},
{"id":"LW-nemo-tenetur-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “No one is bound to give evidence that incriminates themselves”","o":["Nullum crimen sine lege","Volenti non fit injuria","Ex turpi causa non oritur actio","Nemo tenetur se ipsum accusare"],"a":[3],"s":1,"x":"Nemo tenetur se ipsum accusare: no one is bound to give evidence that incriminates themselves. Literally: no one is bound to accuse himself. The privilege against self-incrimination and the right to silence, implied in the European Convention's fair trial (art. 6; Saunders v UK, 1996, on answers compelled by inspectors); 'pleading the Fifth' in the US.","about":["nemo-tenetur"]},
{"id":"LW-lex-talionis","lv":"wrongs","d":5,"area":"Wrongs and crimes","q":"What does this mean? “Lex talionis” (literally: the law of retaliation)","o":["a punishment equal to the harm done, and never more than that","a state may strike back at once and in kind when it's attacked","a victim's family may choose the punishment of the guilty","a creditor may seize the debtor's goods himself, without a court"],"a":[0],"s":1,"x":"Lex talionis: a punishment equal to the harm done, and never more than that. Literally: the law of retaliation. Hammurabi's laws (about 1754 BC), the Torah's 'an eye for an eye' and Rome's Twelve Tables. Its point was a limit on revenge as much as a measure of it.","about":["lex-talionis"]},
{"id":"LW-lex-talionis-name","lv":"wrongs","d":6,"area":"Wrongs and crimes","q":"Which legal term means this? “A punishment equal to the harm done, and never more than that”","o":["Nullum crimen sine lege","Respondeat superior","In dubio pro reo","Lex talionis"],"a":[3],"s":1,"x":"Lex talionis: a punishment equal to the harm done, and never more than that. Literally: the law of retaliation. Hammurabi's laws (about 1754 BC), the Torah's 'an eye for an eye' and Rome's Twelve Tables. Its point was a limit on revenge as much as a measure of it.","about":["lex-talionis"]},
{"id":"LW-lex-specialis","lv":"reading","d":5,"area":"Reading the law","q":"What does this mean? “Lex specialis derogat legi generali”","o":["the higher rule prevails over the lower, a constitution over a statute","the stricter rule prevails over the milder one in criminal cases","the later rule prevails over the earlier one on the same point","the rule made for the particular case prevails over the broader one"],"a":[3],"s":1,"x":"Lex specialis derogat legi generali: the rule made for the particular case prevails over the broader one. Literally: the special law overrides the general. A canon for statutes, contracts and treaties alike: in international law, the law of armed conflict is the lex specialis beside human rights (ICJ, Nuclear Weapons, 1996). A later general law doesn't override an earlier special one: generalia specialibus non derogant.","about":["lex-specialis"]},
{"id":"LW-lex-specialis-name","lv":"reading","d":6,"area":"Reading the law","q":"Which legal term means this? “The rule made for the particular case prevails over the broader one”","o":["Ubi jus, ibi remedium","Lex specialis derogat legi generali","Lex posterior derogat legi priori","De minimis non curat lex"],"a":[1],"s":1,"x":"Lex specialis derogat legi generali: the rule made for the particular case prevails over the broader one. Literally: the special law overrides the general. A canon for statutes, contracts and treaties alike: in international law, the law of armed conflict is the lex specialis beside human rights (ICJ, Nuclear Weapons, 1996). A later general law doesn't override an earlier special one: generalia specialibus non derogant.","about":["lex-specialis"]},
{"id":"LW-lex-posterior","lv":"reading","d":5,"area":"Reading the law","q":"What does this mean? “Lex posterior derogat legi priori”","o":["the higher rule prevails over the lower, a constitution over a statute","the earlier rule prevails, as the parties relied on it first","the later rule prevails over the earlier one on the same point","the rule made for the particular case prevails over the broader one"],"a":[2],"s":1,"x":"Lex posterior derogat legi priori: the later rule prevails over the earlier one on the same point. Literally: the later law overrides the earlier. Parliament can't bind its successors, so a later Act impliedly repeals an earlier one that conflicts with it; but a later general law doesn't override an earlier special one.","about":["lex-posterior"]},
{"id":"LW-lex-posterior-name","lv":"reading","d":6,"area":"Reading the law","q":"Which legal term means this? “The later rule prevails over the earlier one on the same point”","o":["De minimis non curat lex","Ut res magis valeat quam pereat","Ignorantia juris non excusat","Lex posterior derogat legi priori"],"a":[3],"s":1,"x":"Lex posterior derogat legi priori: the later rule prevails over the earlier one on the same point. Literally: the later law overrides the earlier. Parliament can't bind its successors, so a later Act impliedly repeals an earlier one that conflicts with it; but a later general law doesn't override an earlier special one.","about":["lex-posterior"]},
{"id":"LW-lex-superior","lv":"reading","d":5,"area":"Reading the law","q":"What does this mean? “Lex superior derogat legi inferiori”","o":["the ruling of the higher court prevails over the lower court's own","the higher rule prevails over the lower, a constitution over a statute","the later rule prevails over the earlier one on the same point","the rule made for the particular case prevails over the broader general one"],"a":[1],"s":1,"x":"Lex superior derogat legi inferiori: the higher rule prevails over the lower, a constitution over a statute. Literally: the higher law overrides the lower. The hierarchy of norms, Kelsen's Stufenbau: constitution, statute, regulation, contract. In the EU, EU law takes precedence over national law (Costa v ENEL, 1964).","about":["lex-superior"]},
{"id":"LW-lex-superior-name","lv":"reading","d":6,"area":"Reading the law","q":"Which legal term means this? “The higher rule prevails over the lower, a constitution over a statute”","o":["De minimis non curat lex","Ubi jus, ibi remedium","Lex specialis derogat legi generali","Lex superior derogat legi inferiori"],"a":[3],"s":1,"x":"Lex superior derogat legi inferiori: the higher rule prevails over the lower, a constitution over a statute. Literally: the higher law overrides the lower. The hierarchy of norms, Kelsen's Stufenbau: constitution, statute, regulation, contract. In the EU, EU law takes precedence over national law (Costa v ENEL, 1964).","about":["lex-superior"]},
{"id":"LW-ejusdem-generis","lv":"reading","d":5,"area":"Reading the law","q":"What does this mean? “Ejusdem generis” (literally: of the same kind)","o":["a buyer may reject goods not of the same kind as the sample","broad words after a list cover only things like those listed","parties of the same kind must be treated alike by the law","goods of the same kind may be swapped for each other on delivery"],"a":[1],"s":1,"x":"Ejusdem generis: broad words after a list cover only things like those listed. Literally: of the same kind. In a force majeure clause, 'wars, strikes, riots or any other cause' reaches only causes of that sort, unless 'whatsoever' or the like says otherwise. A canon of construction, with noscitur a sociis and expressio unius.","about":["ejusdem-generis"]},
{"id":"LW-ejusdem-generis-name","lv":"reading","d":6,"area":"Reading the law","q":"Which legal term means this? “Broad words after a list cover only things like those listed”","o":["Per incuriam","Mutatis mutandis","Ubi jus, ibi remedium","Ejusdem generis"],"a":[3],"s":1,"x":"Ejusdem generis: broad words after a list cover only things like those listed. Literally: of the same kind. In a force majeure clause, 'wars, strikes, riots or any other cause' reaches only causes of that sort, unless 'whatsoever' or the like says otherwise. A canon of construction, with noscitur a sociis and expressio unius.","about":["ejusdem-generis"]},
{"id":"LW-noscitur-a-sociis","lv":"reading","d":7,"area":"Reading the law","q":"What does this mean? “Noscitur a sociis” (literally: it is known by its companions)","o":["a person's character is judged by the company they keep","a partner is bound by whatever the other partners agree","a witness's evidence is weighed by those who back it up","a word's meaning is taken from the words that surround it"],"a":[3],"s":1,"x":"Noscitur a sociis: a word's meaning is taken from the words that surround it. Literally: it is known by its companions. Inland Revenue v Frere (1965): 'interest, annuities or other annual payments' read together, so 'interest' meant annual interest. A canon for statutes and contracts alike.","about":["noscitur-a-sociis"]},
{"id":"LW-noscitur-a-sociis-name","lv":"reading","d":8,"area":"Reading the law","q":"Which legal term means this? “A word's meaning is taken from the words that surround it”","o":["Noscitur a sociis","Per incuriam","Mutatis mutandis","Ubi jus, ibi remedium"],"a":[0],"s":1,"x":"Noscitur a sociis: a word's meaning is taken from the words that surround it. Literally: it is known by its companions. Inland Revenue v Frere (1965): 'interest, annuities or other annual payments' read together, so 'interest' meant annual interest. A canon for statutes and contracts alike.","about":["noscitur-a-sociis"]},
{"id":"LW-expressio-unius","lv":"reading","d":7,"area":"Reading the law","q":"What does this mean? “Expressio unius est exclusio alterius”","o":["broad words after a list cover only things like those listed","an unclear term is read against whoever drafted it or relies on it","a word's meaning is taken from the words that surround it","listing some things implies the ones not listed are left out"],"a":[3],"s":1,"x":"Expressio unius est exclusio alterius: listing some things implies the ones not listed are left out. Literally: to name one is to exclude the other. A guide, not a rule, as lists are often written by way of example: a clause excusing delay 'by strikes and lockouts' suggests that other causes don't.","about":["expressio-unius"]},
{"id":"LW-expressio-unius-name","lv":"reading","d":8,"area":"Reading the law","q":"Which legal term means this? “Listing some things implies the ones not listed are left out”","o":["De minimis non curat lex","Expressio unius est exclusio alterius","Ubi jus, ibi remedium","Ut res magis valeat quam pereat"],"a":[1],"s":1,"x":"Expressio unius est exclusio alterius: listing some things implies the ones not listed are left out. Literally: to name one is to exclude the other. A guide, not a rule, as lists are often written by way of example: a clause excusing delay 'by strikes and lockouts' suggests that other causes don't.","about":["expressio-unius"]},
{"id":"LW-ut-res-magis-valeat","lv":"reading","d":7,"area":"Reading the law","q":"What does this mean? “Ut res magis valeat quam pereat” (literally: that the thing may rather have effect than fail)","o":["a debtor who can't pay in full must pay as much as it can","a law that has fallen into disuse stays in force until repealed","a term is read so that it works, rather than so that it fails","a contract partly void is wholly void, unless the parties agree"],"a":[2],"s":1,"x":"Ut res magis valeat quam pereat: a term is read so that it works, rather than so that it fails. Literally: that the thing may rather have effect than fail. The validation principle: of two readings, courts prefer the one that gives a clause effect. Treaty interpreters call it effet utile.","about":["ut-res-magis-valeat"]},
{"id":"LW-ut-res-magis-valeat-name","lv":"reading","d":8,"area":"Reading the law","q":"Which legal term means this? “A term is read so that it works, rather than so that it fails”","o":["Ignorantia juris non excusat","Expressio unius est exclusio alterius","Ubi jus, ibi remedium","Ut res magis valeat quam pereat"],"a":[3],"s":1,"x":"Ut res magis valeat quam pereat: a term is read so that it works, rather than so that it fails. Literally: that the thing may rather have effect than fail. The validation principle: of two readings, courts prefer the one that gives a clause effect. Treaty interpreters call it effet utile.","about":["ut-res-magis-valeat"]},
{"id":"LW-de-minimis","lv":"reading","d":3,"area":"Reading the law","q":"What does this mean? “De minimis non curat lex”","o":["the law ignores matters too small to be worth its time","the law punishes small crimes as firmly as great ones","the law protects the weakest party first in any dispute","the law treats acts of minors more leniently than adults'"],"a":[0],"s":1,"x":"De minimis non curat lex: the law ignores matters too small to be worth its time. Literally: the law doesn't concern itself with trifles. In trade too: a buyer couldn't reject a wheat cargo for being a trifle over its contract quantity (Shipton, Anderson v Weil Brothers, 1912). WTO law has de minimis thresholds: no anti-dumping duty on a margin under 2%.","about":["de-minimis"]},
{"id":"LW-de-minimis-name","lv":"reading","d":4,"area":"Reading the law","q":"Which legal term means this? “The law ignores matters too small to be worth its time”","o":["De minimis non curat lex","Mutatis mutandis","Dura lex, sed lex","Ut res magis valeat quam pereat"],"a":[0],"s":1,"x":"De minimis non curat lex: the law ignores matters too small to be worth its time. Literally: the law doesn't concern itself with trifles. In trade too: a buyer couldn't reject a wheat cargo for being a trifle over its contract quantity (Shipton, Anderson v Weil Brothers, 1912). WTO law has de minimis thresholds: no anti-dumping duty on a margin under 2%.","about":["de-minimis"]},
{"id":"LW-ignorantia-juris","lv":"reading","d":3,"area":"Reading the law","q":"What does this mean? “Ignorantia juris non excusat”","o":["not knowing the law is no defence to breaking it","a judge unsure of the law must refer the case to a higher court","not knowing a contract's terms is no reason to escape them","not knowing the facts is no defence to breaking the law"],"a":[0],"s":1,"x":"Ignorantia juris non excusat: not knowing the law is no defence to breaking it. Literally: ignorance of the law is no excuse. Its pair, ignorantia facti excusat: a genuine mistake of fact can be a defence. Since Kleinwort Benson v Lincoln City Council (1998), money paid under a mistake of law can be recovered in England.","about":["ignorantia-juris"]},
{"id":"LW-ignorantia-juris-name","lv":"reading","d":4,"area":"Reading the law","q":"Which legal term means this? “Not knowing the law is no defence to breaking it”","o":["Ignorantia juris non excusat","Expressio unius est exclusio alterius","Lex posterior derogat legi priori","Ut res magis valeat quam pereat"],"a":[0],"s":1,"x":"Ignorantia juris non excusat: not knowing the law is no defence to breaking it. Literally: ignorance of the law is no excuse. Its pair, ignorantia facti excusat: a genuine mistake of fact can be a defence. Since Kleinwort Benson v Lincoln City Council (1998), money paid under a mistake of law can be recovered in England.","about":["ignorantia-juris"]},
{"id":"LW-dura-lex","lv":"reading","d":3,"area":"Reading the law","q":"What does this mean? “Dura lex, sed lex”","o":["a law must be obeyed even when it bears hard on someone","a harsh law must be read narrowly to soften its effect","a law too harsh to bear loses its force and needn't be obeyed","a law grows harder to repeal the longer it stays in force"],"a":[0],"s":1,"x":"Dura lex, sed lex: a law must be obeyed even when it bears hard on someone. Literally: the law is harsh, but it is the law. After Ulpian in Justinian's Digest (40.9.12): 'quod quidem perquam durum est, sed ita lex scripta est'. Its counterweight in German thought is Radbruch's formula: statute yields when its injustice becomes intolerable.","about":["dura-lex"]},
{"id":"LW-dura-lex-name","lv":"reading","d":4,"area":"Reading the law","q":"Which legal term means this? “A law must be obeyed even when it bears hard on someone”","o":["Ipso facto","Ubi jus, ibi remedium","Ejusdem generis","Dura lex, sed lex"],"a":[3],"s":1,"x":"Dura lex, sed lex: a law must be obeyed even when it bears hard on someone. Literally: the law is harsh, but it is the law. After Ulpian in Justinian's Digest (40.9.12): 'quod quidem perquam durum est, sed ita lex scripta est'. Its counterweight in German thought is Radbruch's formula: statute yields when its injustice becomes intolerable.","about":["dura-lex"]},
{"id":"LW-ubi-jus","lv":"reading","d":5,"area":"Reading the law","q":"What does this mean? “Ubi jus, ibi remedium”","o":["every wrong must be punished, even if no one complains","every claim must be brought where the defendant lives","every court must offer the parties a chance to settle","every legal right must have a means of enforcing it"],"a":[3],"s":1,"x":"Ubi jus, ibi remedium: every legal right must have a means of enforcing it. Literally: where there is a right, there is a remedy. Ashby v White (1703): a voter turned away from the poll could sue, though his candidate won anyway. It's why equity grew up beside the common law.","about":["ubi-jus"]},
{"id":"LW-ubi-jus-name","lv":"reading","d":6,"area":"Reading the law","q":"Which legal term means this? “Every legal right must have a means of enforcing it”","o":["Ubi jus, ibi remedium","Dura lex, sed lex","Ignorantia juris non excusat","Noscitur a sociis"],"a":[0],"s":1,"x":"Ubi jus, ibi remedium: every legal right must have a means of enforcing it. Literally: where there is a right, there is a remedy. Ashby v White (1703): a voter turned away from the poll could sue, though his candidate won anyway. It's why equity grew up beside the common law.","about":["ubi-jus"]},
{"id":"LW-per-incuriam","lv":"reading","d":7,"area":"Reading the law","q":"What does this mean? “Per incuriam” (literally: through lack of care)","o":["a loss caused by carelessness, which the careless party must pay","a decision taken without hearing one side, and so void","a ruling made in ignorance of a binding authority, so not binding","a ruling made in haste, which the judge may correct within a week"],"a":[2],"s":1,"x":"Per incuriam: a ruling made in ignorance of a binding authority, so not binding. Literally: through lack of care. Young v Bristol Aeroplane (1944): the Court of Appeal may depart from its own decision given per incuriam, such as one that overlooked a statute or a binding case.","about":["per-incuriam"]},
{"id":"LW-per-incuriam-name","lv":"reading","d":8,"area":"Reading the law","q":"Which legal term means this? “A ruling made in ignorance of a binding authority, so not binding”","o":["Dura lex, sed lex","Ubi jus, ibi remedium","Mutatis mutandis","Per incuriam"],"a":[3],"s":1,"x":"Per incuriam: a ruling made in ignorance of a binding authority, so not binding. Literally: through lack of care. Young v Bristol Aeroplane (1944): the Court of Appeal may depart from its own decision given per incuriam, such as one that overlooked a statute or a binding case.","about":["per-incuriam"]},
{"id":"LW-pacta-tertiis","lv":"states","d":7,"area":"States and trade rules","q":"What does this mean? “Pacta tertiis nec nocent nec prosunt” (literally: agreements neither harm nor benefit third parties)","o":["a treaty that harms a third state is void from the start","a treaty may be joined later only with every party's consent","a treaty binds no state that hasn't consented to it","a treaty signed by a third state needn't be ratified to bind it"],"a":[2],"s":1,"x":"Pacta tertiis nec nocent nec prosunt: a treaty binds no state that hasn't consented to it. Literally: agreements neither harm nor benefit third parties. Vienna Convention on the Law of Treaties, arts 34 to 38; contract law's privity is the same idea. A rule of customary law binds a non-party all the same.","about":["pacta-tertiis"]},
{"id":"LW-pacta-tertiis-name","lv":"states","d":8,"area":"States and trade rules","q":"Which legal term means this? “A treaty binds no state that hasn't consented to it”","o":["Causa proxima non remota spectatur","Actus non facit reum nisi mens sit rea","Lex specialis derogat legi generali","Pacta tertiis nec nocent nec prosunt"],"a":[3],"s":1,"x":"Pacta tertiis nec nocent nec prosunt: a treaty binds no state that hasn't consented to it. Literally: agreements neither harm nor benefit third parties. Vienna Convention on the Law of Treaties, arts 34 to 38; contract law's privity is the same idea. A rule of customary law binds a non-party all the same.","about":["pacta-tertiis"]},
{"id":"LW-jus-cogens","lv":"states","d":7,"area":"States and trade rules","q":"What does this mean? “Jus cogens” (literally: compelling law)","o":["rules a court applies of its own motion, though not pleaded","rules binding only once the UN Security Council adopts them","rules no state may contract out of, like the ban on genocide","rules a state must enforce on every ship that sails under its flag"],"a":[2],"s":1,"x":"Jus cogens: rules no state may contract out of, like the ban on genocide. Literally: compelling law. Vienna Convention on the Law of Treaties, art. 53: a treaty conflicting with a peremptory norm is void. Agreed examples: the bans on aggression, genocide, slavery, torture and racial discrimination.","about":["jus-cogens"]},
{"id":"LW-jus-cogens-name","lv":"states","d":8,"area":"States and trade rules","q":"Which legal term means this? “Rules no state may contract out of, like the ban on genocide”","o":["De facto","Ipso facto","Lex situs","Jus cogens"],"a":[3],"s":1,"x":"Jus cogens: rules no state may contract out of, like the ban on genocide. Literally: compelling law. Vienna Convention on the Law of Treaties, art. 53: a treaty conflicting with a peremptory norm is void. Agreed examples: the bans on aggression, genocide, slavery, torture and racial discrimination.","about":["jus-cogens"]},
{"id":"LW-erga-omnes","lv":"states","d":7,"area":"States and trade rules","q":"What does this mean? “Erga omnes” (literally: towards all)","o":["a right a state holds against all of its citizens alike","owed to all states, so that any of them may invoke a breach","an offer open to all comers, accepted by whoever acts on it","a tax levied on all goods alike, whatever their origin"],"a":[1],"s":1,"x":"Erga omnes: owed to all states, so that any of them may invoke a breach. Literally: towards all. Barcelona Traction (ICJ, 1970): obligations towards the international community as a whole, such as the bans on aggression and genocide. In property law, a right in rem holds erga omnes, a contract right only between the parties.","about":["erga-omnes"]},
{"id":"LW-erga-omnes-name","lv":"states","d":8,"area":"States and trade rules","q":"Which legal term means this? “Owed to all states, so that any of them may invoke a breach”","o":["Mare liberum","Bona fide","Jus cogens","Erga omnes"],"a":[3],"s":1,"x":"Erga omnes: owed to all states, so that any of them may invoke a breach. Literally: towards all. Barcelona Traction (ICJ, 1970): obligations towards the international community as a whole, such as the bans on aggression and genocide. In property law, a right in rem holds erga omnes, a contract right only between the parties.","about":["erga-omnes"]},
{"id":"LW-par-in-parem","lv":"states","d":7,"area":"States and trade rules","q":"What does this mean? “Par in parem non habet imperium” (literally: an equal has no authority over an equal)","o":["one partner can't give binding orders to another of equal share","one treaty can't override another between the same states","one judge can't overrule another judge of the same court","one state can't be sued in another's courts for its sovereign acts"],"a":[3],"s":1,"x":"Par in parem non habet imperium: one state can't be sued in another's courts for its sovereign acts. Literally: an equal has no authority over an equal. Restrictive since the 1970s: a state's commercial acts (acta iure gestionis) aren't immune, only its sovereign ones (acta iure imperii). The UK's State Immunity Act 1978 lets traders sue a state's trading arm, though its central bank's assets are safe from execution.","about":["par-in-parem"]},
{"id":"LW-par-in-parem-name","lv":"states","d":8,"area":"States and trade rules","q":"Which legal term means this? “One state can't be sued in another's courts for its sovereign acts”","o":["Delegatus non potest delegare","Qui facit per alium facit per se","Ex turpi causa non oritur actio","Par in parem non habet imperium"],"a":[3],"s":1,"x":"Par in parem non habet imperium: one state can't be sued in another's courts for its sovereign acts. Literally: an equal has no authority over an equal. Restrictive since the 1970s: a state's commercial acts (acta iure gestionis) aren't immune, only its sovereign ones (acta iure imperii). The UK's State Immunity Act 1978 lets traders sue a state's trading arm, though its central bank's assets are safe from execution.","about":["par-in-parem"]},
{"id":"LW-mare-liberum","lv":"states","d":5,"area":"States and trade rules","q":"What does this mean? “Mare liberum” (literally: the free sea)","o":["the high seas belong to no state and are open to every ship for trade","a ship may enter any port free of duties if it carries no cargo","a coastal state may tax ships passing within sight of its shores","a ship at sea answers to no law but its own master's command"],"a":[0],"s":1,"x":"Mare liberum: the high seas belong to no state and are open to every ship for trade. Literally: the free sea. Grotius (1609), written for the Dutch East India Company against Portugal's claim to the Indian Ocean and answered by Selden's Mare clausum (1635). UNCLOS (1982) splits the difference: 12 miles of territorial sea, a 200-mile economic zone, the high seas beyond.","about":["mare-liberum"]},
{"id":"LW-mare-liberum-name","lv":"states","d":6,"area":"States and trade rules","q":"Which legal term means this? “The high seas belong to no state and are open to every ship for trade”","o":["De facto","Locus standi","Mare liberum","Per incuriam"],"a":[2],"s":1,"x":"Mare liberum: the high seas belong to no state and are open to every ship for trade. Literally: the free sea. Grotius (1609), written for the Dutch East India Company against Portugal's claim to the Indian Ocean and answered by Selden's Mare clausum (1635). UNCLOS (1982) splits the difference: 12 miles of territorial sea, a 200-mile economic zone, the high seas beyond.","about":["mare-liberum"]},
{"id":"LW-transit-passage","lv":"states","d":7,"area":"States and trade rules","q":"What is meant by “Transit passage”?","o":["a right to cross a strait only after paying the coastal state's toll","a right to cross a coastal state's waters, which it may suspend for security","a right to cross a strait like Hormuz that coastal states can't suspend","a right to cross a strait in wartime under escort by the coastal navy"],"a":[2],"s":1,"x":"Transit passage: a right to cross a strait like Hormuz that coastal states can't suspend. UNCLOS, part III (1982), for Hormuz, Malacca, Gibraltar and the like: submarines may pass submerged and aircraft overfly, unlike innocent passage through a territorial sea. Iran signed UNCLOS but hasn't ratified it, and the US isn't a party.","about":["transit-passage"]},
{"id":"LW-transit-passage-name","lv":"states","d":8,"area":"States and trade rules","q":"Which legal term means this? “A right to cross a strait like Hormuz that coastal states can't suspend”","o":["Anti-dumping","Hull formula","National treatment","Transit passage"],"a":[3],"s":1,"x":"Transit passage: a right to cross a strait like Hormuz that coastal states can't suspend. UNCLOS, part III (1982), for Hormuz, Malacca, Gibraltar and the like: submarines may pass submerged and aircraft overfly, unlike innocent passage through a territorial sea. Iran signed UNCLOS but hasn't ratified it, and the US isn't a party.","about":["transit-passage"]},
{"id":"LW-mfn","lv":"states","d":5,"area":"States and trade rules","q":"What is meant by “Most-favoured-nation treatment”?","o":["imported goods must fare no worse than local ones once inside","a member may raise duties on a country that dumps goods on it","a member must give its best tariff to its oldest trading partners","a trade advantage given to one member must go to all at once"],"a":[3],"s":1,"x":"Most-favoured-nation treatment: a trade advantage given to one member must go to all at once. GATT 1947, art. I, the first rule of the WTO: no discrimination between trading partners. Exceptions: customs unions and free trade areas (art. XXIV) and preferences for developing countries. The US revoked Russia's in 2022.","about":["mfn"]},
{"id":"LW-mfn-name","lv":"states","d":6,"area":"States and trade rules","q":"Which legal term means this? “A trade advantage given to one member must go to all at once”","o":["Transit passage","National treatment","Hull formula","Most-favoured-nation treatment"],"a":[3],"s":1,"x":"Most-favoured-nation treatment: a trade advantage given to one member must go to all at once. GATT 1947, art. I, the first rule of the WTO: no discrimination between trading partners. Exceptions: customs unions and free trade areas (art. XXIV) and preferences for developing countries. The US revoked Russia's in 2022.","about":["mfn"]},
{"id":"LW-national-treatment","lv":"states","d":5,"area":"States and trade rules","q":"What is meant by “National treatment”?","o":["once imported, goods must carry a label giving their country of origin","once imported, goods may be taxed only at the rate bound at the WTO","once imported, goods may be sold only by firms owned by locals","once imported, goods must fare no worse than local goods"],"a":[3],"s":1,"x":"National treatment: once imported, goods must fare no worse than local goods. GATT, art. III. Carbon border taxes and sustainability rules for biofuels must meet it, or be justified under the general exceptions of article XX.","about":["national-treatment"]},
{"id":"LW-national-treatment-name","lv":"states","d":6,"area":"States and trade rules","q":"Which legal term means this? “Once imported, goods must fare no worse than local goods”","o":["Most-favoured-nation treatment","Transit passage","Blocking statute","National treatment"],"a":[3],"s":1,"x":"National treatment: once imported, goods must fare no worse than local goods. GATT, art. III. Carbon border taxes and sustainability rules for biofuels must meet it, or be justified under the general exceptions of article XX.","about":["national-treatment"]},
{"id":"LW-blocking-statute","lv":"states","d":7,"area":"States and trade rules","q":"What is meant by “Blocking statute”?","o":["a law barring imports of goods made with forced labour","a law forbidding firms to obey another state's sanctions","a law freezing the assets of the persons on a sanctions list","a law letting a minister stop a foreign takeover of a firm"],"a":[1],"s":1,"x":"Blocking statute: a law forbidding firms to obey another state's sanctions. The EU's, Regulation 2271/96, was passed against US sanctions on Cuba, Iran and Libya and revived for Iran in 2018. A firm may not end a contract just to comply with US sanctions; if it seems to have, it must show otherwise (Bank Melli v Telekom Deutschland, ECJ, 2021).","about":["blocking-statute"]},
{"id":"LW-blocking-statute-name","lv":"states","d":8,"area":"States and trade rules","q":"Which legal term means this? “A law forbidding firms to obey another state's sanctions”","o":["Most-favoured-nation treatment","Separation of powers","Blocking statute","Anti-dumping"],"a":[2],"s":1,"x":"Blocking statute: a law forbidding firms to obey another state's sanctions. The EU's, Regulation 2271/96, was passed against US sanctions on Cuba, Iran and Libya and revived for Iran in 2018. A firm may not end a contract just to comply with US sanctions; if it seems to have, it must show otherwise (Bank Melli v Telekom Deutschland, ECJ, 2021).","about":["blocking-statute"]},
{"id":"LW-hull-formula","lv":"states","d":7,"area":"States and trade rules","q":"What is meant by “Hull formula”?","o":["an expropriating state owes nothing at all if it acts for a public purpose","an expropriating state owes only what its own courts find fair","an expropriating state owes the assets' book value, paid over years","an expropriating state owes prompt, adequate and effective compensation"],"a":[3],"s":1,"x":"Hull formula: an expropriating state owes prompt, adequate and effective compensation. Cordell Hull's note to Mexico in 1938 over its expropriations; Latin America answered with the Calvo doctrine (local courts only, and no better treatment for foreigners). Investment treaties now write the Hull standard in.","about":["hull-formula"]},
{"id":"LW-hull-formula-name","lv":"states","d":8,"area":"States and trade rules","q":"Which legal term means this? “An expropriating state owes prompt, adequate and effective compensation”","o":["Hull formula","Separation of powers","Anti-dumping","Blocking statute"],"a":[0],"s":1,"x":"Hull formula: an expropriating state owes prompt, adequate and effective compensation. Cordell Hull's note to Mexico in 1938 over its expropriations; Latin America answered with the Calvo doctrine (local courts only, and no better treatment for foreigners). Investment treaties now write the Hull standard in.","about":["hull-formula"]},
{"id":"LW-separation-of-powers","lv":"states","d":3,"area":"States and trade rules","q":"What is meant by “Separation of powers”?","o":["the central government and the regions each rule in their own sphere","law-making, governing and judging are kept in different hands","the state and the church keep out of each other's affairs","the courts may strike down any law that breaks the constitution"],"a":[1],"s":1,"x":"Separation of powers: law-making, governing and judging are kept in different hands. Montesquieu, The Spirit of the Laws (1748), drawing on England, and written into the US Constitution's three articles. Britain's own is looser: ministers sit in Parliament, and the Supreme Court has sat apart from the Lords only since 2009.","about":["separation-of-powers"]},
{"id":"LW-separation-of-powers-name","lv":"states","d":4,"area":"States and trade rules","q":"Which legal term means this? “Law-making, governing and judging are kept in different hands”","o":["Anti-dumping","Rule of law","Hull formula","Separation of powers"],"a":[3],"s":1,"x":"Separation of powers: law-making, governing and judging are kept in different hands. Montesquieu, The Spirit of the Laws (1748), drawing on England, and written into the US Constitution's three articles. Britain's own is looser: ministers sit in Parliament, and the Supreme Court has sat apart from the Lords only since 2009.","about":["separation-of-powers"]},
{"id":"LW-rule-of-law","lv":"states","d":3,"area":"States and trade rules","q":"What is meant by “Rule of law”?","o":["everyone, the state included, answers to known laws in the courts","the courts may make new law whenever parliament has stayed silent on it","a law passed by a majority binds even those who voted against","every law must first be approved by the people in a referendum"],"a":[0],"s":1,"x":"Rule of law: everyone, the state included, answers to known laws in the courts. Dicey's three senses (1885): no punishment but for a breach of law proved in court, everyone equal before the ordinary law, rights secured by the courts. Magna Carta's clause 39 is its oldest root.","about":["rule-of-law"]},
{"id":"LW-rule-of-law-name","lv":"states","d":4,"area":"States and trade rules","q":"Which legal term means this? “Everyone, the state included, answers to known laws in the courts”","o":["Anti-dumping","Hull formula","Frustration","Rule of law"],"a":[3],"s":1,"x":"Rule of law: everyone, the state included, answers to known laws in the courts. Dicey's three senses (1885): no punishment but for a breach of law proved in court, everyone equal before the ordinary law, rights secured by the courts. Magna Carta's clause 39 is its oldest root.","about":["rule-of-law"]},
{"id":"LW-separate-legal-personality","lv":"companies","d":3,"area":"Companies and agents","q":"What is meant by “Separate legal personality”?","o":["a company may act only in the ways its founding papers list","a company's directors own its assets on its members' behalf","a company has rights and debts of its own, apart from its owners","a company's owners answer for its debts up to their own wealth"],"a":[2],"s":1,"x":"Separate legal personality: a company has rights and debts of its own, apart from its owners. Salomon v A Salomon & Co (House of Lords, 1896; reported 1897): a one-man leather business was a company of its own, so its founder, a secured creditor, was paid ahead of the others. The veil is lifted only where a company is used to evade an existing obligation (Prest v Petrodel, 2013).","about":["separate-legal-personality"]},
{"id":"LW-separate-legal-personality-name","lv":"companies","d":4,"area":"Companies and agents","q":"Which legal term means this? “A company has rights and debts of its own, apart from its owners”","o":["Fiduciary duty","Documentary collection","Wrongful trading","Separate legal personality"],"a":[3],"s":1,"x":"Separate legal personality: a company has rights and debts of its own, apart from its owners. Salomon v A Salomon & Co (House of Lords, 1896; reported 1897): a one-man leather business was a company of its own, so its founder, a secured creditor, was paid ahead of the others. The veil is lifted only where a company is used to evade an existing obligation (Prest v Petrodel, 2013).","about":["separate-legal-personality"]},
{"id":"LW-ultra-vires","lv":"companies","d":3,"area":"Companies and agents","q":"What does this mean? “Ultra vires”","o":["an act done abroad, beyond the reach of the home courts","an act done in bad faith by a body's officer, and so voidable","an act beyond the powers a body has, and so without effect","an act a body may do only with a court's prior approval"],"a":[2],"s":1,"x":"Ultra vires: an act beyond the powers a body has, and so without effect. Literally: beyond the powers. Once fatal to companies' contracts; now a company's capacity can't be questioned because of its constitution (Companies Act 2006, s 39). It lives on in public law: a council's interest rate swaps were void (Hazell v Hammersmith and Fulham, 1991).","about":["ultra-vires"]},
{"id":"LW-ultra-vires-name","lv":"companies","d":4,"area":"Companies and agents","q":"Which legal term means this? “An act beyond the powers a body has, and so without effect”","o":["Ipso facto","Res nullius","Locus standi","Ultra vires"],"a":[3],"s":1,"x":"Ultra vires: an act beyond the powers a body has, and so without effect. Literally: beyond the powers. Once fatal to companies' contracts; now a company's capacity can't be questioned because of its constitution (Companies Act 2006, s 39). It lives on in public law: a council's interest rate swaps were void (Hazell v Hammersmith and Fulham, 1991).","about":["ultra-vires"]},
{"id":"LW-fiduciary-duty","lv":"companies","d":5,"area":"Companies and agents","q":"What is meant by “Fiduciary duty”?","o":["a duty to take the care a reasonable person would in the job","a duty of loyalty: no conflicts and no secret profit","a duty to carry out every lawful instruction of the board","a duty to keep the company's affairs secret from its rivals"],"a":[1],"s":1,"x":"Fiduciary duty: a duty of loyalty: no conflicts and no secret profit. Owed by trustees, directors, agents and partners: Keech v Sandford (1726) and Regal (Hastings) v Gulliver (1942) strip a fiduciary of its profit even where the principal lost nothing. Directors' duties are now in the Companies Act 2006, ss 171 to 177.","about":["fiduciary-duty"]},
{"id":"LW-fiduciary-duty-name","lv":"companies","d":6,"area":"Companies and agents","q":"Which legal term means this? “A duty of loyalty: no conflicts and no secret profit”","o":["Consideration","Bill of lading","Fiduciary duty","Undisclosed principal"],"a":[2],"s":1,"x":"Fiduciary duty: a duty of loyalty: no conflicts and no secret profit. Owed by trustees, directors, agents and partners: Keech v Sandford (1726) and Regal (Hastings) v Gulliver (1942) strip a fiduciary of its profit even where the principal lost nothing. Directors' duties are now in the Companies Act 2006, ss 171 to 177.","about":["fiduciary-duty"]},
{"id":"LW-apparent-authority","lv":"companies","d":5,"area":"Companies and agents","q":"What is meant by “Apparent authority”?","o":["an agent binds itself, not its principal, when it hides who it acts for","an agent binds its principal only within powers set down in writing","an agent binds its principal when it was held out as having power","an agent binds its principal when the principal approves the deal later"],"a":[2],"s":1,"x":"Apparent authority: an agent binds its principal when it was held out as having power. Freeman & Lockyer v Buckhurst Park Properties (1964): a director acting as managing director with the board's knowledge bound the company. The representation must come from the principal, not from the agent itself.","about":["apparent-authority"]},
{"id":"LW-apparent-authority-name","lv":"companies","d":6,"area":"Companies and agents","q":"Which legal term means this? “An agent binds its principal when it was held out as having power”","o":["Separate legal personality","Fiduciary duty","Apparent authority","Undisclosed principal"],"a":[2],"s":1,"x":"Apparent authority: an agent binds its principal when it was held out as having power. Freeman & Lockyer v Buckhurst Park Properties (1964): a director acting as managing director with the board's knowledge bound the company. The representation must come from the principal, not from the agent itself.","about":["apparent-authority"]},
{"id":"LW-delegatus","lv":"companies","d":7,"area":"Companies and agents","q":"What does this mean? “Delegatus non potest delegare”","o":["one entrusted with a power can't be removed before the term ends","one entrusted with a power answers for every act of those under it","one entrusted with a power must use it in person, never by letter","one entrusted with a power can't pass it on to another without leave"],"a":[3],"s":1,"x":"Delegatus non potest delegare: one entrusted with a power can't pass it on to another without leave. Literally: a delegate can't delegate. For agents, trustees, arbitrators and public bodies alike; a minister, though, may act through officials (Carltona v Commissioners of Works, 1943).","about":["delegatus"]},
{"id":"LW-delegatus-name","lv":"companies","d":8,"area":"Companies and agents","q":"Which legal term means this? “One entrusted with a power can't pass it on to another without leave”","o":["Par in parem non habet imperium","Nemo tenetur se ipsum accusare","Ex turpi causa non oritur actio","Delegatus non potest delegare"],"a":[3],"s":1,"x":"Delegatus non potest delegare: one entrusted with a power can't pass it on to another without leave. Literally: a delegate can't delegate. For agents, trustees, arbitrators and public bodies alike; a minister, though, may act through officials (Carltona v Commissioners of Works, 1943).","about":["delegatus"]},
{"id":"LW-qui-facit-per-alium","lv":"companies","d":5,"area":"Companies and agents","q":"What does this mean? “Qui facit per alium facit per se”","o":["an agent is personally bound by every contract it signs for another","a principal is bound by what its agent does on its behalf","a partner may act for the firm only with the other partners' consent","an employee who acts without orders answers alone for the act"],"a":[1],"s":1,"x":"Qui facit per alium facit per se: a principal is bound by what its agent does on its behalf. Literally: who acts through another acts himself. The root of agency and of vicarious liability. It cuts the other way too: some duties can't be escaped by handing them to another, such as an employer's to keep the workplace safe.","about":["qui-facit-per-alium"]},
{"id":"LW-qui-facit-per-alium-name","lv":"companies","d":6,"area":"Companies and agents","q":"Which legal term means this? “A principal is bound by what its agent does on its behalf”","o":["Qui facit per alium facit per se","Lex posterior derogat legi priori","Nemo tenetur se ipsum accusare","Causa proxima non remota spectatur"],"a":[0],"s":1,"x":"Qui facit per alium facit per se: a principal is bound by what its agent does on its behalf. Literally: who acts through another acts himself. The root of agency and of vicarious liability. It cuts the other way too: some duties can't be escaped by handing them to another, such as an employer's to keep the workplace safe.","about":["qui-facit-per-alium"]},
{"id":"LW-undisclosed-principal","lv":"companies","d":7,"area":"Companies and agents","q":"What is meant by “Undisclosed principal”?","o":["the hidden party behind an agent may sue and be sued on the contract","the hidden party behind an agent may cancel the deal at any time","the hidden party behind an agent is bound only once it's named","the hidden party behind an agent can't be sued, only the agent"],"a":[0],"s":1,"x":"Undisclosed principal: the hidden party behind an agent may sue and be sued on the contract. A common law oddity civil lawyers struggle with, and routine in commodity trading, where brokers and trading houses deal in their own names. The other side, on learning of the principal, may choose to sue either.","about":["undisclosed-principal"]},
{"id":"LW-undisclosed-principal-name","lv":"companies","d":8,"area":"Companies and agents","q":"Which legal term means this? “The hidden party behind an agent may sue and be sued on the contract”","o":["Anti-suit injunction","Apparent authority","Documentary collection","Undisclosed principal"],"a":[3],"s":1,"x":"Undisclosed principal: the hidden party behind an agent may sue and be sued on the contract. A common law oddity civil lawyers struggle with, and routine in commodity trading, where brokers and trading houses deal in their own names. The other side, on learning of the principal, may choose to sue either.","about":["undisclosed-principal"]},
{"id":"LW-del-credere","lv":"companies","d":7,"area":"Companies and agents","q":"What does this mean? “Del credere” (literally: of trust)","o":["an agent's loan to its principal against sales still to come","an agent's guarantee, for extra pay, that its buyers will pay","an agent's promise to sell only to buyers its bank approved","an agent's purchase on credit, paying the seller once it's paid"],"a":[1],"s":1,"x":"Del credere: an agent's guarantee, for extra pay, that its buyers will pay. Literally: of trust. From the Italian merchants; common in commodity and shipping agency, the extra commission paying for the risk of the buyer's default. The guarantee needs no writing, being part of the agency.","about":["del-credere"]},
{"id":"LW-del-credere-name","lv":"companies","d":8,"area":"Companies and agents","q":"Which legal term means this? “An agent's guarantee, for extra pay, that its buyers will pay”","o":["Res nullius","Del credere","Ultra vires","Lis pendens"],"a":[1],"s":1,"x":"Del credere: an agent's guarantee, for extra pay, that its buyers will pay. Literally: of trust. From the Italian merchants; common in commodity and shipping agency, the extra commission paying for the risk of the buyer's default. The guarantee needs no writing, being part of the agency.","about":["del-credere"]},
{"id":"LW-wrongful-trading","lv":"companies","d":7,"area":"Companies and agents","q":"What is meant by “Wrongful trading”?","o":["a director's liability for dealing in shares on inside information it holds","a director's liability for trading with a sanctioned country","a director's liability for running a business without a licence","a director's liability for carrying on when insolvency was unavoidable"],"a":[3],"s":1,"x":"Wrongful trading: a director's liability for carrying on when insolvency was unavoidable. Insolvency Act 1986, s 214: once a director knew or ought to have known that insolvent liquidation couldn't be avoided, it must take every step to minimise the creditors' loss. Fraudulent trading (s 213) needs dishonesty.","about":["wrongful-trading"]},
{"id":"LW-wrongful-trading-name","lv":"companies","d":8,"area":"Companies and agents","q":"Which legal term means this? “A director's liability for carrying on when insolvency was unavoidable”","o":["Wrongful trading","Letter of credit","Demand guarantee","Undisclosed principal"],"a":[0],"s":1,"x":"Wrongful trading: a director's liability for carrying on when insolvency was unavoidable. Insolvency Act 1986, s 214: once a director knew or ought to have known that insolvent liquidation couldn't be avoided, it must take every step to minimise the creditors' loss. Fraudulent trading (s 213) needs dishonesty.","about":["wrongful-trading"]}
];
